# include <stdio.h>

int main(){

    int n, k, count = 0;
    scanf("%d", &n);
    scanf("%d", &k);
    int i = 0, j = n -1;

    int a[100];

    for(i = 0; i < n; i++)
		scanf("%d", &a[i]);
    i = 0;
    while (i < j) {
      if (a[i] <= k) {++i; ++count;}
      if (a[j] <= k) {--j; ++count;}    
      if (a[i] > k & a[j] > k) break;
    }
    if ((i == j) & (a[i] <= k)) ++count;
    printf("%d", count);
    return 0; 
}

