            test[2]++;

        }
    }
    for(ct1 = 0 ; ct1 + 2 < length ; ct1++){
        if(name[ct1] == 'A' && name[ct1 +1 ] == 'n' && name[ct1 + 2] == 'n'  ){
            test[3]++;

        }
    }
    for(ct1 = 0 ; ct1 + 5 < length ; ct1++){
        if(name[ct1] == 'N' && name[ct1 +1 ] == 'i' && name[ct1 + 2] == 'k' && name[ct1 + 3] == 'i' && name[ct1 + 4] == 't' && name[ct1 + 5] == 'a'){
            test[4]++;

        }
    }
    if(test[0] + test[1] + test[2] + test[3] + test[4] == 1){
        printf("YES");
