#include<stdio.h>
#define MAX 987654321
int n;

int main()
{
	scanf("%d", &n);
	if (n < 3)    //when polygon has less than 3 points
		return 0;
	int table[501][501];

	for (int gap = 0; gap < n; gap++) {
		for (int i = 0, j = gap; j < n; i++, j++) {
			if (j < i + 2)
				table[i][j] = 0;
			else {
				table[i][j] = MAX;

				for (int k = i + 1; k < j; k++) {
					int val = table[i][k] + table[k][j] + (i+1)*(j+1)*(k+1);
					if (table[i][j] > val)
						table[i][j] = val;    //update table data to minimum value
				}
			}
		}
	}
	printf("%d\n", table[0][n - 1]);
	return 0;
}

