{
    char s[len * 2], s1[len + 1], s2[len + 1];

    scanf("%s", s);
    s1[len] = s2[len] = 0;

    qsort(strncpy(s1, s, len), len, sizeof(char), comp );
    qsort(strncpy(s2, s + len, len), len, sizeof(char), comp );

    for( int i = 0; i < len -1; i++ )
    {
        if ( comp(s1+i, s2+i) != comp(s1+i+1, s2+i+1)  || *(s1+i) == *(s2+i) )
        {
            puts("NO");
            return;
        }
    }

    if ( *(s1) == *(s2) )
        {
            puts("NO");
            return;
        }
    puts("YES");

}

