#define N	200

int max(int a, int b) { return a > b ? a : b; }

int main() {
	static char cc[N], cc_[2];
	static int dp[N + 1][N + 1], dq[N + 1][N + 1];
	int n, m, i, j, k, ans;

	scanf("%d%d%s%s", &n, &m, cc, cc_);
	for (j = 0; j <= m; j++)
		memset(dp, -1, (n + 1) * sizeof *dp);
	dp[0][0] = 0;
	for (i = 0; i < n; i++) {
		for (j = 0; j <= m; j++)
			memset(dq, -1, (n + 1) * sizeof *dq);
		for (j = 0; j <= m; j++)
			for (k = 0; k <= n; k++) {
				int j_, k_, x = dp[j][k];

				if (x == -1)
					continue;
				j_ = j, k_ = k;
				if (cc[i] == cc_[0])
					k_++;
				dq[j_][k_] = max(dq[j_][k_], x + (cc[i] == cc_[1] ? k : 0));
				if (j < m) {
					j_ = j + 1, k_ = k + 1;
					dq[j_][k_] = max(dq[j_][k_], x + (cc_[0] == cc_[1] ? k : 0));
					if (cc_[0] != cc_[1]) {
						j_ = j + 1, k_ = k;
						dq[j_][k_] = max(dq[j_][k_], x + k);
					}
				}
			}
		for (j = 0; j <= m; j++)
			memcpy(dp, dq, (n + 1) * sizeof *dq);
	}
	ans = -1;
	for (j = 0; j <= m; j++)
		for (k = 0; k <= n; k++)
			ans = max(ans, dp[j][k]);
	printf("%d\n", ans);
	return 0;
}

