#include <stdio.h>

#define N	250
#define MD	1000000007

long long power(int a, int k) {
	long long b = a, p = 1;

	while (k > 0) {
		if (k & 1)
			p = p * b % MD;
		b = b * b % MD;
		k >>= 1;
	}
	return p;
}

int ff[N + 1], gg[N + 1];

void init() {
	int i;
	long long f = 1;

	for (i = 0; i <= N; i++) {
		gg[i] = power(ff[i] = f, MD - 2);
		f = f * (i + 1) % MD;
	}
}

long long choose(int n, int k) {
	return (long long) ff[n] * gg[k] % MD * gg[n - k] % MD;
}

int main() {
	int n, k, r, ans;

	init();
	scanf("%d%d", &n, &k);
	ans = 0;
	for (r = 0; r <= n; r++)
		ans = (ans + (r % 2 == 0 ? 1 : -1) * choose(n, r) * power(power(k - 1, r) * (power(k, n - r) - power(k - 1, n - r)) % MD, n)) % MD;
	if (ans < 0)
		ans += MD;
	printf("%d\n", ans);
	return 0;
}

#include<stdio.h>
#define MOD 1000000007

int dar[252][252], k, n, fact[252], inv[252], precomp[2][252];

int add(int a, int b){
  a += b;
  if(a >= MOD)a -= MOD;
  return a;
}

int mul(int a, int b){
  return (a*1ll*b)%MOD;
}
int powmod(int base, long long p){
  int toret = 1;
  while(p){
    if(p&1)toret = mul(toret, base);
    base = mul(base, base);
    p >>= 1;
  }
  return toret;
}

int ncr(int n, int r){
  return mul(mul(fact[n], inv[r]), inv[n - r]);
}

int dp(int r, int c){
  //  printf("dp(%d, %d)\n", r, c);
  if(dar[r][c] == -1){
    int toret = 0;
    if(r == 0){
      dar[r][c] = (c == 0);
      return dar[r][c];
    }

    int sat = n - c;
    int i;
    for(i = 0;i <= c;i++)if(i + sat){
      int f1 = precomp[0][c - i];
      f1 = mul(f1, ncr(c, i));
      int f2 = precomp[1][sat];
      if(i == 0){
	f2 = add(f2, MOD - precomp[0][sat]);
      }
      toret = add(toret, mul(dp(r - 1, c - i), mul(f1, f2)));
    }
    dar[r][c] = toret;
  }
  return dar[r][c];
}

int main(){
  scanf("%d %d", &n, &k);
  if(k == 1){
    printf("1\n");
    return 0;
  }
  int i,j;
  fact[0] = 1;
  inv[0] = 1;
  precomp[0][0] = precomp[1][0] = 1;
  for(i = 1;i < 252;i++){
    fact[i] = mul(fact[i - 1], i);
    inv[i] = powmod(fact[i], MOD - 2);
    precomp[0][i] = powmod(k - 1, i);
    precomp[1][i] = powmod(k, i);
  }
  for(i = 0;i <= n;i++)for(j = 0;j <= n;j++){
      dar[i][j] = -1;
    }
  printf("%d\n", dp(n, n));
  return 0;
}

