#include <stdio.h>
#define MAX(a, b) (((a)>(b))?(a):(b))

char grid[3][4];

int adj(int x, int y){
    int i,j,max;
    char t;
    max=-1;
    t=grid[x][y];
    for(i=0; x+i<3&&grid[x+i][y]==t; ++i);
    max=MAX(max, i);
    for(i=0; x-i>-1&&grid[x-i][y]==t; ++i);
    max=MAX(max, i);
    for(j=0; y+j<3&&grid[x][y+j]==t; ++j);
    max=MAX(max, j);
    for(j=0; y-j<3&&grid[x][y-j]==t; ++j);
    max=MAX(max, j);
    for(i=0; x+i<3&&y+i<3&&grid[x+i][y+i]==t; ++i);
    max=MAX(max, i);
    for(i=0; x+i<3&&y-i>-1&&grid[x+i][y-i]==t; ++i);
    max=MAX(max, i);
    for(j=0; x-j>-1&&y+j<3&&grid[x-j][y+j]==t; ++j);
    max=MAX(max, j);
    for(j=0; x-j>-1&&y-j>-1&&grid[x-j][y-j]==t; ++j);
    max=MAX(max, j);
    return max;
}

int verdict(void){
    int i,j,p,d,f,s;
    d=f=s=0;
    for(i=0; i<3; ++i)
        for(j=0; j<3; ++j){
            if(grid[i][j]=='.')
                d=3;
            p=adj(i,j);
            if(p==3){
                if(grid[i][j]=='X')
                    f=1;
                else if(grid[i][j]=='0')
                    s=1;
            }
        }
    if(f&&s)
        d=-1;
    else if(f)
        d=1;
    else if(s)
        d=2;
    return d;
}

int place(void){
    int i,j,f,s;
    for(f=s=i=0; i<3; ++i)
        for(j=0; j<3; ++j){
            if(grid[i][j]=='X')
                ++f;
            else if(grid[i][j]=='0')
                ++s;
        }
    if(f==s)
        return 1;
    else if(f-s==1)
        return 2;
    else
        return 0;
}

