unsigned long long max_with_256(k_2, k_3, k_5, k_6) {
  unsigned long long min_32, min_256;
  min_256 = min(min(k_2, k_5), k_6);
  min_32 = min(k_2 - min_256, k_3);
  return 256 * min_256 + 32 * min_32;
}

unsigned long long max_with_32(k_2, k_3, k_5, k_6) {
  unsigned long long min_32, min_256;
  min_32 = min(k_2, k_3);
  min_256 = min(min(k_2 - min_32, k_5), k_6);
  return 256 * min_256 + 32 * min_32;
}

