#include <stdio.h>

#define MAXN 100002

#define R 0x1
#define B 0x2

unsigned char balls[MAXN+MAXN];

void solve(int prev, int r, int b, int *s1, int *s2) {
	int turn = 0x1;
	int curr;
	if (prev == R) r--;
	else b--;
	*s1 = 0;
	*s2 = 0;
	while (r + b > 0) {
		if (turn == 0) {
			if (prev == R) {
				if (r > 0) {
					r--;
					curr = R;
				}
				else if (b > 0) {
					b--;
					curr = B;
				}
			} else {
				if (b > 0) {
					b--;
					curr = B;
				} else if (r > 0) {
					r--;
					curr = R;
				}
			}
		} else {
			if (prev == R) {
				if (b > 0) {
					b--;
					curr = B;
				} else if (r > 0) {
					r--;
					curr = R;
				}
			} else {
				if (r > 0) {
					r--;
					curr = R;
				} else if (b > 0) {
					b--;
					curr = B;
				}
			}
		}

		if (prev == curr) ++(*s1);
		else ++(*s2);
		turn ^= 0x1;
		prev = curr;
	}
}

int main() {
	int s1, s2;
	int s3, s4;
	int r, b;
	scanf("%d %d", &r, &b);

	solve(R, r, b, &s1, &s2);
	solve(B, r, b, &s3, &s4);
	if (s1 > s3) {
		printf("%d %d\n", s1, s2);
	} else {
		printf("%d %d\n", s3, s4);
	}
	return 0;
}

