        for (j = 0; j <= c; j++)
        {
/*          if (i + 2 * j > n)
            {
                break;
            }*/
            count[i + 2 * j]++;
        }
    }
    for (i = 0; i <= a; i += 2)
    {
        if (n - i / 2 < 0)
        {
            break;
        }
