#include<stdio.h>
//成功了，感觉这还是最优策略问题
#define N 10
char grid[N+2][N+2];
int x[N*N];
int y[N*N];
int wolf;

int main() {
	int n,m;
	scanf("%d%d",&n,&m);
	int i,j;
	getchar();
	for(i=1;i<=n;i++){
		for(j=1;j<=m;j++){
			grid[i][j]=getchar();
		}
		getchar();
	}
	//四周都是狼，我可以避免一些边界检查
	for(j=0;j<=m+1;j++){
		grid[0][j]='W';
		grid[n+1][j]='W';
	}
	for(i=1;i<=n;i++){
		grid[i][0]='W';
		grid[i][m+1]='W';
	}
	/*
	for(i=0;i<=n+1;i++){
		for(j=0;j<=m+1;j++){
			printf("%c",grid[i][j]);
		}
		printf("\n");
	}
	*/

	wolf=0;
	for(i=1;i<=n;i++){
		for(j=1;j<=m;j++){
			if(grid[i][j]=='W'){
				x[wolf]=i;
				y[wolf]=j;
				wolf++;
			}
		}
	}
	int total=wolf;
	for(i=0;i<wolf;i++){
		int wx=x[i];
		int wy=y[i];
		//再吃右边的
		if(grid[wx][wy+1]=='P'){
			grid[wx][wy+1]='W';
		//先吃上边的
		}else if(grid[wx-1][wy]=='P'){
			grid[wx-1][wy]='W';
		//再吃左边的
		}else if(grid[wx][wy-1]=='P'){
			grid[wx][wy-1]='W';
			//由于我们是一层一层地吃，
			//所以，我们最后一个吃下面的！
			//可以先吃下面的，在吃右边的！
		}else if(grid[wx+1][wy]=='P'){
			grid[wx+1][wy]='W';
		}else{
			//这条狼没有吃到猪
			total--;
		}

	}
	//剩下的可以吃到猪的狼的个数
	printf("%d\n",total);
	return 0;
}

