#define IN_RANGE(v, s, e)   ( (s) <= (v) && (v) <= (e) )

#define IS_LOWER(c)         IN_RANGE(c, 'a', 'z')
#define IS_UPPER(c)         IN_RANGE(c, 'A', 'Z')

#define IS_ALPHA(c)         ( IS_UPPER(c) || IS_LOWER(c) )
#define IS_DIGIT(c)         IN_RANGE(c, '0', '9')
#define IS_ALNUM(c)         ( IS_ALPHA(c) || IS_DIGIT(c) )

#define TO_LOWER(c)         (IS_UPPER(c)) ? c += 32 : c ;
#define TO_UPPER(c)         (IS_LOWER(c)) ? c -= 32 : c ;

#define MAX_LINE            100u


uint8_t CountUpperCase(uint8_t * str, uint8_t str_len);
void ToUpperCase(uint8_t * str, uint8_t str_len);
void ToLowerCase(uint8_t * str, uint8_t str_len);


int main(void)
{
  uint8_t word[MAX_LINE] = {0};
  uint8_t str_len = 0u;
  uint8_t upper_case_count = 0u;

  scanf("%s", word);

  while(word[str_len]) str_len++;

  upper_case_count = CountUpperCase(word, str_len);

  if(upper_case_count > (str_len/2))
  {
    ToUpperCase(word, str_len);
  }
  else
  {
    ToLowerCase(word, str_len);
  } /*  end if  */

	printf("%s\n", word);

	return 0;
}


uint8_t CountUpperCase(uint8_t * str, uint8_t str_len)
{
  uint8_t upper_count = 0u;

  for(uint8_t i = 0u; i < str_len; i++)
  {
    if(IS_UPPER(str[i]))
    {
      upper_count++;
    } /*  end if    */

  } /*  end for   */

  return upper_count;
}

void ToUpperCase(uint8_t * str, uint8_t str_len)
{
  for(uint8_t i = 0u; i < str_len; i++)
  {
    if(IS_LOWER(str[i]))
    {
      str[i] = TO_UPPER(str[i]);
    } /*  end if  */
  } /*  end for   */
}

void ToLowerCase(uint8_t * str, uint8_t str_len)
{
  for(uint8_t i = 0u; i < str_len; i++)
  {
    if(IS_UPPER(str[i]))
    {
      str[i] = TO_LOWER(str[i]);
    } /*  end if  */
  } /*  end for   */
}

