    for(int i=0;i<n;i++)
        scanf(" %hu",&numberofBlocks[i]);

    for(short int column=n-2;column>-1;column--)
    {
        short int destination=column+1;
        if(numberofBlocks[destination]>=numberofBlocks[column])
            continue;

        while(1)
        {
            while(1)
            {
                if(numberofBlocks[destination+1]<numberofBlocks[column] && destination+1<n)
                    destination++;
                else
                    break;
            }

            //moving the block
            short int numberofBlocksMoved=numberofBlocks[column]-numberofBlocks[destination];
            numberofBlocks[destination]+=numberofBlocksMoved;
            numberofBlocks[column]-=numberofBlocksMoved;

            //reseting destination to next block
            destination=column+1;
            if(numberofBlocks[destination]>=numberofBlocks[column])
                break;
        }
    }

    for(int i=0;i<n;i++)
        printf("%d ",numberofBlocks[i]);
    printf("\n");

    return 0;
}

