void mirror(int a, int x, int y){
	if (a == 1 || a == 5){
		q1 = min(400, 2 * x + 1);
		for (int i = max(0, 2 * x - 399); i < q1; i++){
			for (int j = 0; j < 400; j++){
				sky[j][i] |= sky[j][2 * x - i];
			}
		}
	} else if (a == 3 || a == 7){
		q1 = min(400, 2 * y + 1);
		for (int i = max(0, 2 * y - 399); i < q1; i++){
			for (int j = 0; j < 400; j++){
				sky[i][j] |= sky[2 * y - i][j];
			}
		}
	} else if (a == 2 || a == 6){
		q1 = min(400, 400 + y - x);
		q2 = min(400, 400 - y + x);
		for (int i = max(0, y - x); i < q1; i++){
			for (int j = max(0, x - y); j < q2; j++){
				sky[i][j] |= sky[y - x + j][x - y + i];
			}
		}
	} else {
		q1 = min(400, x + y + 1);
		for (int i = max(0, y + x - 399); i < q1; i++){
			for (int j = max(0, x + y - 399); j < q1; j++){
				sky[i][j] |= sky[x + y - j][x + y - i];
			}
		}
	}
}

