#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node
{
  char val;
  struct Node *child;
  struct Node *next;
};

void tree(struct Node *root, char str[])
{
  int i;
  int length = strlen(str);

  if(length == 0)
    return;

  if(root->child == NULL)
    {
      root->child = (struct Node *)malloc(sizeof(struct Node));
      root->child->child = NULL;
      root->child->next = NULL;

      root->child->val = str[0];

      tree(root->child, &str[1]);
    }
  else
    {
      struct Node *prev = NULL;
      struct Node *cur = root->child;
      while(cur != NULL)
        {
          if(cur->val == str[0])
            break;
          else
            {
              prev = cur;
              cur = cur->next;
            }
        }

      if(cur != NULL)
        tree(cur, &str[1]);
      else
        {
          prev->next = (struct Node *)malloc(sizeof(struct Node));

          prev->next->child = NULL;
          prev->next->next = NULL;

          prev->next->val = str[0];

          tree(prev->next, &str[1]);
        }

    }

}

int countLeaves(struct Node *root)
{
  if(root->child == NULL)
    return 1;
  else
    {
      int cnt = 0;
      struct Node *cur = root->child;
      while(cur != NULL)
        {
          cnt += countLeaves(cur);
          cur = cur->next;
        }

      return cnt;
    }

}

