  root->child = NULL;
  root->next = NULL;

  for(i = 0; i < len; i++)
    {
      char cur[52];
      k = 0;
      for(j = len-i; j < len; j++)
        cur[k++] = str[j];

      for(j = 0; j < len-i; j++)
        cur[k++] = str[j];

      cur[len] = '\0';

      tree(root, cur);
    }

  printf("%d\n",countLeaves(root));

}

