void multiply(long long x[3][3],long long y[3][3],long long z[3][3]){
    z[1][1]=((x[1][1]*y[1][1])%mod+(x[1][2]*y[2][1])%mod)%mod;
    z[1][2]=((x[1][1]*y[1][2])%mod+(x[1][2]*y[2][2])%mod)%mod;
    z[2][1]=((x[2][1]*y[1][1])%mod+(x[2][2]*y[2][1])%mod)%mod;
    z[2][2]=((x[2][1]*y[1][2])%mod+(x[2][2]*y[2][2])%mod)%mod;
}

void powermatrix(long long x[3][3],long long n){
    while(n!=0){
        if(n%2==0){
            multiply(x,x,N);
            copymatrix(N,x);
            n=n/2;
        }
        else{
            multiply(x,Q,N);
            copymatrix(N,Q);
            n=n-1;
        }
    }
}

