int mark[110][110][110];
int memo[110][110][110];
char A[110];
int n, k;
int max(int a, int b){
	if(a > b) return a;
	return b;
}
int dp(int prev, int pos, int MAX){
	int d1, d2;
	if(pos == n) return MAX == k;
	if(mark[prev][pos][MAX]) return memo[prev][pos][MAX];
	mark[prev][pos][MAX] = 1;
	if(A[pos] == 'Y'){
		return memo[prev][pos][MAX] = dp(0, pos + 1, MAX);
	}else if(A[pos] == 'N'){
		return memo[prev][pos][MAX] = dp(prev + 1, pos + 1, max(MAX, prev + 1));
	}else{
		d1 = dp(0, pos + 1, MAX);
		d2 = dp(prev+1, pos+1, max(MAX, prev+1));
		return memo[prev][pos][MAX] = d1 || d2;
	}

}
