#include <stdio.h>

typedef struct
{
    long long int x;
    long long int y;
}Point; //Tipe data Point

int Absis(Point P) { return P.x; } //Absis dari titik P

int Ordinat(Point P) { return P.y; } //Ordinat dari titik P

int relative_direction(Point P1, Point P2)
{
    /*I.S P1 dan P2 merupakan titik terdefinisi
      F.S Keluarannya berupa kode yang menyatakan P2 di ... menurut P1
      1 = Utara
      2 = Antara Utara dan Timur
      3 = Timur
      4 = Antara Timur dan Selatan
      5 = Selatan
      6 = Antara Barat dan Selatan
      7 = Barat
      8 = Antara Barat dan Utara
    */

    //Algoritma
    if (Absis(P1) == Absis(P2)) //X nya sama, beda y. antara utara dan selatan
    {
        if ((Ordinat(P2) - Ordinat(P1)) > 0) return 1; //Utara
        else return 5;//Selatan
    }
    else if (Ordinat(P1) == Ordinat(P2)) //Ynya sama, beda x. antara Timur dan Barat
    {
        if ((Absis(P2) - Absis(P1)) > 0) return 3; //Timur
        else return 7; //Barat
    }
    else //Ketika miring (Absis dan Ordinat kedua titik tidak sama)
    {
        if (((Absis(P2) - Absis(P1)) > 0) && ((Ordinat(P2) - Ordinat(P1)) > 0)) //Kuadran 1
        {
            return 2;
        }
        else if (((Absis(P2) - Absis(P1)) < 0) && ((Ordinat(P2) - Ordinat(P1)) > 0)) //Kuadran 2
        {
            return 8;
        }
        else if (((Absis(P2) - Absis(P1)) < 0) && ((Ordinat(P2) - Ordinat(P1)) < 0)) //Kuadran 3
        {
            return 6;
        }
        else return 4;
    }
}

int Arah(Point A, Point B, Point C)
{
    /* I.S Point A,B,C terdefinisi
       F.S dapat ditentukan arah dari titik A ke titik C lewat B, 
       apakah LEFT (1), RIGHT(2), TOWARDS(3).   
    */
    int AB,BC;
    AB = relative_direction(A,B);
    BC = relative_direction(B,C);

if (AB == BC) return 3;
else
{
    if (AB == 1)
    {
        if (BC == 3) return 2; //Kanan
        else return 1;
    }
    else if (AB == 2)
    {
        if (BC == 4) return 2;
        else return 1;
    }
    else if (AB == 3)
    {
        if (BC == 5) return 2;
        else return 1;
    }
    else if (AB == 4)
    {
        if (BC == 6) return 2;
        else return 1;
    }
    else if (AB == 5) //balikan dari AB == 1
    {
        if (BC == 3) return 1;
        else return 2;
    }
    else if (AB == 6)
    {
        if (BC == 4) return 1;
        else return 2;
    }
    else if (AB == 7)
    {
        if (BC==5) return 1;
        else return 2;
    }
    else //Balikan dari AB == 4
    {
        if (BC==6) return 1;
        else return 2;
    }
}
}
