int main()
{
long long n,m,gmax,gmin,anterior,aux;
scanf("%lld%lld",&n,&m);
if(n==1)
{
    gmin=0;
    gmax=0;
}
else if(m==1)
{
    gmin=n*(n-1)/2;
    gmax=gmin;
}
else if(m==n)
{
    gmin=0;
    gmax=0;
}
else {
    gmax=n-m+1;
    gmax=gmax*(gmax-1)/2;
    if(n%m==0)
    {
        gmin=n/m;
        gmin=(gmin*(gmin-1)/2)*m;
    }
    else{
        gmin=n/m;
        anterior=n%m;
        if(anterior!=0)
        {
            aux=gmin;
            gmin=gmin*(gmin-1)/2*(m-anterior);
            aux=aux+1;
            gmin=gmin+aux*(aux-1)/2*(anterior);
        }
        else gmin=(gmin*(gmin-1)/2)*m;
       }
   }
    printf("%lld %lld\n",gmin,gmax);
    return 0;
}

