#define N	100

struct ball {
	int c, cnt;
} bb[N];

int count(struct ball *bb, int n, int i) {
	int l, r, k;

	k = bb[i].cnt;
	for (l = i - 1, r = i + 1; l >= 0 && r < n && bb[l].c == bb[r].c && bb[l].cnt + bb[r].cnt >= 3; l--, r++)
		k += bb[l].cnt + bb[r].cnt;
	return k;
}

