	l = -1;
	for (i = 0; i <= n; i++) {
		int c;

		if (i < n)
			scanf("%d", &c);
		if (i == n || c_ != c) {
			l++;
			if (i < n) {
				bb[l].cnt = 1;
				bb[l].c = (c_ = c);
			}
			c_ = c;
		} else
			bb[l].cnt++;
	}
	max = 0;
	for (i = 0; i < l; i++)
		if (bb[i].c == x && bb[i].cnt == 2) {
			cnt = count(bb, l, i);
