#define modd 1000000007
long long fast_expo(long long a,long long b)
{
	long long res=1;
	while(b>0)
	{
		if(b&1)
			res=(res*a)%modd;
		a=(a*a)%modd;
		b=b>>1;
	}
	return res;
}
int main()
{
	long long fact[200001];
	int i,n;
	fact[0]=1;
	for(i=1;i<200001;i++)
		fact[i]=(fact[i-1]*i)%modd;
	while(scanf("%d",&n)==1)
	{
		long long ans=(fact[(n<<1)-1]*((fast_expo(fact[n],modd-2)*fast_expo(fact[n-1],modd-2))%modd))%modd;
		ans=(ans<<1)-n;
		if(ans<0)
			printf("%I64d\n",(ans+modd)%modd);
		else printf("%I64d\n",ans%modd);
	}
	return 0;
}

