long long solve(long long n)
{
	long long i = 1;
	long long count = 0;
	long long div = 1;
	long long mult = 1;

	//4 = 4*1
	//10 = 9*1 + 1*2
	//11 = 9*1 + 2*2
	//100 = 9*1 + 90*2 + 1*3
	//1000 = 9*1 + 90*2 + 900*3 + 1*4
	//55 = 9*1 + 46*2

	while (n > 0)
	{
		if (n < 9*mult)
		{
			count = count + n * i;
			n = n - n;
		}
		else
		{
			n = n - (9 * mult);
			count = count + (9 * mult * i);
			mult = mult * 10;
			i++;
		}
	}

	return count;
}

