#include <stdio.h>
#include <stdlib.h>

int main()
{
    int n, c, i, sum1 = 0, sum2 = 0;
    scanf("%d%d", &n, &c);
    int p[n], t[n], t1[n], t2[n];
    for(i = 0; i < n; i++)
        scanf("%d", &p[i]);
    for(i = 0; i < n; i++)
    {
        scanf("%d", &t[i]);
        t1[i] = t[i];
        t2[i] = t[i];
    }
    for(i = 1; i < n; i++)
        t1[i] += t1[i-1];
    for(i = n - 1; i > 0; i--)
        t2[i-1] += t2[i];
    for(i = 0; i < n; i++)
        if(p[i] - c * t1[i] > 0)
            sum1 = sum1 + p[i] - c * t1[i];
    for(i = n; i > 0; i--)
        if(p[i-1] - c * t2[i-1] > 0)
            sum2 = sum2 + p[i-1] - c * t2[i-1];
    if(sum1 > sum2)
        printf("Limak");
    if(sum1 == sum2)
        printf("Tie");
    if(sum1 < sum2)
        printf("Radewoosh");
