long long int calc(long long int n,long long int r){
    long long int sub = n - r,i;
    long long int result = 1;
    for(i=0;i<sub;i++){
        result = result * n;
        n--;
    }
    for(i=1;i<sub;i++){
        result = result / (i+1);
    }
    return result;
}
