typedef long long slong;
slong mod=1e9+7;
slong quick_power(slong a,slong b){
    slong res=1;
    while(b!=0){
        if(b&1){
            res=res*a%mod;
        }
        a=a*a%mod;
        b>>=1;
    }
    return res;
}
