/* upsolve with Dukkha */
#include <stdio.h>

#define N	1000000
#define MD	1000000007

long long ff[N], gg[N], pn[N], pm[N];

long long power(long long a, int k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k / 2);
	p = p * p % MD;
	if (k % 2)
		p = p * a % MD;
	return p;
}

void init(int n, int m) {
	long long f, p;
	int i;

	f = 1;
	for (i = 0; i < N; i++) {
		ff[i] = f;
		gg[i] = power(f, MD - 2);
		f = f * (i + 1) % MD;
	}
	p = 1;
	for (i = 0; i < n; i++) {
		pn[i] = p;
		p = p * n % MD;
	}
	p = 1;
	for (i = 0; i < n; i++) {
		pm[i] = p;
		p = p * m % MD;
	}
}

long long cayley(int n, int k) {
	return k == n ? 1 : k * pn[n - k - 1] % MD;
}

int main() {
	int n, m, a, b, k;
	long long ans;

	scanf("%d%d%d%d", &n, &m, &a, &b);
	init(n, m);
	ans = 0;
	for (k = 0; k <= n - 2 && k < m; k++) {
		/* choose(n - 2, k) * factorial(k) */
		long long path = ff[n - 2] * gg[n - 2 - k] % MD;
		/* choose(m - 1, k) * power(m, n - k - 2) */
		long long edges = ff[m - 1] % MD * gg[k] % MD * gg[m - 1 - k] % MD
			* pm[n - k - 2] % MD;

		ans = (ans + path * cayley(n, k + 2) % MD * edges) % MD;
	}
	printf("%lld\n", ans);
	return 0;
}

