double square,triangle,d_tri;

int putting_pole(double remain,int count);


int main(void){
  int r,h,maxnum,n,count;
  double l;
  scanf("%d %d",&r,&h);
  square=r;
  triangle=sqrt(3)*r/2;
  d_tri=2*triangle;
  l=h-triangle;
  count=3;
  //printf("3:%f\n",l);
  n=putting_pole(l,count);
  maxnum=n;
  l=h-(double)r/2;
  count=2;
  //printf("2:%f\n",l);
  n=putting_pole(l,count);
  if(n>maxnum) maxnum=n;
  if(!n) maxnum=1;
  printf("%d\n",maxnum);
  return 0;
}

int putting_pole(double remain,int count){
  int x,y,z;
  int max=0,num;

  if(remain<0) return 0;

  for(x=remain/d_tri;x>=0;x--){
    y=(remain-x*d_tri)/square;
    z=(remain-x*d_tri-y*square>=triangle)?1:0;
    num=3*x+2*y+z;
    if(num>max) max=num;
  } 
  return max+count;
}

