int qs(int a[],int n,int m)
{
	int i=n,j=m,k=a[i];
	if(n>=m)return 0;
	while(i<j)
	{
		while(i<j&&a[j]>k)j--;
		if(i<j)a[i++]=a[j];
		while(i<j&&a[i]<k)i++;
		if(i<j)a[j--]=a[i];
	}
	a[i]=k;
	qs(a,n,i-1);
	qs(a,i+1,m);
	return 0;
}
