int calc(char *s) {
    int i, len = strlen(s), result = 0;
    for (i = 0; i + 1 < len; i++) {
        result += s[i] == 'V' && s[i+1] == 'K';
    }
    return result;
}

int main() {
    char s[101];
    scanf("%s", s);
    int i, val, len = strlen(s), ans = calc(s);
    for (i = 0; i < len; i++) {
        s[i] = s[i] == 'K' ? 'V' : 'K';
        val = calc(s);
        if (val > ans) {
            ans = val;
        }
        s[i] = s[i] == 'K' ? 'V' : 'K';
    }
    printf("%d\n", ans);
    return 0;
}

