int main()
{
    int n,q=0,w=0;
    scanf("%d",&n);
    char c[n];
    scanf("%s",c);
    int l=0;
    while(c[l]!='\0')
        l++;
    if(c[0]==c[1]&&c[0]!='?')
        w=1;
    if(c[0]=='?'||c[l-1]=='?')
        q++;
    for(int i=1;c[i+1]!='\0'&&w<1;i++)
    {
        if(c[i]=='?')
        {
            if(c[i-1]==c[i+1])
                q++;

            if(c[i-1]==c[i] || c[i+1]==c[i])
                q++;
        }
        else
        {
            if(c[i+1]==c[i]||c[i-1]==c[i])
                w++;
        }
    }
    if(w==0&&q>0)
        printf("Yes");
    else
        printf("No");

    return 0;
}

