int full_leftdiag(int temp1,int temp2,int r2,int c2)
{
	int i,j;
	for(i=temp1,j=temp2;i>=1 && j>=1;--i,--j)
		if(i==r2 && j==c2)
			return 2;
	for(i=temp1,j=temp2;i<=8 && j<=8;++i,++j)
		if(i==r2 && j==c2)
			return 2;
	return 0;
}
int full_rightdiag(int temp1,int temp2,int r2,int c2)
{
	int i,j;
	for(i=temp1,j=temp2;i<=8 && j>=1;++i,--j)
		if(i==r2 && j==c2)
			return 2;
	for(i=temp1,j=temp2;i>=1 && j<=8;--i,++j)
		if(i==r2 && j==c2)
			return 2;
	return 0;
}
int right_diag(int r1,int c1,int r2,int c2)    //diagonals starting from right
{
	int temp1,temp2,ct;
	for(temp1=r1+1,temp2=c1-1;temp1<=8 && temp2>=1;++temp1,--temp2)
	{
		if(temp1==r2 && temp2==c2)
			return 1;
		ct=full_leftdiag(temp1,temp2,r2,c2);
		if(ct!=0)
			return ct;
	}
	for(temp1=r1-1,temp2=c1+1;temp1>=1 && temp2<=8;--temp1,++temp2)
	{
		if(temp1==r2 && temp2==c2)
			return 1;
		ct=full_leftdiag(temp1,temp2,r2,c2);
		if(ct!=0)
			return ct;
	}
	return 0;
}
int left_diag(int r1,int c1,int r2,int c2)   //diagonals starting from left
{
	int temp1,temp2,ct;
	for(temp1=r1+1,temp2=c1+1;temp1<=8 && temp2<=8;++temp1,++temp2)
	{
		if(temp1==r2 && temp2==c2)
			return 1;
		ct=full_rightdiag(temp1,temp2,r2,c2);
		if(ct!=0)
			return ct;
	}
	for(temp1=r1-1,temp2=c1-1;temp1>=1 && temp2>=1;--temp1,--temp2)
	{
		if(temp1==r2 && temp2==c2)
			return 1;
		ct=full_rightdiag(temp1,temp2,r2,c2);
		if(ct!=0)
			return ct;
	}
	return 0;
}
int bishop(int r1,int c1,int r2,int c2)
{
	int ct;
	ct=left_diag(r1,c1,r2,c2);
	if(ct!=0)
		return ct;
	else
		ct=right_diag(r1,c1,r2,c2);
	return ct;
}
