static inline uLL sqrt64(uLL x)
{
    uLL t,g;
    for (g=(x>>1)+(x&1),t=x;g<t;g=(g+x/g)>>1)
    {
        t=g;
    }
    return t;
}
static inline uLL gcd(uLL a,uLL b)
{
    while (a>0)
    {
        b=(b%a)^a;
        a=a^b;
        b=a^b;
    }
    return b;
}
uLL prime[4000001];
uLL EulerSieve(uLL n)
{
    uLL i,j;
    memset(prime,0,sizeof(*prime)*(n+1));
    *prime=0;
    for (i=2;i<=n;i++)
    {
        if (prime[i]==0)
        {
            prime[++(*prime)]=i;
            prime[i]=i;
        }
        for (j=1;j<=*prime;j++)
        {
            if (i*prime[j]>n) {break;}
            prime[i*prime[j]]=prime[j];
            if (prime[i]==prime[j]) {break;}
        }
    }
    return *prime;
}
uLL fac[10000];
uLL times[10000];
uLL factoring(uLL a,uLL *fac,uLL *times)
{
	uLL k,i,l;
	l=sqrt64(a);
	for (k=0,i=1;(i<=prime[0])&&(prime[i]<=l);i++)
	{
		if (a%prime[i]==0)
		{
			fac[++k]=prime[i];
			times[k]=1;
			for (a=a/prime[i];a%prime[i]==0;a=a/prime[i],times[k]+=1);
		}
	}
	if (a>1)
	{
		fac[++k]=a;
		times[k]=1;
	}
	return k;
}
