double zero = 0;
double square_root(double num)
{
    if(num < 0){
        return 0 / zero;
    }
    double root = 1;
    while(num >= 100){
        num /= 100;
        root *= 10;
    }
    while(num < 1){
        num *= 100;
        root /= 10;
    }
    double d = (1 + num) / 2;
    int i = 0;
    do{
        d = (d + num / d) / 2;
        i++;
    }while(i < 50);
    return d * root;
}
