long long int powerModulo(long long int a, long long int p, long long int m)
{   
    if(p==0)
        return 1;

    long long int temp = powerModulo(a, p/2, m);
    temp = (temp * temp)%m;
    if(p%2 == 0)
        return temp;
    else
        return (a * temp)%m;
}

long long int inverseModulo(long long int a, long long int P)
{
    return powerModulo(a, P-2, P);
}

int isGood(int n, int a, int b)
{
    while(n > 0)
    {
        int last = n%10;
        if(last == a || last == b)
            n = n/10;
        else
            return 0;
    }
    return 1;
}

int main()
{
    int a, b, n;
    scanf("%d %d %d", &a, &b, &n);

    long long int P = 1000000007;
    int N_MAX = 1000000;

    long long int *factorial_inverse;
    factorial_inverse = (long long int*)(malloc(sizeof(long long int) * (N_MAX + 1) ));
    factorial_inverse[0] = 1;

    for(int i = 1; i <= N_MAX; i++)
        factorial_inverse[i] = (inverseModulo(i, P) * factorial_inverse[i - 1])%P;

    long long int n_factorial = 1;
    for(int i = 2; i <= n; i++)
    {
        n_factorial = (n_factorial * i)%P;
    }

    long long int ans = 0;
    for(int num_of_a = 0; num_of_a <= n; num_of_a++)
    {
        int sum_of_digits = num_of_a * a + ( n - num_of_a ) * b;
        if(!isGood(sum_of_digits, a, b))
            continue;

        long long int temp = (factorial_inverse[n - num_of_a] * factorial_inverse[num_of_a])%P;
        temp = (n_factorial * temp)%P;
        ans = (ans + temp)%P;
    }
    printf("%lld\n", ans);
}

