int substring(char arr[]){
    int i,temp,sum=0,temp1;
    for(i=0;i<4;i++){
        if(greeting[i] != arr[i]){
            if(greeting[i] < arr[i]){
                temp = abs(greeting[i]-arr[i]);
                temp1 = 1 + abs('Z' - arr[i]) + abs('A' - greeting[i]);
                if(temp<temp1)
                    sum += temp;
                else
                    sum += temp1;
            }
            else{
                temp = abs(greeting[i]-arr[i]);
                temp1 = 1 + abs('A' - arr[i]) + abs('Z' - greeting[i]);
                if(temp<temp1)
                    sum += temp;
                else
                    sum += temp1;
            }
        }
    }
    return sum;
}

