#define BASE "%ld"

typedef long int Base;

int main()
{
	Base InitialNumber = 0;
	Base DesiredNumber = 0;
	Base PredictedSteps = 0;
	Base ActualSteps = 0; 

	scanf(BASE BASE, &InitialNumber, &DesiredNumber);

	if (DesiredNumber % InitialNumber) {
		ActualSteps = -1;	
	}
	else 
	{
		PredictedSteps = DesiredNumber / InitialNumber;	

		while (PredictedSteps % 3 == 0) 
		{
			ActualSteps++;
			PredictedSteps /= 3;
		}

		while (PredictedSteps % 2 == 0)
		{
			ActualSteps++;
			PredictedSteps /= 2;
		}

		if (PredictedSteps != 1) 
		{
			ActualSteps = -1;	
		}
	}

	printf(BASE"\n", ActualSteps);

	return 0;
}

