#include <stdio.h>
#include <memory.h>

#define DATA_SIZE 2005
#define MODULE 1000000007

long long dp[DATA_SIZE][DATA_SIZE];

int main()
{
	int n, k;
	scanf("%d %d", &n, &k);
	memset(dp, 0, sizeof(dp));
	for (int i = 1; i <= n; i++)
	{
		dp[i][1] = 1;
	}
	for (int i = 1; i <= n; ++i)
	{
		for (int kk = 2; kk <= k; ++kk)
		{
			for (int j = i; j <= n; j += i)
			{
				dp[j][kk] = (dp[j][kk] + dp[i][kk - 1]) % MODULE;
			}
		}
	}

	long long res = 0;
	for (int i = 1; i <= n; ++i)
	{
		res += dp[i][k];
	}
	printf("%I64d", res % MODULE);
	return 0;
}

