uint64_t count(uint64_t s, uint64_t x)
{
    if ((!s && !x))
        return 1;
    if ((s & 1) ^ (x & 1))
        return 0;

    if ((s & 1))
        return 2*count(s >> 1, x >> 1);
    return count(s >> 1, x >> 1) + count((s >> 1)-1, x >> 1);
}


int main(int argc, char *argv[])
{
    uint64_t s, x;
    scanf("%"PRIu64" %"PRIu64"", &s, &x);
    printf("%"PRIu64"\n", count(s, x) - 2*(s == x));
    return 0;
}

