int isZero(double i)
{
	if(fabs(i)<1e-6)
		return 1;
	return 0;
}

int isRon(double a,double b,double c,double d,double e,double f)
{
	double result;
	if(isZero(d))
		return 0;
	else
	{
		if(isZero(c))
			return 1;
		else
		{
			if(isZero(b))
				return 0;
			else
			{
				if(isZero(a))
					return 1;
				else
				{
					if(isZero(f))
						return 0;
					else
					{
						if(isZero(e))
							return 1;
						else
						{
							result=(b*d*f)/(a*c*e);
							if((result<1)||isZero(result-1))
								return 0;
							return 1;
						}
					}
				}
			}
		}
	}
}

