#include <stdio.h>
#include <stdlib.h>

struct vertex {
	struct coordinate {
		int x, y;
	} c;
	char has_x, has_y;
} vertices[4];

int compare(const void *a, const void *b) {
	struct vertex pa = *(struct vertex *) a;
	struct vertex pb = *(struct vertex *) b;

	return pa.c.x != pb.c.x ? pa.c.x - pb.c.x : pa.c.y - pb.c.y;
}

struct vertex *lookup(int x, int y, int vcnt) {
	int i;

	for (i = 0; i < vcnt; i++)
		if (vertices[i].c.x == x && vertices[i].c.y == y)
			return vertices + i;
	return NULL;
}

int rect1() {
	char good = 1;
	int i, x1, y1, x2, y2, vcnt = 0;
	struct vertex *v1, *v2;

	for (i = 0; i < 4; i++) {
		scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
		if ((x1 != x2 && y1 != y2) || (x1 == x2 && y1 == y2))
			good = 0;

		if ((v1 = lookup(x1, y1, vcnt)) == NULL)
			if (vcnt == 4)
				good = 0;
			else {
				v1 = vertices + vcnt;
				vertices[vcnt].c.x = x1, vertices[vcnt].c.y = y1;
				vertices[vcnt].has_x = 0, vertices[vcnt].has_y = 0;
				vcnt++;
			}
		else if ((x1 == x2 && v1->has_x) || (y1 == y2 && v1->has_y))
			good = 0;
		if ((v2 = lookup(x2, y2, vcnt)) == NULL)
			if (vcnt == 4)
				good = 0;
			else {
				v2 = vertices + vcnt;
				vertices[vcnt].c.x = x2, vertices[vcnt].c.y = y2;
				vertices[vcnt].has_x = 0, vertices[vcnt].has_y = 0;
				vcnt++;
			}
		else if ((x1 == x2 && v2->has_x) || (y1 == y2 && v2->has_y))
			good = 0;

		if (x1 == x2 && good && !v1->has_x && !v2->has_x) {
			v1->has_x = 1;
			v2->has_x = 1;
		} else if (y1 == y2 && good && !v1->has_y && !v2->has_y) {
			v1->has_y = 1;
			v2->has_y = 1;
		}
	}
	if (vcnt < 4)
		return 0;
	return good;
}

int rect2(struct vertex *v) {
	qsort(v, 4, sizeof(struct vertex), compare);
	return v[1].c.x == v[0].c.x && v[1].c.y == v[3].c.y
		&& v[2].c.x == v[3].c.x && v[2].c.y == v[0].c.y;
}

int main() {
	if (rect1() && rect2(vertices))
		printf("YES\n");
	else
		printf("NO\n");
	return 0;
}

