#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>


#define MAX(X, Y) (((X) > (Y)) ? (X) : (Y))

typedef long long llong;


bool enough(llong v, int cx, int cy, int x, int y) {
	llong for_neither = v / (x*y);
	llong for_x = v / y - for_neither, 
		 for_y = v / x - for_neither;

	llong for_both = v - (for_x + for_y + for_neither);

	return for_both - (MAX(cx - for_x, 0) + MAX(cy - for_y, 0)) >= 0L;
}



llong solve(int cx, int cy, int x, int y) {

	llong l = 1;
	llong r = MAX(cx, cy);
	while (!enough(r, cx, cy, x, y)) {
		r *= 2;
	}

	while (l < r) {
		llong m = (l + r) / 2;
		if (enough(m, cx, cy, x, y)) {
			r = m;
		}
		else {
			l = m + 1;
		}
	}

	return r;
}


int main(int argc, char **argv) {

	int cx, cy, x, y;
	while (scanf("%d %d %d %d", &cx, &cy, &x, &y) != EOF) {
