/* practice with Dukkha */
#include <stdio.h>

#define N	20
#define MD	1000000007

int d_, x_, y_;

void gcd_(int a, int b) {
	if (b == 0)
		d_ = a, x_ = 1, y_ = 0;
	else {
		int tmp;

		gcd_(b, a % b);
		tmp = x_ - a / b * y_, x_ = y_, y_ = tmp;
	}
}

int inv[N];

void init() {
	int k;

	for (k = 1; k < N; k++) {
		gcd_(k, MD);
		if (x_ < 0)
			x_ += MD;
		inv[k] = x_;
	}
}

long long ch(long long n, int k) {
	return k == 0 ? 1 : ch(n - 1, k - 1) * (n % MD) % MD * inv[k] % MD;
}

int main() {
	static long long ff[N];
	int n, b, i, ans;
	long long s;

	init();
	scanf("%d%lld", &n, &s);
	for (i = 0; i < n; i++)
		scanf("%lld", &ff[i]);
	ans = 0;
	for (b = 0; b < 1 << n; b++) {
		long long t;
		int k;

		t = s;
		k = 0;
		for (i = 0; i < n; i++)
			if (b & 1 << i) {
				k++;
				t -= ff[i] + 1;
			}
		if (t >= 0) {
			int cnt = ch(t + n - 1, n - 1);

			ans = (ans + (k % 2 == 0 ? cnt : -cnt)) % MD;
		}
	}
	if (ans < 0)
		ans += MD;
	printf("%d\n", ans);
	return 0;
}

