#include<stdio.h>
double pri(double w,double b);
double dra(double w,double b);
double pria[1000][1000]={0};
double draa[1000][1000]={0};
int main(){
int w,b;
scanf("%d%d",&w,&b);
printf("%.9lf\n",pri((double)w,(double)b));
return 0;
}

double pri(double w,double b){
if(pria[(int)(w-1)][(int)(b-1)]!=0)return pria[(int)(w-1)][(int)(b-1)];
if(w==0)return 0;
else if(b==0)return 1;
pria[(int)(w-1)][(int)(b-1)]=(w/(w+b))+(b/(w+b))*dra(w,b-1);
return pria[(int)(w-1)][(int)(b-1)];
}

double dra(double w,double b){
if(draa[(int)(w-1)][(int)(b-1)]!=0)return draa[(int)(w-1)][(int)(b-1)];
if(b==0)return 0;
else if(w==1&&b==1)return 0;
else if(b==1)return 1/(1+w);
draa[(int)(w-1)][(int)(b-1)]=(b/(b+w))*( (w/(b+w-1))*pri(w-1,b-1) + ((b-1)/(b+w-1))*pri(w,b-2) );
return draa[(int)(w-1)][(int)(b-1)];
}

