double chances_turno_princesa[1001][1001];
double chances_turno_dragao[1001][1001];

double calcula_prob_princesa(int w, int b);
double calcula_prob_dragao(int w, int b);

// Prob. da princesa ganhar se turno é da princesa com w, b
double calcula_prob_princesa(int w, int b) {
	if (w <= 0)
		return 0.;

	if (b <= 0)
		return 1.;

	if (!chances_turno_princesa[w][b])
		chances_turno_princesa[w][b] = ((double) w / ((double) w + b)) + ((double) b / ((double) w + b)) * calcula_prob_dragao(w, b - 1);

	//printf("Prob. princesa: %d %d %f\n", w, b, chances_turno_princesa[w][b]);
	return chances_turno_princesa[w][b];
}

// Prob. da princesa ganhar se turno é do dragão com w, b
double calcula_prob_dragao(int w, int b) {
	if (w <= 0)
		return 0.;

	if (b <= 0.)
		return 0.;

	if (!chances_turno_dragao[w][b]) {
		double ans = ((double) b) / ((double) w + b);	// chance de tirar b

		ans = ans * ((((double) b - 1) / ((double) w + b - 1)) * calcula_prob_princesa(w, b - 2) +
			(((double) w) / ((double) w + b - 1)) * calcula_prob_princesa(w - 1, b - 1));

		chances_turno_dragao[w][b] = ans;
	}

	//printf("Prob. dragão: %d %d %f\n", w, b, chances_turno_dragao[w][b]);
	return chances_turno_dragao[w][b];
}

int main() {
	int w, b;
	double ans = 0, prob_estado = 1;

	memset(chances_turno_princesa, 0, sizeof(chances_turno_princesa));
	memset(chances_turno_dragao, 0, sizeof(chances_turno_dragao));

	scanf("%d%d", &w, &b);

	printf("%.9lf\n", calcula_prob_princesa(w, b));
	return 0;
}

