long arr[N];

long calc(int sz) {
    if (arr[sz] != -1) return arr[sz];
    arr[sz] = 2 * calc(sz-1) + 1;
    return arr[sz];
}

int getval(long n, int sz, long idx) {
    if (n == 0 || n == 1) return (int)n;
    long t = calc(sz - 1);
    if (idx == t + 1) return (n & 1);
    if (idx <= t) return getval((n >> 1), sz - 1, idx);
    else return getval((n >> 1), sz - 1, idx - t - 1);
}

