#define MOD 1000000007ULL

static inline uint64_t pow_mod(int64_t a, int64_t pow, int64_t mod) {
    if(pow == 0) return 1;
    while(pow % 2 == 0) { a = (a*a) % mod; pow /= 2; }
    int64_t ret = a; pow /= 2;
    while(pow) {
        a = (a*a) % mod;
        if(pow % 2 != 0) ret = (ret*a) % mod;
        pow /= 2;
    }
    return ret;
}

// lets consider line of len M. To have product to be 1 we need even count of -1, and for -1 odd count of -1
// if we consider first M-1 numbers, disregarding how we pick them we can always "fix" it with the last one
// so count(M) = 2^(M-1)
// similarly for N > 1 rows we can pick N-1 however we want and "fix it" with the last one
// but this is only possible if N,M have same parity
// 2 ^ [(N-1)*(M-1)] = [([2^(N-1)] mod M) ^ (M-1)] mod M

int main() {
    uint64_t N,M; int K; scanf("%"PRIu64 "%"PRIu64 "%d\n", &N,&M,&K);
    if(N % 2 != M % 2 && K == -1) { printf("0\n"); return 0; }
    printf("%"PRIu64 "\n", pow_mod(pow_mod(2,M-1,MOD), N-1,MOD));
    return 0;
}

