#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX 2000010
#define MOD 1000000007
#define clr(ar) memset(ar, 0, sizeof(ar))
#define read() freopen("lol.txt", "r", stdin)

short len[MAX];
char mu[MAX], flag[MAX];
int prime[MAX], dp[MAX], sum[MAX], power[MAX], L[MAX], *divisors[MAX];

int expo(int a, int b){
    int res = 1;

    while (b){
        if (b & 1) res = (long long)res * a % MOD;
        a = (long long)a * a % MOD;
        b >>= 1;
    }
    return res;
}

void mobius(){
    mu[1] = 1;
    int i, j, k, p = 0;

    for (i = 2; i < MAX; i++){
        if (!flag[i]) mu[i] = -1, prime[p++] = i;
        for (j = 0; j < p && (k = i * prime[j]) < MAX; j++){

            flag[k] = true;
            if (!(i % prime[j])){
                mu[k] = 0;
                break;
            }
            else mu[k] -= mu[i];
        }
    }
    for (i = 1; i < MAX; i++) sum[i] = sum[i - 1] + mu[i];
}

void generate(){
    mobius();
    int i, j, k, c, d, x;

    len[0] = len[1] = L[0] = L[1] = 1;
    for (i = 4; i < MAX; i++, i++) len[i] = 2;

    for (i = 3; (i * i) < MAX; i += 2){
        if (!len[i]){
            for (j = (i * i), d = i << 1; j < MAX; j += d){
                if (!len[j]) len[j] = i;
            }
        }
    }

    for (i = 2; i < MAX; i++){
        if (!len[i]) L[i] = i;
        else{
            L[i] = len[i];
            x = L[i /len[i]];
            if (x > L[i]) L[i] = x;
        }
    }

    divisors[1] = (int *) malloc(sizeof(int));
    divisors[1][0] = 1, len[1] = 1;

    for (i = 2; i < MAX; i++){
        c = 0, k = i;
        while (k > 1 && L[k] == L[i]){
            c++;
            k /= L[k];
        }

        len[i] = (c + 1) * len[k];
        divisors[i] = (int *) malloc(sizeof(int) * len[i]);

        for (x = 1, j = 0, len[i] = 0; j <= c; j++, x *= L[i]){
            for (d = 0; d < len[k]; d++){
                divisors[i][len[i]++] = divisors[k][d] * x;
            }
        }
    }
}

int count(int n, int m){
    int z, y, x = m;
    long long v, res = 0;

    while (x >= 1){
        y = m / x, z = m / (y + 1);
        v = (long long)power[y] * (sum[x] - sum[z]);
        x = z, res += v;
    }

    res = (res % MOD + MOD) % MOD;
    return res;
}

int solve(int n, int k){
    long long res = 0;
    int i, j, v, m, x, y, z;
    for (i = 0; i < MAX; i++) power[i] = expo(i, n);

    dp[1] = count(n, 1);
    for (m = 2; m <= k; m++){
        res = dp[m - 1];
        for (j = 0; j < len[m]; j++){
            x = 0, y = 0, z = 0;
            x = divisors[m][j], v = m / x;
            y = power[v] * mu[x];
            z = power[v - 1] * mu[x];
            res = res + y - z;
        }
        dp[m] = ((res % MOD) + MOD) % MOD;
    }

    for (m = 1, res = 0; m <= k; m++) res += (m ^ dp[m]);
    return res % MOD;
}

int main(){
    generate();
    int n, k, res;

    while (scanf("%d %d", &n, &k) != EOF){
        printf("%d\n", solve(n, k));
    }
    return 0;
}

