int w[10];
long long dp[10][21];
long long c[21][21];
void init(){
	int i,j;
	for(i=1;i<=20;i++){
		c[i][0]=1;
		c[i][i]=1;
	}
	for(i=2;i<=20;i++){
		for(j=1;j<i;j++){
			c[i][j]=c[i-1][j-1]+c[i-1][j];
		}
	}
}
void run(){
	int i,j,k;
	long long r;
	init();
	while(scanf(LLD,&n)!=EOF){
		for(i=0;i<10;i++){
			x[i]=0;
		}
		for(;n>0;n/=10){
			x[n%10]++;
		}
		l=0;
		for(i=1;i<10;i++){
			if(x[i]>0){
				w[l++]=x[i];
			}
		}
		for(i=0;i<10;i++){
			for(j=0;j<=20;j++){
				dp[i][j]=0;
			}
		}
		for(i=1;i<=w[0];i++){
			dp[0][i]=1;
		}
		for(i=1;i<l;i++){
			for(j=i+1;j<=20;j++){
				for(k=1;k<=w[i]&&j-k>=i;k++){
					dp[i][j]+=dp[i-1][j-k]*c[j-k+k][j-k];
				}
			}
		}
		if(x[0]>0){
			l++;
			for(j=i+1;j<=20;j++){
				for(k=1;k<=x[0]&&j-k>=i;k++){
					dp[i][j]+=dp[i-1][j-k]*c[j-1-k+k][j-1-k];
				}
			}
		}
		r=0;
		for(i=0;i<=20;i++){
			r+=dp[l-1][i];
		}
		printf(LLD"\n",r);
	}
}
