void swap(ll *xp, ll *yp) {
  ll h = *xp;
  *xp = *yp;
  *yp = h;
}

ll lessEqualInTable(int n, int m, ll x) {
  ll result = 0;
  ll rightmostColumn = min(x, n);
  ll rightmostFullColumn = min(x, x/m);
  result += rightmostFullColumn * min(x, m);
  for (ll column = rightmostFullColumn + 1; column <= rightmostColumn; column++)
    result += min(x / column, m);
  //printf("%d %d %d %d\n", n, m, x, result);
  return result;
}

ll findKthInList(ll n, ll m, ll k) {
  if (n > m)
    swap(&n, &m);
  if (k == 1)
    return 1;
  ll l = 1, r = n*m, mid;
  while (r - l > 1) {
    mid = (l + r) / 2;
    if (lessEqualInTable(n, m, mid) >= k)
      r = mid;
    else
      l = mid;
  }
  return l + 1;
}

