int calc_moves(int start_x, int start_y, int finish_x, int finish_y, int step_x, int step_y) {

    int dx = abs(start_x - finish_x);
    int dy = abs(start_y - finish_y);

    if (dx % step_x != 0 || dy % step_y != 0) {
        return -1;
    }

    int sx = dx / step_x;
    int sy = dy / step_y;

    if (abs(sx - sy) & 1) {
        return -1;
    }
    else {
        return (sx > sy)?sx:sy;
    }

}

int min(int a, int b) {
    if (a == -1 || b == -1) {
        return -a*b;
    }
    else{
        return (a > b)?b:a;
    }
}

