        printf("%d\n", ModExp(p, p - 1, 1000000007));
        return 0;
    } else if(k == 1) {
        printf("%d\n", ModExp(p, p, 1000000007));
        return 0;
    }
    for(i = 1; i < p; ++i) {
        A[((long long)i * k) % p] = i;
    }
    for(i = 1; i < p; ++i) {
        if(!Flag[i]) {
            ++exp;
        }
        int j = i;
        while(!Flag[j]) {
            Flag[j] = 1;
            j = A[j];
        }
    }
    printf("%d\n", ModExp(p, exp, 1000000007));
    return 0;
}

