	scanf("%d %d %d %d", &n, &a, &b, &k);

	dp[0][a] = 1;
	for (i = 1; i <= k; i++) {
		int sum[5001];

		sum[0] = 0;
		for (j = 1; j <= n; j++) {
			sum[j] = sum[j - 1] + dp[i - 1][j];
			if (sum[j] >= MOD)
				sum[j] -= MOD;
		}

		for (j = 1; j <= n; j++)
			if (j < b) {
				dp[i][j] = sum[(j + b - 1) / 2] - dp[i - 1][j] + MOD;
				if (dp[i][j] >= MOD)
				 	dp[i][j] -= MOD;
			} else if (j > b) {
				dp[i][j] = sum[n] - sum[(j + b) / 2] + MOD;
