					dp[i][j] -= MOD;
				dp[i][j] += -dp[i - 1][j] + MOD;
				if (dp[i][j] >= MOD)
					dp[i][j] -= MOD;
			}
	}

	ans = 0;
	for (j = 1; j <= n; j++)
		ans = (ans + dp[k][j]) % MOD;

