#define MAX_SIZE(X) ((unsigned short)(X))
void MSA(short, short, unsigned short*);
void Merge(short, short, short, unsigned short*);
int main()
{
    unsigned short Seq[MAX_SIZE(1e2)], Cut[MAX_SIZE(1e2)], n, b, i, j = 0, Odd = 0, Even = 0, max = 0, Sum = 0;
    scanf("%hu%hu", &n, &b);
    for(i = 0; i < n; i++){ scanf("%hu", Seq + i); }
    for(i = 0; i < n - 2; i++){
        if(Seq[i] % 2 == 0){ Even++; }
        else{ Odd++; }
        if(Odd == Even){ Cut[j++] = Seq[i] > Seq[1 + i] ? Seq[i] - Seq[1 + i] : Seq[1 + i] - Seq[i]; }
    }
    MSA(0, j - 1, Cut);
    for(i = 0; i < j; i++){
        Sum += Cut[i];
        if(Sum > b){ break; }
        max++;
    }
    printf("%hu", max);

    return 0;
}
void MSA(short l, short r, unsigned short* A){
    if(l < r){
        unsigned short m = (l + r) / 2;
        MSA(l, m, A);
        MSA(1 + m, r, A);
        Merge(l, m, r, A);
    }
}
void Merge(short l, short m, short r, unsigned short* A){
    unsigned short s1 = m - l + 1, s2 = r - m, i, j;
    unsigned short A1[s1], A2[s2];
    for(i = 0; i < s1; i++){ A1[i] = A[i + l]; }
    for(j = 0; j < s2; j++){ A2[j] = A[j + m + 1]; }
    i = 0, j = 0;
    while(i < s1 && j < s2){ A[l++] = A1[i] < A2[j] ? A1[i++] : A2[j++]; }
    while(i < s1){ A[l++] = A1[i++]; }
    while(j < s2){ A[l++] = A2[j++]; }

}

