#include<stdio.h>
#include<stdlib.h>

#define ll long long

const ll M = 1000000007;

ll inv(ll a, ll M)
{
   if (a < 0)
       a = (a + (1+(0-a)/M)*M)%M;
   ll M_o = M;
   ll ac0 = 1;
   ll ac1 = 0;
   ll bc0 = 0;
   ll bc1 = 1;
   ll q;
   ll r;
   ll temp;
   while (M > 0)
   {
       q = a/M;
       r = a%M;
       a = M;
       M = r;

       temp = ac0;
       ac0 = bc0;
       bc0 = temp - q*bc0;

       temp = ac1;
       ac1 = bc1;
       bc1 = temp - q*bc1;
   }
   M = M_o;
   if (ac0 > 0)
       return ac0%M;
   else
       return (ac0 + M*(1+(0-ac0)/M))%M;
}

ll expmod(ll a, ll x, ll m)
{
    ll ans = 1;
    while (x > 0)
    {
        if (x%2 == 1)
            ans = ans*a%m;
        a = a*a%m;
        x /= 2;
    }
    if (ans > 0)
        return ans%M;
    else
        return (ans + M*(1 + (0-ans)/M))%M;
}

int main()
{
    int n, m;
    int ai, bi;
    int ki;

    fscanf(stdin, "%d %d\n", &n, &m);
    fscanf(stdin, "%d %d\n", &ai, &bi);
    fscanf(stdin, "%d", &ki);

    ll a = (ll) ai;
    ll b = (ll) bi;
    ll k = (ll) ki;

    ll p = a*inv(b, M)%M;

    ll* kchoose = malloc((m+1)*sizeof(ll));
    kchoose[0] = 1;
    for (int l = 1; l < m+1; l++)
        kchoose[l] = (kchoose[l-1]*(k-l+1)%M)*inv(l,M)%M;

    ll* expmodp = malloc((m+1)*sizeof(ll));
    ll* expmod1pkminus = malloc((m+1)*sizeof(ll));
    expmodp[0] = 1;
    expmod1pkminus[0] = expmod(1-p, k, M);
    ll inv1p = p!=1? inv(1-p, M):1;

    for (int x = 1; x < m+1; x++)
    {
        expmodp[x] = p*expmodp[x-1]%M;
        if (p != 1)
            expmod1pkminus[x] = inv1p*expmod1pkminus[x-1]%M;
        else
            expmod1pkminus[x] = x<k? 0:1;
    }

    ll* p_left = malloc((m+1)*sizeof(ll));
    for (int l = 0; l < m+1; l++)
    {
        if (l > k)
            p_left[l] = 0;
        else
            p_left[l] = (((kchoose[l]*expmodp[l])%M)*expmod1pkminus[l])%M;
    }

    ll* egs1 = malloc((m+1)*sizeof(ll));
    ll* egs2 = malloc((m+1)*sizeof(ll));
    ll* sle1 = malloc((m+1)*sizeof(ll));
    ll* sle2 = malloc((m+1)*sizeof(ll));

    ll* R = malloc(m*sizeof(ll));
    ll* T = malloc((m+1)*sizeof(ll));
    T[m] = 1;
    for (int i = 0; i < m; i++)
    {
        R[i] = 1;
        T[i] = 0;
    }

    ll* Tp_left = malloc(m*sizeof(ll));
    ll* Rp_left = malloc(m*sizeof(ll));

    for (int ni = 0; ni < n; ni++)
    {
        egs1[m] = 0;
        egs2[m] = 0;

        for (int i = 0; i < m; i++)
            Rp_left[i] = R[i]*p_left[m-(i+1)]%M;

        for (int s = m-1; s >= 0; s--)
        {
            egs1[s] = (egs1[s+1] + Rp_left[s])%M;
            egs2[s] = (egs2[s+1] + p_left[m-(s+1)])%M;
        }

        sle1[0] = 0;
        sle2[0] = 0;

        for (int i = 0; i < m; i++)
            Tp_left[i] = T[i]*p_left[i]%M;

        for (int e = 1; e < m+1; e++)
        {
            sle1[e] = (sle1[e-1] + p_left[e-1])%M;
            sle2[e] = (sle2[e-1] + Tp_left[e-1])%M;
        }

        R[0] = (p_left[0]*egs1[0]%M - Tp_left[0]*egs2[0]%M + M)%M;
        for (int s = 1; s < m; s++)
            R[s] = (R[s-1] + p_left[s]*egs1[s]%M - Tp_left[s]*egs2[s]%M + M) % M;

        T[0] = 0;
        for (int e = 1; e < m+1; e++)
            T[e] = (T[e-1] + Rp_left[e-1]*sle1[e]%M - p_left[m-e]*sle2[e]%M + M)%M;
    }

    printf("%lld\n", T[m]);
}

