  i64 min = (i64) n * k;
  i64 max = 1;
  for (i32 i = 0; i < 4; ++i) {
    const i32 s = i >= 2 ? a : (k - a) % k;
    for (i32 j = 0; j < 4; ++j) {
      i32 t = (j & 1) ? (k - b) % k : b;
      if (t <= s) {
	i64 d = m - (s - t);
	i64 v = m / gcd (d, m);
	min = MIN(min, v);
	max = MAX(max, v);
	t += k;
      }
      for (i64 l = t; l < m; l += k) {
	i64 d = l - s;
	i64 v = m / gcd (d, m);
	min = MIN(min, v);
	max = MAX(max, v);
      }
    }
  }
  print_int (min);
  putchar(' ');
  print_int (max);
  puts("");
}

