	min_t = INT64_MAX, max_t = INT64_MIN;

	scanf("%d%d%d%d", &n, &k, &a, &b);
	dis = (int64_t)n * k;
	stp[0] = a-b, stp[1] = b-a, stp[2] = a+b, stp[3] = k-a-b;

	for(i = 0; i < 4; i++){
		for(l = stp[i]; l <= dis; l += k){
			if(l <= 0)
				continue;
			t = dis / gcd(dis, l);
