ll overflowcheck(ll a)
{
    if (a == 1)
    {
        return 0;
    }
    else
    {
        ll temp = a;
        ll power = 1;
        while (longlongmax / temp > a)
        {
            temp *= a;
            power++;
        }
        return power + 1; // Overflow occurs at this power.
    }
