ll merge(ll A[], ll B[], ll left, ll mid, ll right)
{
    ll count = 0;
    ll n1 = mid - left + 1;
    ll n2 = right - mid;

    ll LA[n1], LB[n1], RA[n1], RB[n2];

    for (ll n = 0; n < n1; n++)
    {
        LA[n] = A[n + left];
        LB[n] = B[n + left];
    }
    for (ll n = 0; n < n2; n++)
    {
        RA[n] = A[n + mid + 1];
        RB[n] = B[n + mid + 1];
    }

    ll i = 0, j = 0, k = left;

    while (i < n1 && j < n2)
    {
        if (LA[i] < RA[j])
        {
            A[k] = LA[i];
            B[k] = LB[i];
            i++;
        }
        else
        {
            A[k] = RA[j];
            B[k] = RB[j];
            count += n1 - i;
            j++;
        }
        k++;
    }
    while (i < n1)
    {
        A[k] = LA[i];
        B[k] = LB[i];
        i++;
        k++;
    }

    while (j < n2)
    {
        A[k] = RA[j];
        B[k] = RB[j];
        j++;
        k++;
    }
    return count;
}

ll mergesort(ll A[], ll B[], ll left, ll right)
{
    ll total = 0;
    if (left < right)
    {
        ll mid = (right - left) / 2 + left;
        total += mergesort(A, B, left, mid);
        total += mergesort(A, B, mid + 1, right);
        total += merge(A, B, left, mid, right);
    }
    return total;
}

ll primemarked[3000000];
ll primearray[3000000];
ll primeind;

void setupprimes()
{
    for (ll i = 2; i < 3000000; i++)
    {
        for (ll j = 2 * i; j < 3000000; j += i)
        {
            primemarked[j] = 1;
        }
    }
    for (ll i = 2; i < 3000000; i++)
    {
        if (!primemarked[i])
        {
            primearray[primeind++] = i;
        }
    }
}

ll power(ll x, ll y, ll p)
{
    ll res = 1; // Initialize result

    x = x % p; // Update x if it is more than or
               // equal to p

    while (y > 0)
    {
        // If y is odd, multiply x with result
        if (y & 1)
            res = (res * x) % p;

        // y must be even now
        y = y >> 1; // y = y/2
        x = (x * x) % p;
    }
    return res;
}

ll factorsX[3000000];
ll ind = 0;

int main(int argc, char const *argv[])
{
    ll T = 1;
    // scanf("%lld",&T);
    setupprimes();


    for (ll t = 0; t < T; t++)
    {
        ll x, N;
        scanf("%lld %lld", &x, &N);
        for (ll j = 0; j < primeind; j++)
        {
            if ((x % primearray[j]) == 0)
            {
                factorsX[ind++] = primearray[j];
                while((x % primearray[j])==0)
                {
                    x /= primearray[j];
                }
            }
        }
        if (x!=1)
        {
            // a prime itself
            factorsX[ind++] = x;
        }

        ll total = 1;
        // printf("%lldpopop\n",longlongmax/947);
        for (ll o = 0; o < ind; o++)
        {
            // for each prime factor calculate
            ll count[300];
            ll cind = 0;
            ll fac = factorsX[o];
            ll p = 1;
            ll gh = 1;
            while (p <= N && gh)
            {
                // printf("%lld\n",p);
                count[cind++] = N / p;
                if( p >= longlongmax/fac)
                {
                    gh = 0;
                }
                p *= fac;
            }

            for (ll m = 0; m < cind; m++)
            {
                ll num = 1;
                ll prod ;

                if(m!=(cind-1))
                {
                   num = (m*(count[m]-count[m+1]))%(MOD-1);
                }
                else
                {
                    num = (m*count[m])%(MOD-1);
                }
                // printf("%lld\n",num);
                prod = power(factorsX[o],num,MOD);
                total  = (total*prod)%MOD;
                total %= MOD;
            }
        }
        printf("%lld\n",total%MOD);
    }

    return 0;
}

