#define lint long long

const int P = 1e9 + 7;

lint f(lint n, lint k) {
	lint ret = 1;
	while (k) {
		if (k & 1) ret = ret * n % P;
		n = n * n % P;
		k >>= 1;
	}
	return ret;
}

int main()
{
	lint x, n, i, k, cnt, ans = 1;
	scanf("%lld%lld", &x, &n);

	for (i = 2; i*i <= x; ++i) {
		if (x % i) continue;
		cnt = 0, k = i;
		while (1) {
			cnt += n / k;
			if (k > n/i) break;
			k *= i;
		}
		ans = ans * f(i, cnt) % P;
		while (!(x % i)) x /= i;
	}

	if (x - 1) {
		cnt = 0, k = x;
		while (1) {
			cnt += n / k;
			if (k > n/x) break;
			k *= x;
		}
		ans = ans * f(x, cnt) % P;
	}

	printf("%d", ans);
	return 0;
}

