long long BS(ll l, ll h, ll b, ll s, ll c, ll nb, ll ns, ll nc, ll pb, ll ps, ll pc, ll r, ll ans){

	if(l <= h){

		ll m = l + (h - l) / 2;
		ll p = max( 0 , b*m - nb ) * pb + max( 0 , c*m - nc ) * pc + max( 0 , s*m - ns ) * ps;

		if(p == r){
			return m;
		}
		else if(p < r){
			ans = max( ans , m );
			return BS(m + 1, h, b, s, c, nb, ns, nc, pb, ps, pc, r, ans);
		}
		else{
			return BS(l, m - 1, b, s, c, nb, ns, nc, pb, ps, pc, r, ans);
		}
	}

	return ans;
}

