int ok(ll x) {
	ll tmp = x * cb - nb, rr = r;
	if (tmp * pb > rr || rr < 0)
		return 0;
	if (tmp > 0)
		rr -= tmp * pb;

	tmp = x * cs - ns;
	if (tmp * ps > rr || rr < 0)
		return 0;
	if (tmp > 0)
		rr -= tmp * ps;

	tmp = x * cc - nc;
	if (tmp * pc > rr || rr < 0)
		return 0;
	if (tmp > 0)
		rr -= tmp * ps;

	return 1;
}

