int requires_substitute(char string[], int index1, int index2) {
    if (index1 != 0 && index2 != 0) return 0;
    if (index1 == 1 || index2 == 1) {
        if (string[2] == '0') return 1;
    } if (string[1] == '0') return 1;
}
int requires_substitute_fifty(char string[], int index1, int index2) {
    if (index1 == 0 && index2 != 1 && string[1] == '0') return 1;
    else return 0;
}
int substitute(char string[], int index1, int index2, int size) {
    int res = -1;
    for (int i = 0; i < size; i++) {
        if (i != index1 && i != index2 && string[i] != '0') {
            res = i;
            break;
        }
    }
    return res;
}

