            if (nums[1] < nums[2]) {
                step_count ++;
            }
            step_count += size - nums[1] - 1;
            step_count += size - nums[2] - 2;
            steps[1] = step_count;
        } if (nums[4] != -1) {
            int step_count = 0;
            if (size > 2 && requires_substitute_fifty(string, nums[1], nums[4])) {
                int sub = substitute(string, nums[1], nums[4], size);
                if (sub != -1) {
                    step_count += sub;
                }
