#define ll long long
ll digitsum(ll num)                      
{
    ll div = 1;
    ll sum = 0;

    while (num / div != 0)
    {
        sum += ((num) % (div * 10)) / div;
        div *= 10;
    }

    return sum;
}

int main(void)
{
    ll n, s;
    scanf("%lli %lli", &n, &s);

    ll left = 0, right = n;                 
    while(right != left)
    {
        ll mid = (right + left) / 2;
        ll check = mid - digitsum(mid);

        if (check >= s)
            right = mid;
        else
            left = mid;

        if (right - left == 1)
            left++;
    }

    if (n - digitsum(n) >= s)               
        printf("%lli\n", n - right + 1);
    else
        printf("0\n");
}

