int n, m, highest = 0, highest_temp = 0, p[8+1], i, k, m_note, n_count, min;
void permutate(int, int);
void swap(int *x, int *y);

int main()
{
    while(scanf("%d", &n)!=EOF)
    {
        highest = 0;
        highest_temp = 0;
        min = 9;
        scanf("%d", &m);
        for(i = 1; i<=8; i++)
        {
            p[i] = 0;
        }
        for(i = 1; i<=n; i++)
        {
            p[i] = i;
        }
        for(i = 1; i<=n; i++)
        {
            highest += i * (n+1-i);
        }

        m_note = 0;
        permutate(1, n);

    }
    return 0;
}

void permutate(int start, int end)
{
    if(start == end)
    {

        for(k=1; k<=n; k++)
        {
            n_count = n;
            for(n_count; n_count>0; --n_count)
            {
                min = 9;
                for(i=k; i<=n_count; ++i)
                {

                    if(p[i]<min)
                    {
                        min = p[i];
                    }
                    else{}
                }
                for(i=k; i<=n_count; ++i)
                {
                    if(p[i]==min)
                    {
                        highest_temp += p[i];
                    }
                    else{}
                }
            }
        }
        if(highest_temp >= highest)
        {
            ++m_note;
            if(m_note==m)
            {
                for(i=1; i<=n; i++)
                {
                    printf("%d ", p[i]);
                }
                printf("\n");
            }
            else{}
        }
        else{}
    }
    else
    {
        int j;
        for(j = start; j <= end; ++j)
        {

            swap((p+start), (p+j));
            permutate(start+1, end);
            highest_temp = 0;
            swap((p+start), (p+j));
        }
    }
}

void swap(int *x, int *y)
{
    int temp; 
    temp = *x;
    *x = *y; 
    *y = temp;
}

