					dq_[k + d] = min(dq_[k + d], x + d * (i + 1));
					if (++d < 10)
						dp_[k + d] = min(dp_[k + d], x + d * (i + 1));
				}
			}
		}
		memcpy(dp, dp_, (K * 2 + 1) * sizeof *dp_), memcpy(dq, dq_, (K * 2 + 1) * sizeof *dq_); 
	}
	ans = INF;
	for (k = 0; k <= K * 2; k++)
		if ((aa[0] + k - K) % 10 == 0)
			ans = min(ans, dp[k]);
	printf("%d\n", ans);
	return 0;
}

