u64 walk()
{
  int n, i, j, a, b, c;
  int count[3] = {0,0,0};
  int max_d = 0;

  P[0][0][0][0] = 1;
  for (n = 0; n < N; n++) {
    for (i = T; i >= L[n]; i--)
      for (a = 0; a <= count[0]; a++)
        for (b = 0; b <= count[1]; b++)
          for (c = 0; c <= count[2]; c++) {
            int pos = 0;
            if (G[n] == 0)
              pos |= !!add2i(P[i][a+1][b][c], P[i-L[n]][a][b][c]);
            if (G[n] == 1)
              pos |= !!add2i(P[i][a][b+1][c], P[i-L[n]][a][b][c]);
            if (G[n] == 2)
              pos |= !!add2i(P[i][a][b][c+1], P[i-L[n]][a][b][c]);

            if (pos && i > max_d)
              max_d = i;
          }
    count[G[n]] = min2(count[G[n]] + 1, N/2+1);
  }

  u64 r = 0;
  for (a = 0; a <= count[0]; a++)
    for (b = 0; b <= count[1]; b++)
      for (c = 0; c <= count[2]; c++)
        if (P[T][a][b][c])
          for (int g = 0; g < 3; g++)
            add2i(r, mul3(fact3(a,b,c), perm[a][b][c][g], P[T][a][b][c]));
  return r;
}

