    testcase();
    return 0;
}

#include <stdio.h>

#define N	62

long long rev(long long x) {
	long long y = 0;

	while (x) {
		y = y << 1 | (x & 1);
		x >>= 1;
	}
	return y;
}

long long padded(long long a, long long b) {
	return a % b == 0 && ((a / b) & (a / b - 1)) == 0;
}

int main() {
	static int yy[N];
	long long x, y, z;
	int n, l, r, i;

	scanf("%lld%lld", &x, &y);
	if (x == y) {
		printf("YES\n");
		return 0;
	}
	if ((y & 1) == 0) {
		printf("NO\n");
		return 0;
	}
	n = 0;
	while (y)
		yy[n++] = y & 1, y >>= 1;
	for (l = 0; l < n; l++) {
		for (r = n - 1; r >= l; r--) {
			if (yy[l] == 0 && yy[r] == 0)
				break;
			else if (yy[l] == 0) {
				z = 0;
				for (i = r; i >= l; i--)
					z = z << 1 | yy[i];
				if (x == z) {
					printf("YES\n");
					return 0;
				}
			} else if (yy[r] == 0) {
				z = 0;
				for (i = l; i <= r; i++)
					z = z << 1 | yy[i];
				if (x == z) {
					printf("YES\n");
					return 0;
				}
				break;
			} else {
				z = 0;
				for (i = l; i <= r; i++)
					z = z << 1 | yy[i];
				if (padded(x, z) || padded(x, rev(z))) {
					printf("YES\n");
					return 0;
				}
			}
		}
		if (yy[l] == 0)
			break;
	}
	printf("NO\n");
	return 0;
}

