long long solve(long long n, int useN) {
    int i, mask, j, high, r7, r8, r9, last, next;
    memset(d[0], 0, sizeof(d[0]));

    if(useN) {
        dgCount = 0;
        while(n) {
            digits[dgCount++] = n % 10;
            n /= 10;
        }
    } else {
        for(i = 0; i < dgCount / 2; i++)
           swap(&digits[i], &digits[dgCount - i - 1]); 
    }

    d[0][0][0][0][0][0][0] = 1;
    for(i = 0; i < dgCount; i++) {
      memset(d[(i & 1) ^ 1], 0, sizeof(d[(i & 1) ^ 1]));
      for(mask = 0; mask < 48; mask++) {
        for(r7 = 0; r7 < 7; r7++) {
          for(r8 = 0; r8 < 8; r8++) {
            for(r9 = 0; r9 < 9; r9++) {
              for(high = 0; high < 2; high++) {
                for(last = 0; last < 2; last++) {
                    if(d[i & 1][mask][r7][r8][r9][high][last] == 0)
                        continue;
                    int limit = 9;
                    if(high == 0)
                        limit = digits[dgCount - i - 1];
                    for(next = 0; next <= limit; next++) {
                        int nr7 = nx7[r7][next];
                        int nr8 = nx8[r8][next];
                        int nr9 = nx9[r9][next];
                        int nmask = nxmask[mask][next];
                        int nhigh = (high ? 1 : (next == limit ? 0 : 1));
                        int nlast = (next == 0 || next == 5 ? 1 : 0);
                        d[(i & 1) ^ 1][nmask][nr7][nr8][nr9][nhigh][nlast] += 
                            d[i & 1][mask][r7][r8][r9][high][last];
                    }
                }
              }
            }
          }
        }
      }
    }

    long long ans = 0;
    for(mask = 0; mask < 48; mask++) {
        for(r7 = 0; r7 < 7; r7++) {
            if(bad7[mask][r7]) {
                break;
            }
            for(r8 = 0; r8 < 8; r8++) {
                if(bad8[mask][r8]) {
                    continue;
                }
                for(r9 = 0; r9 < 9; r9++) {
                    if(bad9[mask][r9]) {
                        continue;
                    }
                    for(high = 0; high < 2; high++)
                        for(last = 0; last < 2; last++) {
                            if(bad5[mask][last])
                                continue;
                            ans += d[dgCount & 1][mask][r7][r8][r9][high][last];
                            if(0 && d[dgCount & 1][mask][r7][r8][r9][high][last] > 0)
                                printf("mask=%d r7=%d r8=%d r9=%d high=%d last=%d val="LL"\n"
                                        , mask, r7, r8, r9, high, last, 
                                        d[dgCount & 1][mask][r7][r8][r9][high][last]);

                        }
                }
            }
        }
    }
    //printf("HERE "LL"\n", d[1][24][0][7][7][0][0]); 
    return ans;
}

int stupid(int n) {
    int i, j, tmp;
    int ans = 0;
    for(i = 0; i <= n; i++) {
        int isValid = 1;
        tmp = i;
        while(tmp) {
            int cur = tmp % 10;
            tmp /= 10;
            if(cur >= 2 && i % cur)
                isValid = 0;
        }
        ans += isValid;
    }
    return ans;
}

