  ll a, b, res;
  int size;

  bc[0]=0;
  REP(i,1,1<<8) bc[i] = bc[i&(i-1)]+1;

  scanf("%d",&size);
  while(size--){
    scanf("%I64d%I64d",&a,&b);
    res = solve(b) - solve(a-1);
    printf("%I64d\n",res);
  }

  return 0;
}

