void dfs(int *p, int x, int y)
{
	if (vis[p[0]][p[1]][p[2]][x][y])
		return; 
	vis[p[0]][p[1]][p[2]][x][y] = true; 
	int far = 0, near = 50; 
	for (int i = 0; i < 3; i++)
	{
		if (p[i] < 45)
			far = max(far, p[i]); 
		near = min(near, p[i]);
	}
	ans = max(ans, far); 
	for (int j = 0; j < 3; j++)
	{
		int arr[] = {p[0], p[1], p[2]}, z = 1 << j; 
		if (p[j] >= 45)
		{
			int pos = p[j] - 45; 
			if (p[pos] >= 45)
				continue;
			for (int i = p[pos] + t[pos]; i >= p[pos] - t[pos] && i > near - 2 && i; i--)
			{
				if (chk(i))
				{
					arr[j] = i; 
					dfs(arr, x, y); 
				}
			}
		}
		else if (chk(j + 45))
		{
			if (y & z)
			{
				for (int i = 0; i < 3; i++)
				{
					if (my_abs(p[i] - p[j]) != 1)
						continue; 
					arr[i] = 45 + j; 
					dfs(arr, x, y ^ z); 
					arr[i] = p[i]; 
				}
