/* practice with Dukkha */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N	50
#define A	26
#define N_	(1 + N + A + 1)
#define M_	(N + N * A + A)
#define INF	0x3f3f3f3f

int min(int a, int b) { return a < b ? a : b; }
int max(int a, int b) { return a > b ? a : b; }

int oo[1 + M_ * 2], oh[1 + M_ * 2];

int link(int o, int h) {
	static int _ = 1;

	oo[_] = o, oh[_] = h;
	return _++;
}

int ii[M_], jj[M_], cc[M_ * 2], cost[M_], cost_[M_], m_;
int ae[N_], pi[N_], dd[N_], ff[N_], n_;
int pq[1 + N_], iq[N_], cnt;

void link_(int i, int j, int c, int co) {
	int h = m_++;

	ii[h] = i, jj[h] = j, cc[h << 1] = c;
	cost[h] = co;
	ae[i] = link(ae[i], h << 1);
	ae[j] = link(ae[j], h << 1 | 1);
}

int less(int u, int v) {
	return pi[u] < pi[v] || pi[u] == pi[v] && dd[u] < dd[v];
}

int i2(int i) {
	return (i *= 2) > cnt ? 0 : i < cnt && less(pq[i + 1], pq[i]) ? i + 1 : i;
}

void pq_up(int u) {
	int i, j, v;

	for (i = iq[u]; (j = i / 2) && less(u, v = pq[j]); i = j)
		pq[iq[v] = i] = v;
	pq[iq[u] = i] = u;
}

void pq_dn(int u) {
	int i, j, v;

	for (i = iq[u]; (j = i2(i)) && less(v = pq[j], u); i = j)
		pq[iq[v] = i] = v;
	pq[iq[u] = i] = u;
}

void pq_add_last(int u) {
	pq[iq[u] = ++cnt] = u;
}

int pq_remove_first() {
	int u = pq[1], v = pq[cnt--];

	if (v != u)
		iq[v] = 1, pq_dn(v);
	iq[u] = 0;
	return u;
}

int dijkstra(int s, int t) {
	memset(pi, 0x3f, n_ * sizeof *pi);
	pi[s] = 0, pq_add_last(s);
	while (cnt) {
		int i, d, o;

		i = pq_remove_first();
		d = dd[i] + 1;
		for (o = ae[i]; o; o = oo[o]) {
			int h_ = oh[o];

			if (cc[h_] > 0) {
				int h = h_ >> 1, j = i ^ ii[h] ^ jj[h];
				int p = pi[i] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);

				if (pi[j] > p || pi[j] == p && dd[j] > d) {
					if (pi[j] == INF)
						pq_add_last(j);
					pi[j] = p, dd[j] = d, ff[j] = h_;
					pq_up(j);
				}
			}
		}
	}
	return pi[t] != INF;
}

int trace(int s, int t) {
	while (t != s) {
		int h_ = ff[t], h = h_ >> 1;

		cc[h_]--, cc[h_ ^ 1]++;
		t ^= ii[h] ^ jj[h];
	}
	return 1;
}

int edmonds_karp(int s, int t) {
	int h, f, ans;

	for (h = 0; h < m_; h++) {
		int i = ii[h], j = jj[h];

		pi[j] = min(pi[j], pi[i] + cost[h]);
	}
	for (h = 0; h < m_; h++) {
		int i = ii[h], j = jj[h];

		cost_[h] = cost[h] + pi[i] - pi[j];
	}
	f = 0;
	while (dijkstra(s, t)) {
		f += trace(s, t);
		for (h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];

			if (pi[i] != INF && pi[j] != INF) {
				/* pi[j] <= pi[i] + cost_[h] */
				/* cost_[h] + pi[i] - pi[j] >= 0 */
				cost_[h] += pi[i] - pi[j];
			}
		}
	}
	ans = 0;
	for (h = 0; h < m_; h++)
		ans += cc[h << 1 | 1] * cost[h];
	return ans;
}

int main() {
	static char cc[N * 2 + 1];
	static int bb[N * 2], kk[A];
	int n, i, a;

	scanf("%d%s", &n, cc), n /= 2;
	n_ = 1 + n + A + 1;
	for (i = 0; i < n * 2; i++)
		scanf("%d", &bb[i]);
	for (i = 0; i < n; i++)
		link_(0, 1 + i, 2, 0);
	for (i = 0; i < n; i++) {
		int j = n * 2 - 1 - i;
		int ai = cc[i] - 'a';
		int aj = cc[j] - 'a';

		for (a = 0; a < A; a++) {
			int b;

			if (a == ai && a == aj)
				b = max(bb[i], bb[j]);
			else if (a == ai)
				b = bb[i];
			else if (a == aj)
				b = bb[j];
			else
				b = 0;
			link_(1 + i, 1 + n + a, 1, -b);
		}
	}
	for (i = 0; i < n * 2; i++) {
		a = cc[i] - 'a';
		kk[a]++;
	}
	for (a = 0; a < A; a++)
		link_(1 + n + a, n_ - 1, kk[a], 0);
	printf("%d\n", -edmonds_karp(0, n_ - 1));
	return 0;
}

