long long power_mod (long long a, long long b, long long mod_num) {
  long long ans = 1LL;

  if (b > 0LL) {
    ans = power_mod(a, b/2LL, mod_num);
    ans = (ans * ans) % mod_num;
    if (b%2LL == 1LL) {
      ans = (ans * a) % mod_num;
    }
  }

  return ans;
}

int main () {
  int n = 0;
  int k = 0;

  int res = 0;

  long long ans = 0LL;
  long long mod_num = 1000000007LL;

  long long fact[100001] = {};
  long long invf[100001] = {};

  res = scanf("%d", &n);
  res = scanf("%d", &k);

  if (n <= k) {
    printf("%lld\n", power_mod(2LL, (long long)n, mod_num));
    return 0;
  }

  fact[0] = 1LL;
  for (int i = 0; i < n; i++) {
    fact[i+1] = fact[i];
    fact[i+1] *= (long long) (i+1);
    fact[i+1] %= mod_num;
  }

  invf[n] = power_mod(fact[n], mod_num-2LL, mod_num);
  for (int i = n; i > 0; i--) {
    invf[i-1] = invf[i];
    invf[i-1] *= (long long)i;
    invf[i-1] %= mod_num;
  }

  for (int i = 0; i <= k; i++) {
    long long tmp = invf[i];
    tmp = (tmp*invf[n-i])%mod_num;
    ans = (ans+tmp)%mod_num;
  }

  ans = (ans*fact[n])%mod_num;
  printf("%lld\n", ans);

  return 0;
}

