	scanf("%i %i %i", &a, &b, &k);

	int lo = 0, hi = b-a+1, ans = -1, mid;
	while( lo <= hi ) {
		mid = (lo + hi) / 2;

		int cnt = ps[a+mid-1] - ps[a-1];

		bool ok = 1;
		if( cnt < k ) ok = 0;

		for( i = a+1; i <= b-mid+1; i++ )
			if( ps[i+mid-1] - ps[i-1] < k ) ok = 0;

		if( ok ) {
			ans = mid;
			hi = mid - 1;
		} else lo = mid + 1;

	}

	printf("%i\n", ans);


	return 0;
}

