#include <stdio.h>

#define N	100
#define MD	100000000

void init(int dp[][N + 1], int n, int k) {
	int b, i, s;

	dp[0][0] = 1;
	for (b = 1; b <= n; b++) {
		s = 0;
		for (i = 0; i <= n; i++) {
			dp[b][i] = s;
			s = (s + dp[b - 1][i]) % MD;
			if (i >= k)
				s = (s - dp[b - 1][i - k] + MD) % MD;
		}
	}
}

int main() {
	static int dp1[N + 1][N + 1], dp2[N + 1][N + 1];
	int n1, n2, k1, k2, b;
	long long ans;

	scanf("%d%d%d%d", &n1, &n2, &k1, &k2);
	init(dp1, n1, k1);
	init(dp2, n2, k2);
	ans = 0;
	for (b = 1; b <= n1 || b <= n2; b++) {
		if (b <= n1 && b <= n2)
			ans = (ans + (long long) dp1[b][n1] * dp2[b][n2] * 2) % MD;
		if (b <= n1 && b - 1 <= n2)
			ans = (ans + (long long) dp1[b][n1] * dp2[b - 1][n2]) % MD;
		if (b - 1 <= n1 && b <= n2)
			ans = (ans + (long long) dp1[b - 1][n1] * dp2[b][n2]) % MD;
	}
	printf("%lld\n", ans);
	return 0;
}

