		//like this
		////1100 -> 1103
		////2200 -> 2203

		//Checking: can we put count of warriors that is devoded into 4
		int group_of_4_warriors = current_group / 4;
		if (rows_of_4_seats - group_of_4_warriors >= 0)
			rows_of_4_seats -= group_of_4_warriors;
