			}
			else { 
				rows_of_2_seats -= group_of_4_warriors * 2;
				group_of_4_warriors = 0;
			}
			supa_dupa_place_for_1x2_or_2x1 -= group_of_4_warriors * 2;
		}
		else {
			puts("NO");
			return 0;
		}
		//Checking: can we put remaining warriors that is devided into 2
		int remain_of_group_of_4_warriors_grouped_by_2 = (current_group % 4) / 2;
		if (rows_of_2_seats - remain_of_group_of_4_warriors_grouped_by_2 >= 0)
			rows_of_2_seats = rows_of_2_seats - remain_of_group_of_4_warriors_grouped_by_2;
		else if (rows_of_4_seats - remain_of_group_of_4_warriors_grouped_by_2 >= 0){//HERE
			rows_of_4_seats = rows_of_4_seats - remain_of_group_of_4_warriors_grouped_by_2;//HERE
