		}
		else if (supa_dupa_place_for_1x2_or_2x1 - remain_of_group_of_4_warriors_grouped_by_2 >= 0)
			supa_dupa_place_for_1x2_or_2x1 = supa_dupa_place_for_1x2_or_2x1 - remain_of_group_of_4_warriors_grouped_by_2;
		else {
			puts("NO");
