		}
		fprintf(stderr, "now we have %d %d %d %d\n", rows_of_4_seats, rows_of_2_seats, seats_for_1_warroir_that_remain_from_HERE, supa_dupa_place_for_1x2_or_2x1);//debug
		//Checking remaining
		int remaining_of_all = (current_group % 4) % 2;
		if (remaining_of_all == 0)
			continue;
		//By the way if we are here, remaining_of_all == 1, but i anyway will use remaining_of_all instead 1, becouse I can
		if (seats_for_1_warroir_that_remain_from_HERE - remaining_of_all >= 0)
			seats_for_1_warroir_that_remain_from_HERE--; //I lied, here and somewhere I will use "--" and "++"
		else if (rows_of_4_seats - remaining_of_all >= 0){
			rows_of_4_seats--;
			rows_of_2_seats++; //We are lost rows of 4 seats, but on other half of rows of 4 seats we still have 2 free seats
		}
		else if (rows_of_2_seats - remaining_of_all >= 0)
			rows_of_2_seats--;
		else if (supa_dupa_place_for_1x2_or_2x1 - remaining_of_all >= 0){
			supa_dupa_place_for_1x2_or_2x1--;
			seats_for_1_warroir_that_remain_from_HERE++; //HERE we take only 1/2 of supa_dupa... and we can use that 1/2 of supa_dupa only for 1 man
		}
		else{
