		A[i]--;
	}
	for(i=0;i<n;i++)visited[i]=0;
	ans=1;
	for(i=0;i<n;i++){
		if(visited[i]==0){
			visited[i]=1;
			cycle=bfs(A[i],visited,1,i,A);
			if(cycle==-1){
				ans=-1;
				break;
			}
