int translate(char c) {
	switch (c) {
		case 'S':
			return 0;
		case 'D':
			return 1;
		case 'H':
			return 2;
		case 'C':
			return 3;
		case 'T':
			return 10;
		case 'J':
			return 11;
		case 'Q':
			return 12;
		case 'K':
			return 13;
		case 'A':
			return 14;
		default:
			return c - '0';
	}
}

