/* upsolve with Dukkha */
#include <stdio.h>

#define N	100
#define S	5000
#define MD	998244353

int ch[S + N][N];

void init(int n, int k) {
	int i, j;

	ch[0][0] = 1;
	for (i = 1; i < n; i++) {
		ch[i][0] = 1;
		for (j = 1; j < k; j++)
			ch[i][j] = (ch[i - 1][j - 1] + ch[i - 1][j]) % MD;
	}
}

long long power(long long a, int k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k / 2);
	p = p * p % MD;
	if (k % 2 == 1)
		p = p * a % MD;
	return p;
}

long long inv(long long a) {
	return power(a, MD - 2);
}

int main() {
	/* dp[a][b]: b balls into a urns of size r - 1 */
	static int dp[1 + N][1 + S];
	/* dq[a][b]: dp[a][b] + dp[a][b - 1] + ... + dp[a][b - (r - 1)] */
	static int dq[1 + N][1 + S];
	int n, s, r, a, b, k, p, q;

	scanf("%d%d%d", &n, &s, &r);
	init(s + n, n);
	for (a = 0; a <= n; a++) {
		int sum;

		if (a == 0)
			dp[0][0] = 1;
		else
			for (b = 0; b <= s; b++)
				dp[a][b] = dq[a - 1][b];
		sum = 0;
		for (b = 0; b <= s; b++) {
			sum = (sum + dp[a][b]) % MD;
			if (b >= r)
				sum = (sum - dp[a][b - r] + MD) % MD;
			dq[a][b] = sum;
		}
	}
	p = 0;
	for (k = 1; k <= n && k * r <= s; k++)
		for (b = 0; b + k * r <= s; b++)
			p = (p + (long long) dp[n - k][b] * ch[s - b - k * r + k - 1][k - 1] % MD * ch[n - 1][k - 1] % MD * inv(k)) % MD;
	q = ch[s - r + n - 1][n - 1];
	printf("%lld\n", p * inv(q) % MD);
	return 0;
}

