int chk(long long n) {
    if (n <= 3) return (n > 1);
    for (long long i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}

void solve() {
    long long a, b;
    scanf("%lld%lld", &a, &b);
    if (a - b == 1 && chk(b + a)) printf("YES\n");
    else printf("NO\n");
}

