#define flow_t long long
// #define flow_t double
typedef struct Dinic Dinic;
typedef struct Dinic {
    int n;
    vector **to;
    vector **cap;
    vector **rev;
    vector *min_cost;
    vector *iter;
    void (*add)(Dinic*, int, int, flow_t);
    flow_t (*max_flow)(Dinic*, int, int);
} Dinic;


void Dinic_add_edge(Dinic *d, int from, int to, flow_t cap) {
    vector_push(d->rev[from], (void*)&d->to[to]->n);
    vector_push(d->rev[to], (void*)&d->to[from]->n);
    vector_push(d->to[from], (void*)&to);
    vector_push(d->to[to], (void*)&from);
    vector_push(d->cap[from], (void*)&cap);
    vector_push(d->cap[to], NULL);
}

bool Dinic_bfs(Dinic *d, int s, int t) {
    int init = -1;
    rep(i, 0, d->n) vector_set(d->min_cost, i, (void*)&init);
    vector *q = vector_init(1, sizeof(int));
    vector_set(d->min_cost, s, NULL);
    int head = 0;
    q->push(q, (void*)&s);
    while(head != q->n && vector_get(d->min_cost, t) == -1){
        int p = q->get(q, head);
        head++;
        rep(i, 0, d->to[p]->n) {
            int to = vector_get(d->to[p], i);
            if(vector_get(d->cap[p], i) > 0 && vector_get(d->min_cost, to) == -1){
                ll cost = vector_get(d->min_cost, p) + 1;
                vector_set(d->min_cost, to, (void*)&cost);
                q->push(q, (void*)&to);
            }
        }
    }
    return vector_get(d->min_cost, t) != -1;
}

flow_t Dinic_dfs(Dinic *d, int idx, int t, flow_t flow) {
    if(idx == t) return flow;
    rep(i, vector_get(d->iter, idx), d->cap[idx]->n){
        vector_set(d->iter, idx, (void*)&i);
        flow_t cap = vector_get(d->cap[idx], i);
        int to = vector_get(d->to[idx], i);
        if(cap > 0 && vector_get(d->min_cost, idx) < vector_get(d->min_cost, to)) {
            flow_t delta = Dinic_dfs(d, to, t, flow < cap ? flow : cap);
            if(delta > 0) {
                cap -= delta;
                vector_set(d->cap[idx], i, (void*)&cap);
                int rev = vector_get(d->rev[idx], i);
                flow_t rev_cap = vector_get(d->cap[to], rev) + delta;
                vector_set(d->cap[to], rev, (void*)&rev_cap);
                return delta;
            }
        }
    }
    return 0;
}

flow_t Dinic_max_flow(Dinic *d, int s, int t) {
    flow_t flow = 0;
    while(Dinic_bfs(d, s, t)) {
        rep(i, 0, d->n) vector_set(d->iter, i, NULL);
        flow_t f = 0;
        while((f = Dinic_dfs(d, s, t, INF)) > 0) flow += f;
    }
    return flow;
}

Dinic *Dinic_init(int n) {
    Dinic *ret = (Dinic *)malloc(sizeof(Dinic));
    ret->n = n;
    ret->to = (vector **)malloc(n * sizeof(vector*));
    ret->cap = (vector **)malloc(n * sizeof(vector*));
    ret->rev = (vector **)malloc(n * sizeof(vector*));
    rep(i, 0, n) {
        ret->to[i] = vector_init(1, sizeof(int));
        ret->cap[i] = vector_init(1, sizeof(flow_t));
        ret->rev[i] = vector_init(1, sizeof(int));
    }
    ret->min_cost =vector_init(n, sizeof(int));
    ret->iter = vector_init(n, sizeof(int));
    ret->add = Dinic_add_edge;
    ret->max_flow = Dinic_max_flow;
    return ret;
}
