int Min(int a[3],int b[3]){
	int i , j = 1 , min = 0 ;
	for(i = 0 ; i < 3 ; i++){
		j++ ;
		if (j == 3) j = 0 ;
		if(a[i] > b[i] + b[j])	min += a[i] - b[i] - b[j] ;

	}
	return min ;
}

int Max(int a[3],int b[3]){
	int i , j = 0  , max = 0 ;
	for(i = 0 ; i < 3 ; i++){
		j++ ;
		if (j == 3) j = 0 ;
		if(a[i] > b[j])	max += b[j] ;
		else max += a[i];

	}
	return max ;
}

