long long power(long long x, long long n){
    long long res;
    if(n==0){
        return 1;
    }
    if(n==1){
        return x%MOD;
    }

    res=power(x, n/2);
    res%=MOD;
    res*=res;
    res%=MOD;
    if(n & 1LL){
        res*=x;
        res%=MOD;
    }
    return res%MOD;
}

