	static long long dp[N + 1][N + 1];
	static int next[N][C];
	static char cc[N + 1];
	int n, h, i, j, c;
	long long k, x, ans;

	scanf("%d%lld", &n, &k);
	scanf("%s", cc);
	for (i = n - 1; i >= 0; i--)
		for (c = 0; c < C; c++)
			next[i][c] = cc[i] == c + 'a' ? i + 1 : i + 1 == n ? -1 : next[i + 1][c];
	dp[0][0] = 1;
	for (h = 0; h < n; h++)
		for (i = 0; i < n; i++)
			if ((x = dp[h][i]))
				for (c = 0; c < C; c++)
					if ((j = next[i][c]) != -1 && (dp[h + 1][j] += x) > INF)
						dp[h + 1][j] = INF;
	ans = 0;
	for (h = n; h >= 0; h--)
		for (i = 0; i <= n; i++) {
