#include <stdio.h>
#include <string.h>

#define N	13

long long lucky(int b) {
	return b == 1 ? 0 : lucky(b / 2) * 10 + (b % 2 == 0 ? 4 : 7);
}

int is_lucky(int y) {
	return y == 0 ? 1 : is_lucky(y / 10) && (y % 10 == 4 || y % 10 == 7);
}

int ff[N];

void init() {
	int i, f;

	f = 1;
	for (i = 0; i < N; i++) {
		ff[i] = f;
		f *= i + 1;
	}
}

int get(int n, int k, int i) {
	static char used[N];
	int h, j;

	memset(used, 0, n * sizeof *used);
	for (h = 0; h < n; h++) {
		int f = ff[n - 1 - h], s = k / f;

		for (j = 0; j < n; j++)
			if (!used[j] && s-- == 0) {
				if (h == i)
					return j;
				used[j] = 1;
				break;
			}
		k %= f;
	}
	return -1;
}

int main() {
	int n, n_, k, b, ans;
	long long f;

	init();
	scanf("%d%d", &n, &k);
	f = 1;
	n_ = 1;
	while (f < k)
		f *= ++n_;
	if (n_ > n) {
		printf("-1\n");
		return 0;
	}
	ans = 0;
	for (b = 2; ; b++) {
		long long x = lucky(b);
		int y;

		if (x > n)
			break;
		if (x <= n - n_) {
			ans++;
			continue;
		}
		y = n - n_ + get(n_, k - 1, x - (n - n_) - 1) + 1;
		if (is_lucky(y))
			ans++;
	}
	printf("%d\n", ans);
	return 0;
}

