#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

long long gcd(long long a, long long b) {
  if (a % b == 0) {
    return b;
  }
  return gcd(b, a % b);
}

int main(void) {
  long long n, m, x, y, a, b;
  scanf("%lld %lld %lld %lld %lld %lld", &n, &m, &x, &y, &a, &b);

  long long d = gcd(a, b);
  a /= d;
  b /= d;

  int ans[4];
  long long lo = 1, hi = n;
  while (lo <= hi) {
    long long mid = (lo + hi) / 2;

    long long lx = mid * a;
    long long ly = lx * b / a;

    long long x0 = MAX(0, x - lx);
    long long y0 = MAX(0, y - ly);

    if (x0 + lx <= n && y0 + ly <= m) {
      lo = mid + 1;
      ans[0] = x0, ans[1] = y0;
      ans[2] = x0 + lx, ans[3] = y0 + ly;
    } else {
      hi = mid - 1;
    }
  }

  int lx = ans[2] - ans[0];
  if (x >= ans[0] + (lx+1)/2) {
    int r = x - (ans[0] + (lx+1)/2);
    int w = n - ans[2];
    ans[0] += MIN(r, w);
    ans[2] += MIN(r, w);
  }

  int ly = ans[3] - ans[1];
  if (y >= ans[1] + (ly+1)/2) {
    int r = y - (ans[1] + (ly+1)/2);
    int w = m - ans[3];
    ans[1] += MIN(r, w);
    ans[3] += MIN(r, w);
  }

  for (int i = 0; i < 4; i++) {
    printf("%i ", ans[i]);
  }
  puts("");

  return 0;
}

