    if (p == 0) p = 1;

    c[0][0] = 1;

    for (i = 1; i <= 100; i++) {
        c[i][0] = c[i][i] = 1;

        for (j = 1; j < i; j++) c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % m;
    }

    for (i = p; i <= n; i++) {
        for (j = 1; j <= 9; j++) {
            for (k = 0; k <= 10; k++) {
                for (l = 0; l <= n; l++) {
