typedef long long ll;

int a[10];
ll dp[101][10];
ll c[101][101];

const int mod = 1000000007;

void init()
{
    int i, j;
    for (i = 0; i <= 100; i ++)
    {
        c[i][0] = c[i][i] = 1;
    }
    for (i = 1; i <= 100; i ++)
    {
        for (j = 1; j < i; j ++)
        {
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
        }
    }
}

void solve(int n)
{
    int i, j, k, t;
    ll ans;
    ans = 0;
    for (i = 1; i <= 9; i ++)
    {
        {
            a[i] --;
            for (j = 0; j < n; j ++)
            {
                if (j >= a[0])
                {
                    dp[j][0] = 1;
                }
                else
                {
                    dp[j][0] = 0;
                }
                for (k = 1; k <= 9; k ++)
                {
                    dp[j][k] = 0;
                    for (t = MAX(a[k], 0); t <= j; t ++)
                    {
                        dp[j][k] = (dp[j][k] + ((dp[j - t][k - 1] * c[j][t]) % mod)) % mod;
                    }
                }
                ans = (ans + dp[j][9]) % mod;
            }
            a[i] ++;
        }
    }
    printf("%d\n", (int)ans);
}

