long long int k,i,j,max,min,S;

int main()
{
    int n,m,x,y;

    scanf("%d%d%lld%d%d",&n,&m,&k,&x,&y);

    if(n*m > k)
    {
           max = 1;
           min = 0;
           if((x-1)*m+y <= k)S = 1;
           else S = 0;
    }
    else if(n <= 2)
    {
         min = k/(m*n);
         max = (k%(m*n) == 0)?min:min + 1;

         if(max == min)S = max;
         else
         {
             if(n == 1)
             {
                  if(k%m >= y)S = max;
                  else S = min;
             }
             else
             {
                 j = k%(m*n);
                 if(j > m)
                 {
                            if(x == 2 && j-m < y)S = min;
                            else S = max;
                 }
                 else
                 {
                     if(x == 1 && j >= y)S = max;
                     else S = min;
                 }
             }
         }
    }
    else
    {
        i = k/(m*(2*n-2));
        j = k%(m*(2*n-2));
        max = i*2;
        min = i;
        if(j == 0)
        {
             if(x == 1 || x == n)S = min;
             else S = max;
        }
        else
        {
            if(j <= m)
            {
                 if(x == 1)
                 {
                      if(y > j)S = min;
                      else S = min+1;
                 }
                 else if(x == n)S = min;
                 else S = max;
            }
            else if(j <= m*(n-1))
            {
                 max++;
                 if(x == 1)S = min+1;
                 else if(x == n)S = min;
                 else 
                 {
                      if((x-1)*m+y <= j)S = max;
                      else S = max-1;
                 }
            }
            else if(j <= m*n)
            {
                 max++;
                 if(j == m*n)min++;
                 if(x == 1)S = i+1;
                 else if(x == n)
                 {
                      if(y <= j%m || j%m == 0)S = i+1;
                      else S = i;
                 }
                 else S = max;
            }
            else
            {
                max+=2;
                min++;
                if(x == 1)S = i+1;
                else if(x == n)S = i+1;
                else
                {
                    S = i*2+1;
                    j-=m*n;
                    if(j%m == 0)
                    {
                           if(x + j/m > (n-2))S++;
                    }
                    else
                    {
                        if(x + j/m > (n-1))S++;
                        else if(x + j/m == (n-1))
                        {
                             if(j%m >= y||j%m == 0)S++;
                        }
                    }
                }
            }
        }
    }

    printf("%lld %lld %lld\n",max,min,S);
}

