int64_t count(int64_t n, int64_t m, int64_t k, int64_t x, int64_t y)
{
    if (n != 1) {
        if (x == 0 || x == n - 1)
            //return div(k - y - x*m, 2*(n-1)*m);
            return div(k, x*m+y, 2*(n-1)*m);
        else
            //return div(k - y - x*m, 2*(n-1)*m) + div(k - y - m*(2*n - 2 - x), 2*(n-1)*m);
            return div(k, x*m+y, 2*(n-1)*m) + div(k, (2*n-2-x)*m+y, 2*(n-1)*m);
    } else {
        //return div(k - y - x*m, n*m);
        return div(k, y, n*m);
    }
}

