#define swap(a,b) {*(a)=*(a)^*(b);*(b)=*(a)^*(b);*(a)=*(a)^*(b);}

bool next_permutation(int *a,int len)
{
    if(len == 1)
        return false;
    int i,j;
    int left;
    i = len - 1;
    left = len;
    for(i; i>0; i--)
        if(a[i] > a[i-1])
        {
            left = i - 1;
            break;
        }
    if(left == len)
        return false;
    if(left == len - 2)
    {
        swap(&a[left],&a[left+1]);
        return true;
    }
    i = len - 1;
    for(i; i>left; i--)
        if(a[i] > a[left])
        {
            swap(&a[i],&a[left]);
            break;
        }
    i = len - 1;
    j = left + 1;
    for(i,j; i>j; i--,j++)
        swap(&a[i],&a[j]);
    return true;
}

