#include <stdio.h>

#define N	100
#define K	(N * N)
#define MD	1000000007

long long power(int a, long long k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k / 2);
	p = p * p % MD;
	if (k % 2)
		p = p * a % MD;
	return p;
}

int main() {
	static int ch[N + 1][N + 1], pp[N + 1][N + 1], dp[N + 1][K + 1];
	int n, k, h, i, j;
	long long m;

	scanf("%d%lld%d", &n, &m, &k);
	ch[0][0] = 1;
	for (i = 1; i <= n; i++) {
		ch[i][0] = 1;
		for (j = 1; j <= i; j++)
			ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD;
	}
	for (i = 0; i <= n; i++)
		for (j = 0; j <= i; j++)
			pp[i][j] = power(ch[i][j], m / n);
	dp[0][0] = 1;
	for (i = 0; i < n; i++)
		for (j = 0; j <= k; j++) {
			int x = dp[i][j];

			if (x == 0)
				continue;
			for (h = 0; h <= n && j + h <= k; h++)
				dp[i + 1][j + h] = (dp[i + 1][j + h] + (long long) x * pp[n][h] % MD * (i < m % n ? ch[n][h] : 1)) % MD;
		}
	printf("%d\n", dp[n][k]);
	return 0;
}

