#define N	24

int compare(const void *a, const void *b) {
	int ia = *(int *) a;
	int ib = *(int *) b;

	return ia - ib;
}

int main() {
	static int cc[N], ss[N], aa[1 << N - 1], dp[1 << N - 1];
	int n, m, i, j, k, b;

	scanf("%d", &n);
	for (i = 0; i < n; i++)
		scanf("%d", &cc[i]);
	qsort(cc, n, sizeof *cc, compare);
	k = 0;
	while (k < n && cc[k] == 1)
		k++;
	m = n - k;
	for (i = k; i < n; i++)
		ss[i - k] = cc[i] - 1;
	for (j = 1; j < m; j++)
		ss[j] += ss[j - 1];
	n--;
	for (b = 1; b < 1 << n; b++) {
		i = 0;
		while ((b & 1 << i) == 0)
			i++;
		aa[b] = aa[b ^ 1 << i] + cc[i];
	}
	memset(dp, -1, (1 << n) * sizeof *dp), dp[0] = 0;
	for (b = 0; b < 1 << n; b++) {
		j = dp[b];
		if (j == -1 || j == m)
			continue;
		for (i = 0; i < n; i++)
			if ((b & 1 << i) == 0) {
				int b_ = b ^ 1 << i;

				if (aa[b_] < ss[j])
					dp[b_] = j;
				else if (aa[b_] == ss[j] && aa[b] > (j == 0 ? 0 : ss[j - 1]))
					dp[b_] = j + 1;
			}
	}
	printf(dp[(1 << n) - 1] == m ? "YES\n" : "NO\n");
	return 0;
}

