#define MOD 1000000007
#define SENT -1
lli memo[1010][1010];

lli rec(int a, int b) {
    if (a == 0 && b == 0)
        return 0;
    if (a < 0)
        return 0;
    if (b < 0)
        return 0;
    if (a < b)
        return 0;
    if (memo[a][b] != SENT)
        return memo[a][b];
    int ret = 0;
    if ((a+b)&1)
        ret = 1;
    ret += rec(a-1,b);
    ret += rec(a,b-1);
    while(ret>=MOD)
        ret-=MOD;
    memo[a][b] = ret;
    return ret;
}

int main(void)
{
    int n,i,j;
    in32(n);
    fo3(i,0,n)
        fo3(j,0,n)
            memo[i][j] = SENT;
    out64(rec(n,n));
    return EXIT_SUCCESS;
}

