    int x;
    scanf("%d", &x) > 0;
    return x;
}

int b[MAX_A+1]; // b[x] = how many of size x are in a
int c[MAX_A+1];
int d[MAX_A+1];

int min(int a, int b) { return (a < b && a != -1) ? a : b; }

int main() {
    int n = read_int(), k = read_int(), best = -1;
    for(int i = 0; i < n; i++) b[read_int()]++;
    for(int i = 0; i <= MAX_A; i++) c[i] = b[i];
    for(int e = 1; e < 20; e++) {
        for(int i = 0; i <= MAX_A; i++) {
            if(b[i] >= k && b[i]-c[i] < k) {
                best = min(best, d[i] - (e-1) * (b[i]-k));
            }
            c[i] = 0;
            if (i*2 <= MAX_A) c[i] += c[i*2], d[i] += c[i*2] * e;
            if (i*2+1 <= MAX_A) c[i] += c[i*2+1], d[i] += c[i*2+1] * e;
            b[i] += c[i];
        }
    }
    printf("%d\n", best);
}

