#define N	100
#define A	300

int tt[A + 1];

void update(int i, int x) {
	while (i <= A) {
		if (tt[i] < x)
			tt[i] = x;
		i |= i + 1;
	}
}

int query(int i) {
	int x = 0;

	while (i >= 0) {
		if (x < tt[i])
			x = tt[i];
		 i &= i + 1;
		 i--;
	}
	return x;
}

int main() {
	static int aa[N], kk[A + 1];
	int n, m, t, h, i, a, a_, ans;

	scanf("%d%d", &n, &t);
	for (i = 0; i < n; i++) {
		scanf("%d", &a);
		aa[i] = a;
		kk[a]++;
	}
	a_ = 0;
	for (a = 1; a <= A; a++)
		if (kk[a_] < kk[a])
			a_ = a;
	m = n * n < t ? n * n : t;
	for (h = 0; h < m; h++)
		for (i = 0; i < n; i++)
			update(aa[i], query(aa[i]) + 1);
	ans = query(A);
	if (t > n * n)
		ans += (t - n * n) * kk[a_];
	printf("%d\n", ans);
	return 0;
}

