#define MD	1000000007

int power(int a, int b) {
	int p;

	if (b == 0)
		return 1;
	p = power(a, b / 2);
	p = (long long) p * p % MD;
	if (b % 2 == 1)
		p = (long long) p * a % MD;
	return p;
}

int solve(int x) {
	return power(2, x - 1);
}

int sign(int x) {
	int a, cnt;

	cnt = 0;
	for (a = 2; a * a <= x; a++) {
		if (x % a == 0) {
			x /= a;
			cnt++;
		}
		if (x % a == 0)
			return 0;
	}
	if (x > 1)
		cnt++;
	return cnt % 2 == 0 ? 1 : -1;
}

