static i64 read_int(void){int prev='\0';int c=getchar();while(!('0'<=c && c<='9')){prev=c;c=getchar();}i64 res=0;while('0'<=c && c<='9'){res=10*res+c-'0';c=getchar();}return prev=='-'?-res:res;}

#define MIN(a,b) ((a)<(b)?(a):(b))

#define POS(i, j) ((i) * (n + 1) + (j))

void run (void) {
  i32 n = read_int();
  char *s = (char *) calloc (n + 1, sizeof (char));
  scanf ("%s", s);
  i32 len = 1;
  for (i32 i = 1; i < n; ++i) {
    if (s[i] == s[len - 1]) continue;
    s[len++] = s[i];
  }
  s[len] = '\0';
  n = len;
  i32 *dp = (i32 *) calloc ((n + 1) * (n + 1), sizeof (i32));
  for (i32 len = 1; len <= n; ++len) {
    for (i32 l = 0; l < n + 1 - len; ++l) {
      i32 r = l + len;
      i32 min = 1 + dp[POS(l + 1, r)];
      for (i32 j = l + 1; j < r; ++j) {
        if (s[j] != s[l]) continue;
        min = MIN(min, dp[POS(l + 1, j)] + dp[POS(j, r)]);
      }
      dp[POS(l, r)] = min;
    }
  }
  print_int (dp[POS(0, n)]);
  puts("");
}

int main (void) {
  run ();
  return 0;
}

