#define N	16
#define M	1000000007

int cnt;

int factorial(int n) {
	return n == 0 ? 1 : (long long) factorial(n - 1) * n % M;
}

void solve(int *bb, int *cc, int i, int n) {
	int k, tmp;

	if (i == n) {
		cnt = (cnt + 1) % M;
		return;
	}
	for (k = 0; k <= n - i - 1; k++) {
		int j = (cc[k] - i + n) % n;

		if (!bb[j]) {
			tmp = cc[k], cc[k] = cc[n - i - 1], cc[n - i - 1] = tmp;
			bb[j] = 1;
			solve(bb, cc, i + 1, n);
			tmp = cc[k], cc[k] = cc[n - i - 1], cc[n - i - 1] = tmp;
			bb[j] = 0;
		}
	}
}

