int valid (char word[]) {
    int sum1 = 0, i, sum2 = 0;
    for(i = 0; i < 3; i++) {
        sum1 += word[i] - '0';
        sum2 += word[i + 3] - '0';
    }
    return sum1 == sum2;
}

int fill (int pos, char word[], char base[]) {
    int i;
    if(pos == 6) {
        if(valid(word) == 0) {
            return 100;
        }
        int change = 0;
        for(i = 0; i < 6; i++) {
            if(base[i] != word[i]) change++;
        }
        return change;
    }
    int ans = 100;
    for(i = 0; i < 10; i++) {
        word[pos] = (char)(i + '0');
        int check = fill(pos+1, word, base);
        if(check < ans) ans = check;
        word[pos] = '?';
    }
    return ans;
}

