#define SIZE 1000

void factorization (int n, int p[], int k[], int *sz)
{
	int d;

	if (n == 1)
	{
		p[0] = 1;
		k[0] = 1;
		*sz = 1;
	}

	*sz = 0;

	for (d = 2; d * d <= n; d++)
		if (n % d == 0)
		{
			p[*sz] = d;

			while (n % d == 0)
			{
				k[*sz]++;
				n /= d;
			}

			(*sz)++;
		}

	if (n != 1)
	{
		p[*sz] = n;
		k[(*sz)++] = 1;
	}
}

int is_power_of_two (int n)
{
	while (n % 2 == 0)
		n /= 2;

	return n == 1;
}

int is_need_mult (int p[], int k[], int sz)
{
	int i;

	if (is_power_of_two (k[0]))
		for (i = 1; i < sz; i++)
			if (k[i] != k[i - 1])
				return 1;
			else
				k[i] = k[i];
	else
		return 1;

	return 0;
}

int oper (int p[], int k[], int sz)
{
	int i, cnt = 0, max = 0;

	for (i = 0; i < sz; i++)
		if (k[i] > max)
			max = k[i];

	i = 0;

	while (1 << i < max)
		i++;

	cnt = i;

	if (is_need_mult (p, k, sz))
		cnt++;

	return cnt;
}

int min_num (int p[], int sz)
{
	int i, min = 1;

	for (i = 0; i < sz; i++)
		min *= p[i];

	return min;
}

int main()
{
	int n, i, sz, oper_cnt, p[SIZE] = {0}, k[SIZE] = {0};

	scanf ("%d", &n);

	factorization (n, p, k, &sz);

	oper_cnt = oper (p, k, sz);

	printf ("%d %d\n", min_num (p, sz), oper_cnt);

	return 0;
}

