#define MOD 1000000007

long long mpow(long long a, long long p)
{
  a %= MOD;

  long long r = 1;
  while (p) {
    if ((1 & p)) r = (r * a) % MOD;
    a = (a * a) % MOD;
    p >>= 1;
  }
  return r;
}

int inv(long long x)
{ return mpow(x, MOD-2); }

#define MAXF 100005

long long factorial[MAXF];

long long possib(long long width, long long boxes, long long minh)
{
  long long separators = width-1;
  long long elements = boxes-width*minh;

  if(elements < 0) return 0;
  else return (factorial[separators+elements]*inv(factorial[separators]*factorial[elements])) % MOD;
}

long long all_possib, nice_possib;
void add_all(long long x)
{
  x %= MOD;
  all_possib += x;
  all_possib %= MOD;
}
void add_nice(long long x)
{
  x %= MOD;
  nice_possib += x;
  nice_possib %= MOD;
}

int main()
{
  long long fac;
  int i;
  int result;

  i = 0;
  for(fac = 1; i<MAXF; fac = fac*i % MOD){
    factorial[i] = fac;
    i++;
  }

  int F, W, H, width;
  scanf("%d %d %d\n", &F, &W, &H);

  if(W == 0 || F == 0){
    if(W == 0 || W > H) printf("1\n");
    else printf("0\n");
    return 0;
  }

  all_possib = 0;
  nice_possib = 0;
  for(width=1; width<=W; width++){
    add_all(possib(width, F, 1)*possib(width, W, 1));
    add_all(possib(width+1, F, 1)*possib(width, W, 1));
    add_all(possib(width, W, 1)*possib(width, F, 1));
    add_all(possib(width+1, W, 1)*possib(width, F, 1));

    add_nice(possib(width, F, 1)*possib(width, W, H+1));
    add_nice(possib(width+1, F, 1)*possib(width, W, H+1));
    add_nice(possib(width, W, H+1)*possib(width, F, 1));
    add_nice(possib(width+1, W, H+1)*possib(width, F, 1));
  }
  result = nice_possib*inv(all_possib) % MOD;

  printf("%d\n", result);

  return 0;
}

