#define A int
#define B int

typedef struct {
    A first;
    B second;
} pair;

pair make_pair(A first, B second)
{
    pair p;

    p.first = first;
    p.second = second;

    return p;
}

int n, m;
char s1[101];
char s2[101];
pair dp[100][100];
pair dp2[100];

pair dfs(int x, int y)
{
    if (x == n) {
        pair p = dfs(0, y);

        p.first++;

        return p;
    } else if (y == m) {
        pair p = make_pair(0, x);

        return p;
    } else {
        if (dp[x][y].first != -1) return dp[x][y];

        if (s1[x] == s2[y]) {
            return dp[x][y] = dfs(x + 1, y + 1);
        } else {
            return dp[x][y] = dfs(x + 1, y);
        }
    }
}

