    n = strlen(s1);
    m = strlen(s2);

    for (i = 0; i < n; i++) p[s1[i] - 'a']++;
    for (i = 0; i < m; i++) q[s2[i] - 'a']++;

    for (i = 0; i < 26; i++) {
        if (p[i] == 0 && q[i] > 0) {
            puts("0");

            return 0;
        }
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            dp[i][j] = make_pair(-1, -1);
        }
    }

    for (i = 0; i < n; i++) {
        if (dp[i][0].first == -1) dfs(i, 0);
    }

    for (i = 0; i < n; i++) dp2[i] = make_pair(-1, -1);

    while (1) {
        x += dp[y][0].first;
        y = dp[y][0].second;

        if (x >= b) {
            if (x == b && y == 0) c++;

            break;
        }

        c++;

        if (dp2[y].first == -1) {
            dp2[y] = make_pair(x, c);
        } else {
            int z = x - dp2[y].first;

            if (x + z < b) {
                int w = (b - x - 1) / z;

                x += w * z;
                c += (c - dp2[y].second) * w;
            }
        }
    }

    printf("%d\n", c / d);

