	long long sum;
	int n, d, a, b;

	scanf("%d", &n);
	for (d = 1; d <= 9; d++)
	 kk[d] = n / 9 + (n % 9 >= d);
	sum = 0;
	for (a = 1; a <= 9; a++)
		for (b = 1; b <= 9; b++)
