#include <stdio.h>
typedef long long unsigned int u64;
u64 dp[1<<24];
u64 min(const u64 a, const u64 b) {
    return a < b ? a : b;
}
u64 solve(const u64 n, const u64 x, const u64 y) {
    dp[1] = x;
    for(int i = 1; i <= n; i++)
        if(i & 1) dp[i] = min(dp[i - 1] + x, dp[(i + 1) / 2] + x + y);
        else dp[i] = min(dp[i / 2] + y, dp[i - 1] + x);
    return dp[n];
}

int main(void) {
    int n, x, y;
    scanf("%d%d%d", &n, &x, &y);
    printf("%llu", solve(n, x, y));
    return 0;
}

