int main(void) {
    int i;
    int c;
    long long hr, hb, wr, wb;
    long long ans;

    scanf("%d %lld %lld %lld %lld", &c, &hr, &hb, &wr, &wb);

    ans = 0;
    if (max(wr, wb) * max(wr, wb) > c)
        if (wr > wb)
            for (i = 0; c - wr * i >= 0; i++)
                ans = max(ans, hr * i + (c - wr * i) / wb * hb);
        else
            for (i = 0; c - wb * i >= 0; i++)
                ans = max(ans, hb * i + (c - wb * i) / wr * hr);
    else
        if (hr * wb > hb * wr)
            for (i = 0; c - wb * i >= 0 && i < wr; i++)
                ans = max(ans, hb * i + (c - wb * i) / wr * hr);
        else
            for (i = 0; c - wr * i >= 0 && i < wb; i++)
                ans = max(ans, hr * i + (c - wr * i) / wb * hb);

    printf("%lld\n", ans);

    return 0;
}

