#include <stdio.h>

int ancestor(long long a, long long b) {
	while (b > a)
		b >>= 1;
	return b == a;
}	

int main() {
	int h, c;
	long long n, x, ans;

	scanf("%d%lld", &h, &n);
	n += (1LL << h) - 1;
	x = 1, ans = h;
	c = 0;
	while (x != n)
		if (ancestor(x, n)) {
			x = x << 1 ^ c; c ^= 1;
			h--;
		} else {
			ans += (1LL << h + 1) - 1;
			x >>= 1;
			h++;
		}
	printf("%lld\n", ans);
	return 0;
}

