	for (i = 0; i < h; ++i)
	{
		tn *= 2;
	}
	x = 0;
	for (i = 0; i < h; ++i)
	{
		tn /= 2;
		r += 1;
		if (tn & n)
		{
			if (x == 0)
			{
				r += 2 * tn - 1;
			}
			x = 0;
		}
		else
		{
