long long binsearch(long long n, long long m) {
	long long l = 0, r = n + 1, mid;

	while (r - l > 1) {
		mid = (l + r) / 2;
		if (n * 2 / (mid + 1) < mid)
			r = mid;
		else
			l = mid;
	}
	r = l + 1, l = -1;
	while (r - l > 1) {
		mid = (l + r) / 2;
		if (mid * (mid + 1) / 2 + m + mid < n)
			l = mid;
		else
			r = mid;
	}
	return r + 1;
}

