		k++;
		t >>= 1;
	}
	b = 0;
	for (m = n; m > 1; m >>= 1)
		b++;
	ans = 0;
	for (l = 0; b >= 0; b--)
		if (n & 1LL << b) {
			if (b >= k - l)
