#define M_	531441	/* M_ = pow(3, M) */

struct V {
	long long sum;
	int cnt;
} uu[N_], vv[M_];

long long ff[20];

int fill(struct V *vv, int *aa, int n) {
	int i, b, p, np;

	p = 1;
	for (i = 0; i < n; i++)
		p *= 3;
	np = 0;
	for (b = 0; b < p; b++) {
		int a, valid, cnt;
		long long sum;

		valid = 1;
		sum = 0, cnt = 0;
		for (i = 0, a = b; i < n; i++, a /= 3) {
			int c = a % 3;

			if (c == 1)
				sum += aa[i];
			else if (c == 2) {
				if (aa[i] >= 20) {
					valid = 0;
					break;
				}
				sum += ff[aa[i]];
				cnt++;
			}
		}
		if (valid) {
			struct V *v = &vv[np++];

			v->sum = sum;
			v->cnt = cnt;
		}
	}
	return np;
}

int compare_u(const void *a, const void *b) {
	struct V *u = (struct V *) a;
	struct V *v = (struct V *) b;

	return u->sum == v->sum ? u->cnt - v->cnt : u->sum < v->sum ? -1 : 1;
}

int compare_v(const void *a, const void *b) {
	struct V *u = (struct V *) a;
	struct V *v = (struct V *) b;

	return u->sum == v->sum ? v->cnt - u->cnt : u->sum > v->sum ? -1 : 1;
}

