typedef long long int int64;

static void printInt(int64 n){
  if(n<0){putchar('-');n=-n;}
  if(n==0){putchar('0');return;}
  int s[20];int len=0;
  while(n>0){s[len++]=n%10+'0';n/=10;}
  while(len>0){putchar(s[--len]);}
}
static int64 readInt(void){
  int prev='\0';int c=getchar();
  while(!('0'<=c && c<='9')){prev=c;c=getchar();}
  int64 res=0;
  while('0'<=c && c<='9'){res=10*res+c-'0';c=getchar();}
  return prev=='-'?-res:res;
}

#define POS(i,j) ((i)*(c+1)+(j))

const int mod=1000000007;

int inv(int a){
  int t=1;
  while(a>1){
    t=(int64)t*(mod-mod/a)%mod;
    a=mod%a;
  }
  return t;
}

void run(void){
  int64 n=readInt();
  int k=readInt();
  int ans=1;
  int64 p;
  for(p=2;p*p<=n;p++){
    if(n%p!=0) continue;
    int c=0;
    while(n%p==0){
      n/=p;
      c++;
    }
    int *dp=(int *)calloc((k+1)*(c+1),sizeof(int));
    dp[POS(0,c)]=1;
    int i,j,l;
    for(i=0;i<k;i++){
      for(j=0;j<=c;j++){
	for(l=0;l<=j;l++){
	  dp[POS(i+1,l)]+=(int64)dp[POS(i,j)]*inv(j+1)%mod;
	  dp[POS(i+1,l)]%=mod;
	}
      }
    }
    int local=0;
    for(i=0,j=1;i<=c;i++,j=(int64)j*p%mod) local=(local+(int64)j*dp[POS(k,i)])%mod;
    ans=(int64)ans*local%mod;
    free(dp);
  }
  if(n>1){
    int dp[2]={0,1};
    for(int i=0;i<k;i++){
      dp[0]=(dp[0]+(int64)dp[1]*inv(2))%mod;
      dp[1]=(int64)dp[1]*inv(2)%mod;
    }
    ans=ans*(dp[0]+(int64)n%mod*dp[1]%mod)%mod;
  }
  printInt(ans);
  putchar('\n');
}

int main(void){
  run();
  return 0;
}

#include<stdio.h>
