typedef int64_t i64;
typedef int32_t i32;

static void print_int(i64 n){if(n<0){putchar('-');n=-n;}if(n==0){putchar('0');return;}int s[20],len=0;while(n>0){s[len++]=n%10+'0';n/=10;}while(len>0){putchar(s[--len]);}}
static i64 read_int(void){int prev='\0';int c=getchar();while(!('0'<=c && c<='9')){prev=c;c=getchar();}i64 res=0;while('0'<=c && c<='9'){res=10*res+c-'0';c=getchar();}return prev=='-'?-res:res;}

const i32 mod = 1000000007;

#define ADD(x, a) do{(x) += (a); if ((x) >= mod) (x) -= mod;} while (0)
#define SUB(x, a) do{(x) += mod - (a); if ((x) >= mod) (x) -= mod;} while (0)

i32 inv (i32 a) {
  i32 t = 1;
  while (a > 1) {
    t = (i64) t * (mod - mod / a) % mod;
    a = mod % a;
  }
  return t;
}

i32 calc (i64 p, const i32 c, const i32 k) {
  i32 *dp = (i32 *) calloc (c + 1, sizeof (i32));
  dp[c] = 1;
  i32 *prob = (i32 *) calloc (c + 1, sizeof (i32));
  for (i32 i = 0; i <= c; ++i) {
    prob[i] = inv (i + 1);
  }
  for (i32 i = 0; i < k; ++i) {
    i32 sum = 0;
    for (i32 j = 0; j <= c; ++j) {
      i32 v = (i64) prob[j] * dp[j] % mod;
      ADD(sum, v);
    }
    for (i32 j = 0; j <= c; ++j) {
      i32 assign = sum;
      i32 v = (i64) prob[j] * dp[j] % mod;
      SUB(sum, v);
      dp[j] = assign;
    }
  }
  p %= mod;
  i32 ans = 0;
  for (i32 i = c; i >= 0; --i) {
    ans = ((i64) p * ans + dp[i]) % mod;
  }
  free (dp);
  free (prob);
  return ans;
}

void run (void) {
  i64 n = read_int();
  i32 k = read_int();
  i64 ans = 1;
  for (i64 p = 2; p * p <= n; ++p) {
    if (n % p != 0) continue;
    i32 c = 0;
    while (n % p == 0) {
      n /= p;
      ++c;
    }
    ans = ans * calc (p, c, k) % mod;
  }
  if (n > 1) ans = ans * calc (n, 1, k) % mod;
  print_int (ans);
  puts ("");
}

int main (void) {
  run ();
  return 0;
}

