#include <stdio.h>

#define K	18
#define M	100

int main() {
	static int dd[K];
	static long long dp[1 << K][M];
	long long n;
	int m, h, k, b, r, used;

	scanf("%lld%d", &n, &m);
	k = 0;
	while (n > 0) {
		dd[k++] = n % 10;
		n /= 10;
	}
	used = 0;
	for (h = 0; h < k; h++)
		if (dd[h] != 0 && (used & 1 << dd[h]) == 0) {
			used |= 1 << dd[h];
			dp[1 << h][dd[h] % m] = 1;
		}
	for (b = 0; b < 1 << k; b++)
		for (r = 0; r < m; r++) {
			long long x = dp[b][r];

			if (x != 0) {
				used = 0;
				for (h = 0; h < k; h++)
					if ((b & 1 << h) == 0 && (used & 1 << dd[h]) == 0) {
						used |= 1 << dd[h];
						dp[b | 1 << h][(r * 10 + dd[h]) % m] += x;
					}
			}
		}
	printf("%lld\n", dp[(1 << k) - 1][0]);
	return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define M	4167669	/* (23 choose 7) * 17 */
#define C	16
#define K	2000000000
#define T	7

void print(int k) {
	if (k == 0)
		return;
	print(k / C);
	printf("%c", k % C < 10 ? k % C + '0' : k % C - 10 + 'a');
}

int add(int a, int b) { return (long long) a + b < K ? a + b : K; }

int choose[C + T][C + T];

void init() {
	int n, r;

	choose[0][0] = 1;
	for (n = 1; n < C + T; n++) {
		choose[n][0] = 1;
		for (r = 1; r <= n; r++)
			choose[n][r] = choose[n - 1][r - 1] + choose[n - 1][r];
	}
}

int dp[M], m;

void branch(int *aa, int h) {
	int a, len, j;

	if (h == C) {
		for (len = 0; len <= C; len++) {
			if (len == 0)
				dp[m] = 1;
			else
				for (h = 0; h < C; h++) {
					if (aa[h] == 0)
						continue;
					if (h == 0 || aa[h - 1] != aa[h]) {
						a = aa[h] - 1;
						j = m / (C + 1) - choose[C - h - 1 + T - a][T - a];
						if (h < C - 1)
							j += choose[C - h - 2 + T - a][T - a];
						j = j * (C + 1) + len - 1;
					}
					dp[m] = add(dp[m], dp[j]);
				}
			m++;
		}
		return;
	}
	for (a = h == 0 ? 0 : aa[h - 1]; a <= T; a++) {
		aa[h] = a;
		branch(aa, h + 1);
	}
}

int idx(int *aa, int len) {
	int h, a, sum;

	sum = 0;
	for (h = 0; h < C; h++)
		for (a = h == 0 ? 0 : aa[h - 1]; a < aa[h]; a++)
			sum += choose[C - h - 1 + T - a][T - a];
	return sum * (C + 1) + len;
}

int compare(const void *a, const void *b) {
	int ia = *(int *) a;
	int ib = *(int *) b;

	return ia - ib;
}

int main() {
	static int aa[C], bb[C];
	int k, t, h, i, len, first;

	scanf("%d%d", &k, &t);
	if (t >= 8) {
		print(k);
		printf("\n");
		return 0;
	}
	init();
	branch(aa, 0);
	for (h = 0; h < C; h++)
		aa[h] = t;
	for (len = 1; ; len++) {
		int cnt = dp[idx(aa, len)];

		aa[0]--; cnt -= dp[idx(aa, len - 1)]; aa[0]++;
		if (k <= cnt)
			break;
		k -= cnt;
	}
	first = 1;
	while (len-- > 0) {
		for (h = first ? 1 : 0; h < C; h++) {
			memcpy(bb, aa, C * sizeof *aa);
			if (bb[h] == 0)
				continue;
			bb[h]--;
			qsort(bb, C, sizeof *bb, compare);
			if (k > dp[i = idx(bb, len)]) {
				k -= dp[i];
				bb[h]++;
			} else {
				printf("%c", h < 10 ? h + '0' : h - 10 + 'a');
				aa[h]--;
				break;
			}
		}
		first = 0;
	}
	printf("\n");
	return 0;
}

