#include <stdio.h>

#define Maxm 100
#define mod 1000000007

__attribute__((always_inline)) __inline__
void multiply(int m, int A[][Maxm], int B[][Maxm], int C[][Maxm]) {
	register int i, j, k;
	for (i = 0; i < m; i++) {
		for (j = 0; j < m; j++) C[i][j] = 0;
		for (k = 0; k < m; k++) for (j = 0; j < m; j++)
			C[i][j] = (C[i][j] + (long long)A[i][k] * B[k][j]) % mod;
	}
}

void power(int m, int A[][Maxm], int P[][Maxm], int T[][Maxm], long long k) {
	if (!k) {
		register int i, j;
		for (i = 0; i < m; i++)
			for (j = 0; j < m; j++)
				P[i][j] = (i == j);
	}
	else if (k & 1) {
		power(m, A, P, T, k / 2);
		multiply(m, P, P, T), multiply(m, T, A, P);
	}
	else {
		power(m, A, T, P, k / 2);
		multiply(m, T, T, P);
	}
}

int main() {
	register int i, j;
	static int A[Maxm][Maxm] = {};
	static int P[Maxm][Maxm] = {};
	static int T[Maxm][Maxm] = {};
	long long n;
	int m, ans;
	scanf("%lld%d", &n, &m);
	if (n < m) return puts("1") & 0;
	for (i = 0; i < m - 1; i++) A[i][i + 1] = 1;
	A[m - 1][0] = A[m - 1][m - 1] = 1;
	power(m, A, P, T, n - m + 1);
	for (ans = j = 0; j < m; j++)
		ans = (ans + P[m - 1][j]) % mod;
	printf("%d\n", ans);
	return 0;
}

