a_k = 1 (k<=0)
a_1=2
a_n = a_{n-1} + a_(n-m)
*/

const int mod=1000000007;

#define POS(i,j) ((i)*m+(j))

void matmul(int *c,int *a,int *b,int m){
  static int *tmp=NULL;
  if(tmp==NULL) tmp=calloc(m*m,sizeof(int));
  memset(tmp,0,sizeof(int)*m*m);
  int i,j,k;
  for(i=0;i<m;i++){
    for(k=0;k<m;k++){
      for(j=0;j<m;j++){
	tmp[POS(i,j)]=(tmp[POS(i,j)]+(int64)a[POS(i,k)]*b[POS(k,j)])%mod;
      }
    }
  }
  for(i=0;i<m*m;i++) c[i]=tmp[i];
}

void run(void){
  int64 n=readInt();
  int m=readInt();
  if(m>n){
    printInt(1);
    puts("");
    return;
  }
  n-=m-1;
  int *t=(int *)calloc(m*m,sizeof(int));
  int *s=(int *)calloc(m*m,sizeof(int));
  int i;
  for(i=0;i<m;i++) t[POS(i,i)]=1;
  for(i=1;i<m;i++) s[POS(i,i-1)]=1;
  s[POS(0,0)]=1;
  s[POS(0,m-1)]=1;
  while(n>0){
    if(n&1) matmul(t,t,s,m);
    matmul(s,s,s,m);
    n>>=1;
  }
  int64 ans=0;
  for(i=0;i<m;i++) ans=(ans+t[POS(0,i)])%mod;
  printInt(ans);
  puts("");
}

int main(void){
  run();
  return 0;
}

