long long K=998244353;

long long min(long long a, long long b){
    if(a > b)
        return b;
    return a;
}

long long pmod(long long a, long long n, long long b){
    long long c = 1, i, pows[40], prod;

    prod = 1;
    pows[0]=a;

    for( i =1; i < 40; i++ )
        pows[i] = (pows[i-1] * pows[i-1])%b;

    i = 0;
    while(n > 0){
        if( n % 2 == 1)
            prod = (prod*pows[i])%b;

        n=n/2;
        i++;
    }
    return prod % b;
}

long long binom(long long n, long long k){
    long long prod1, i, prod2;
    k = min(k, n-k);
    prod1 = 1;
    prod2 = 1;
    for( i =  1; i <= k; i++ ) {
        prod1 = (prod1 * i)%K;
        prod2 = (prod2 * (i + n-k ) )%K;
    }
    return (prod2 * pmod(prod1, K-2, K)) % K;
}



void solve(int n, int k){
    long long sum, i;
    if( k > n ){
        printf("0\n");
        return;
    }
    if( k == n ){
        printf("1\n");
        return;
    }
    if( k == 1 ){
        printf("%lld\n", n% K);
        return;
    }
    sum = binom(n-1,k-1 )%K;
    for( i = 2; i <= n/k; i++ )
        sum = (sum + binom(n/i - 1, k-1))%K;

    printf("%lld\n", sum % K );
}



int main(){
    long long n, k;
    scanf("%lld", &n);
    scanf("%lld", &k);
    solve(n,k);
    return 0;
}

