    scanf("%lld%lld%lld%lld%lld",&d,&k,&a,&b,&t);
    if(k>d)
        time+=d*a;
    else
        time+=a*k;

    if((d-k)>0)
    {
       if(k*a+t<k*b)
           time+=(k*a+t)*((d-k)/k);
       else    
            time+=(k*b)*((d-k)/k);
    }
    if(((d-k)%k)!=0 && (d-k)>0)
    {
        c=(d-k)%k;
       if(c*a+t<c*b)
           time+=(c*a+t);
       else    
            time+=(c*b);
    }
    printf("%lld\n",time);
    return 0;
}

#include <stdio.h>

#define N	500
#define MD	998244353

int dp[N + 1][N + 1];

void init() {
	int n, k, n_;

	dp[0][0] = 1;
	for (n = 0; n < N; n++)
		for (k = 0; k <= n; k++)
			if (dp[n][k])
				for (n_ = n + 1; n_ <= N; n_++) {
					int k_ = k > n_ - n ? k : n_ - n;

					dp[n_][k_] = (dp[n_][k_] + dp[n][k]) % MD;
				}
}

int main() {
	int n, k, a, b, ans;

	init();
	scanf("%d%d", &n, &k);
	ans = 0;
	for (a = 1; a <= n; a++)
		for (b = 1; b <= n && a * b < k; b++)
			ans = (ans + 2LL * dp[n][a] * dp[n][b]) % MD;
	printf("%d\n", ans);
	return 0;
}

