#define ll long long

ll solve(ll a, ll b) {
    ll i,k = 0;
    int* factors = malloc(sizeof(int)*1000*1000);
    //record the smaller factors of a
    for (i = 1; i*i <= a; i++) {
        if (a%i == 0) {
            factors[k++] = i;
            // printf("factor of a:%lli\n", i);
        }
    }
    //for each smaller factor of a+b
    ll answer = 2*(a+b+1);
    for (i = 1; i*i <= a+b; i++) {
        if ((a+b)%i == 0) {
            // printf("factor of a+b:%lli\n", i);
            //binary search a factor of a that is smaller than or equal to i
            int found = 0;
            ll hi = k;
            ll lo = 0;
            ll middle;
            // printf("lo:%lli, hi:%lli\n", lo, hi);
            while (!found) {
                middle = (lo + hi)/2;
                // printf("mid:%lli\n",middle);
                if (middle == lo || middle == hi) {
                    // printf("middle\n");
                    break;
                } else if (factors[middle] < i) {
                    lo = middle;
                } else if (factors[middle] > i) {
                    hi = middle;
                } else { // middle = i
                    found = 1;
                    break;
                }
            }
            // printf("i found %lli for a, %lli for a+b\n", factors[middle],i);
            // printf("a/fact=%lli <= a+b/i=%lli?\n",a/factors[middle],(a+b)/i);
            if (a/factors[middle] <= (a+b)/i) {
                if (answer > 2*(i + (a+b)/i)) {
                    answer = 2*(i + (a+b)/i);
                    // printf("NEW answer: %lli\n", answer);
                }
            }
        }
    }
    return answer;
}

int main(int argc, char* argv[]) {
    ll a,b = 0;
    scanf("%lli %lli",&a,&b);
    // printf("%lli + %lli = %lli\n", a, b, a+b);
    ll answer_a = solve(a,b);
    ll answer_b = solve(b,a);
    if (answer_a < answer_b) {
        printf("%lli\n", answer_a);
    } else {
        printf("%lli\n", answer_b);

    }
    return 0;
}

