    int p[10],r;
    for(i=0;i<n;i++) p[i]=order[i];
    r=permutationrank2(n,p);
    seen[r]=1;
    for(i=0;i<n-1;i++) if(left[i]) for(j=i+1;j<n;j++) if(left[j]) {
        left[j]--; left[i]--;
        t=order[j],order[j]=order[i],order[i]=t;
//      printf("  throw %d %d\n",at,i);
        btr();
        left[j]++; left[i]++;
        t=order[j],order[j]=order[i],order[i]=t;
    }
}

