}

long long count(int a, int b){
	int i;
	long long s = 0;
	if(a > b){
		a = a + b;
		b = a - b;
		a = a - b;
	}
	advance(a);
	for(i = 0; i <= a; i++){
	//	printf("%d ",s);
		s += c[a][i] * Arr(i, b);
		s %= 998244353;
	}
	return s;
}

