void divs(long long n)
{
	long long i;

	for(i=1;i*i<=n;i++)
	{
		if(n%i==0)
		{
			if(n/i==i)
				div[u++]=i;
			else
			{
				div[u++]=i;
				ohalf[v++]=n/i;
			}
		}
	}

	for(i=v-1;i>=0;i--)
		div[u++]=ohalf[i];
}

