#pragma GCC optimize("Ofast")
#include <stdio.h>

#define MAXN 5001

const int md = 998244353;

int n, m, k;
int dp[MAXN][MAXN];

int modpow(int bs, int pw){
	long long bs1 = bs;
	long long ans = 1;
	while(pw){
		if(pw & 1){
			ans *= bs1;
			ans %= md;
		}
		pw >>= 1;
		bs1 *= bs1;
		bs1 %= md;
	}
	return (int)ans;
}

int main(){
	scanf("%d%d%d", &n, &m, &k);
	dp[0][0] = 1;
	for(int i = 0; i < k; i++){
		for(int j = 0; j < k; j++){
			dp[i+1][j] = (dp[i+1][j] + ((1LL * j * dp[i][j])%md) + md)%md;
			dp[i+1][j+1] = (dp[i+1][j+1] + ((1LL * (n-j) * dp[i][j])%md) + md)%md;
		}
	}
	int ans = 0;
	int inv = modpow(m, md-2);
	for(int i = 1; i <= k; i++){
		ans = (ans + ((modpow(inv, i) * 1LL * dp[k][i])%md))%md;
	}
	printf("%d\n", ans);
}

#include <stdio.h>
#include <string.h>

#define N	5000
#define MD	998244353

long long power(int a, int k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k >> 1);
	p = p * p % MD;
	if (k & 1)
		p = p * a % MD;
	return p;
}

int dp[N + 1][N + 1];

void init(int k, int n) {
	int i, j;

	dp[0][0] = 1;
	for (i = 0; i < k; i++)
		for (j = 0; j < k; j++) {
			long long x = dp[i][j];

			if (x == 0)
				continue;
