#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))

#define POS(i, j) ((i) * m + (j))

void run (void) {
  i32 n = read_int();
  i32 m = read_int();
  i32 a = read_int();
  i32 b = read_int();
  i32 *h = ALLOC (n * m, i32);
  h[0] = read_int();
  i32 x = read_int();
  i32 y = read_int();
  i32 z = read_int();
  for (i32 i = 1; i < n * m; ++i) {
    h[i] = ((i64) h[i - 1] * x + y) % z;
  }
  i32 *dp1 = ALLOC (n * m, i32);
  i32 *q = ALLOC (n + m, i32);
  for (i32 i = 0; i < n; ++i) {
    i32 front = 0;
    i32 last = 0;
    q[last++] = 0;
    for (i32 j = 1; j < b; ++j) {
      while (front < last && h[POS(i, q[last - 1])] >= h[POS(i, j)]) --last;
      q[last++] = j;
    }
    dp1[POS(i, 0)] = h[POS(i, q[front])];
    for (i32 j = b; j < m; ++j) {
      if (q[front] == j - b) front++;
      while (front < last && h[POS(i, q[last - 1])] >= h[POS(i, j)]) --last;
      q[last++] = j;
      dp1[POS(i, j - b + 1)] = h[POS(i, q[front])];
    }
  }
  {
    i32 *swap = dp1;
    dp1 = h;
    h = swap;
  }
  i64 ans = 0;
  for (i32 j = 0; j < m - b + 1; ++j) {
    i32 front = 0;
    i32 last = 0;
    q[last++] = 0;
    for (i32 i = 1; i < a; ++i) {
      while (front < last && h[POS(q[last - 1], j)] >= h[POS(i, j)]) --last;
      q[last++] = i;
    }
    ans += h[POS(q[front], j)];
    for (i32 i = a; i < n; ++i) {
      if (q[front] == i - a) front++;
      while (front < last && h[POS(q[last - 1], j)] >= h[POS(i, j)]) --last;
      q[last++] = i;
      ans += h[POS(q[front], j)];
    }
  }
  print_int (ans);
  puts ("");
}

int main (void) {
  run ();
  return 0;
}

