#include <stdio.h>

#define MD	998244353

long long power(int a, long long k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k >> 1);
	p = p * p % MD;
	if (k & 1)
		p = p * a % MD;
	return p;
}

void mult(int aa[][2], int bb[][2], int cc[][2]) {
	int i, j;

	for (i = 0; i < 2; i++)
		for (j = 0; j < 2; j++)
			cc[i][j] = ((long long) aa[i][0] * bb[0][j] + (long long) aa[i][1] * bb[1][j]) % MD;
}

void power_(int aa[][2], int pp[][2], int tt[][2], long long k) {
	if (k == 0) {
		int i, j;

		for (i = 0; i < 2; i++)
			for (j = 0; j < 2; j++)
				pp[i][j] = i == j;
		return;
	}
	if ((k & 1) == 0) {
		power_(aa, tt, pp, k >> 1);
		mult(tt, tt, pp);
	} else {
		power_(aa, pp, tt, k >> 1);
		mult(pp, pp, tt);
		mult(tt, aa, pp);
	}
}

int main() {
	static int aa[2][2], pp[2][2], tt[2][2];
	int n, m, l, r, e, o;

	scanf("%d%d%d%d", &n, &m, &l, &r);
	if ((long long) n * m % 2 != 0) {
		printf("%lld\n", power(r - l + 1, (long long) n * m));
		return 0;
	}
	e = r / 2 - (l - 1) / 2, o = r - l + 1 - e;
	aa[0][0] = e, aa[0][1] = o;
	aa[1][0] = o, aa[1][1] = e;
	power_(aa, pp, tt, (long long) n * m);
	printf("%d\n", pp[0][0]);
	return 0;
}

