	if ((w = (x + r) - n) > 0)
		a -= (long long) w * w;
	if ((w = (y + r) - n) > 0)
		a -= (long long) w * w;
	if ((w = r - 1 - (x - 1) - (y - 1)) > 0)
		a += (long long) w * (w + 1) / 2;
	if ((w = r - 1 - (x - 1) - (n - y)) > 0)
