#define PRAZNO (-1)

typedef struct element {
	int cvor;
	struct element *sledeci;
} Element;

//dodavanje na red
void dodaj(Element **pocetak, Element **kraj, int i) {
	Element *temp;
	temp = (Element *)malloc(sizeof(Element));
	temp->cvor = i;
	temp->sledeci = NULL;
	if (*pocetak==NULL) {
		*pocetak = *kraj = temp;
	}
	else {
		(*kraj)->sledeci = temp;
		*kraj = temp;
	}
}

int skini(Element **pocetak, Element **kraj) {
	int cvor;
	Element *temp;
	if (*pocetak==NULL) {
		return PRAZNO;
	}
	else {
		temp = *pocetak;
		*pocetak = temp->sledeci;
		cvor = temp->cvor;
		if (*kraj==temp) *kraj=NULL;
		free(temp);
		return cvor;
	}
}

void dfs_visit(int graph[][501], int color[], int parent[], char vasyaString[], int n, int *hasSolution, int i, char c, int level) {
