      //  *hasSolution = FALSE;
	int j;
	color[i] = GRAY;
	vasyaString[i] = c;
	for (j=1; j<=n; j++) {
		if (i!=j && graph[i][j]==TRUE && parent[i]!=j)
        {
			if (color[j]==WHITE)
			{
                if (parent[i]==FALSE) {
                    c = 'a';
                    vasyaString[i] = c;
                }
                if (c=='a') c='c';
                else c='a';
                parent[j]=i;
				dfs_visit(graph, color, parent, vasyaString, n, hasSolution, j, c, level+1);
			}
			else if (color[j]==GRAY && abs(vasyaString[i]-vasyaString[j])<2) {
				*hasSolution = FALSE;
			}
		}
	}
	color[i] = BLACK;
}



