#include <stdio.h>

#define N	13
#define Q	1010
#define MD1	998244353
#define MD	1000000007

long long min(long long a, long long b) { return a < b ? a : b; }

long long pp[N + 1], qq[N + 1];

void init() {
	int i;

	pp[0] = qq[0] = 1;
	for (i = 1; i <= N; i++) {
		pp[i] = pp[i - 1] * 10;
		qq[i] = qq[i - 1] + pp[i];
	}
}

long long idx(long long a, long long b) {
	static int aa[N], bb[N];
	static long long aa_[N];
	long long cnt;
	int n, m, i, j, c;

	n = 0;
	while (a > 0)
		aa[n++] = a % 10, a /= 10;
	m = 0;
	while (b > 0)
		bb[m++] = b % 10, b /= 10;
	for (i = 0; i < n; i++)
		aa_[i] = (i == 0 ? 0 : aa_[i - 1]) + aa[i] * pp[i];
	cnt = m;
	for (i = n - 1, j = m - 1, c = 0; j >= 0; i--, j--)
		if (c < 0)
			cnt += qq[n - 1 - (m - 1 - j)] * (bb[j] - (j == m - 1 ? 1 : 0));
		else if (c > 0)
			cnt += (n - 1 - (m - 1 - j) == 0 ? 0 : qq[n - 2 - (m - 1 - j)]) * (bb[j] - (j == m - 1 ? 1 : 0));
		else {
			if (bb[j] <= aa[i]) {
				if (bb[j] < aa[i])
					c = -1;
				cnt += qq[n - 1 - (m - 1 - j)] * (bb[j] - (j == m - 1 ? 1 : 0));
			} else {
				c = 1;
				cnt += qq[n - 1 - (m - 1 - j)] * (aa[i] - (j == m - 1 ? 1 : 0));
				cnt += (n - 1 - (m - 1 - j) == 0 ? 0 : qq[n - 2 - (m - 1 - j)]) * (bb[j] - aa[i]) + (i == 0 ? 0 : aa_[i - 1]) + 1;
			}
		}
	return cnt;
}

int aa[N], bb[N];

long long count_(long long a, long long d) {
	long long b, cnt;

	cnt = 0;
	for (b = 1; b <= a; b++)
		if (idx(a, b) - b >= d)
			cnt++;
	return cnt;
}

long long count(long long a, long long d) {
	int m;
	long long cnt;

	cnt = 0;
	for (m = 1; pp[m - 1] - 1 <= a; m++) {
		long long lower = pp[m - 1] - 1, upper = min(pp[m], a + 1);

		while (upper - lower > 1) {
			long long b = (lower + upper) / 2;

			if (idx(a, b) - b >= d)
				upper = b;
			else
				lower = b;
		}
		cnt += min(pp[m], a + 1) - upper;
	}
	return cnt;
}

int main() {
	long long a, q, ans;

	init();
	scanf("%lld", &a);
	ans = Q * a % MD;
	for (q = -Q + 1; q <= Q; q++)
		ans = (ans - count(a, q * MD1)) % MD;
	ans = ans * MD1 % MD;
	if (ans < 0)
