#include <stdio.h>
const long long MOD = 1e9 + 7;
struct A{int first; int second;};
struct A fibp(long long n) {
    long long a = 1, b = 0;
    long long s = 0, r = 1;
    for ( ; n; n >>= 1) {
        if (n & 1) {
            long long na = (a*s + b*r) % MOD;
            long long nb = (a*r + b*s + b*r) % MOD;
            a = na;
            b = nb;
        }
        long long ns = (s*s + r*r) % MOD;
        long long nr = (2*s*r + r*r) % MOD;
        s = ns;
        r = nr;
    }
    struct A res;
    res.first = a;
    res.second = b;
    return res;
}

int powmod(long long a, long long b) {
    long long r = 1;
    for (a %= MOD; b; b >>= 1) {
        if (b & 1) {
            r *= a;
            r %= MOD;
        }
        a *= a;
        a %= MOD;
    }
    return r;
}

int f(long long n, int k) {
    int A[50];
    for (int i = 0; i <= k; ++i) {
        A[i] = powmod(n + i, k);
    }
    struct A ab = fibp(n + 1);
    int a = ab.first, b = ab.second;
    int r = 0;
    for (int lA = k + 1; lA; --lA) {
        a += b; if (a >= MOD) {a -= MOD;}
        b += a; if (b >= MOD) {b -= MOD;}
        r += (long long)A[0] * a % MOD; if (r >= MOD) {r -= MOD;}
        for (int i = 0; i < lA - 1; ++i) {
            A[i] -= A[i + 1]; if (A[i] < 0) {A[i] += MOD;}
        }
    }
    return r;
}

