long long xy[2];

int gcdxy(int a, int b) {
	if (b == 0) {
		xy[0] = 1, xy[1] = 0;
		return a;
	} else {
		int g = gcdxy(b, a % b);
		int tmp;

		tmp = xy[0] - a / b * xy[1];
		xy[0] = xy[1];
		xy[1] = tmp;
		return g;
	}
}

