void Sieve(){
    int i, j, k;
    setbit(ar, 0), setbit(ar, 1);

    for (i = 3; i < SQR; i++, i++){
        if (!chkbit(ar, i)){
            k = i << 1;
            for (j = (i * i); j < MAX; j += k) setbit(ar, j);
        }
    }

    k = 0, counter[2] = ++k;
    for (i = 3; (i + 1) < MAX; i++, i++){
        if (isprime(i)) k++;
        counter[i] = counter[i + 1] = k;
    }
}

void backtrack(int i, int j){
    if (i > j){
        int x = atoi(str);
        if (x < MAX) P[m++] = x;
        return;
    }

    int k;
    for (k = 0; k < 10; k++){
        if (!i && !k) continue;
        str[i] = str[j] = k + 48;
        backtrack(i + 1, j - 1);
    }
}

void Generate(){
    m = 0;
    int i, j;
    for (i = 1; i <= 7; i++){
        str[i] = 0;
        backtrack(0, i - 1);
    }
}

bool Check(int n, int i){
    long long x = q * counter[n];
    long long y = p * (i + 1);
    return (x <= y);
}

