                low = P[i], high = P[i + 1] - 1;

                while ((low + 1) < high){
                    mid = (low + high) >> 1;
                    if (Check(mid, i)) low = mid;
                    else high = mid;
                }

                if (Check(high, i)) res = high;
                else if (Check(low, i)) res = low;
                if (res != -1) break;
            }
        }

