// chestii invmod
static inline int myExp( int a, int n ){
  int acc = 1;

  while( n > 0 ){
    if( n & 1 )
      acc = multmod(acc, a);
    a = multmod(a, a);
    n >>= 1;
  }

  return acc;
}

static inline int inv( int x ){
  return myExp(x, MOD - 2);
}

int main(){
  int t, n, k, i, big_num, comb, numeq, answer;

  p2[0] = 1;
  for( i = 1 ; i <= MAXK ; i++ )
    p2[i] = multmod(2, p2[i - 1]);

  for( scanf("%d", &t) ; t-- ; ){
    scanf("%d%d", &n, &k);

    // calculam big_num = numarul de moduri de a face o pozitie sa fie egala (and = xor) modificand doar bitii de pe acea pozitie
    // cazul and = xor = 1
    big_num = (n & 1);

    // cazul and = xor = 0
    comb = 1;
    for( i = 0 ; i < n ; i += 2 ){
      big_num = addmod(big_num, comb);
      comb = multmod(comb, multmod(n - i, n - i - 1));
      comb = multmod(comb, multmod(inv(i + 1), inv(i + 2)));
    }

    // simulam
    numeq = 1;// numeq = numarul de moduri de a face primele i cifre egale modificand doar primele i cifre
    answer = 0;
    for( i = 0 ; i < k ; i++ ){
      if( (n & 1) == 0 )// cazul in care pentru bitul i and = 1, xor = 0
        answer = addmod(answer, multmod(numeq, myExp(p2[k - i - 1], n)));// adaugam numarul de posibilitati

      numeq = multmod(numeq, big_num);// actualizam x
    }
    answer = addmod(answer, numeq);// adaugam numarul de cazuri in care e egal ca semnul este >=

    printf("%d\n", answer);
  }

  return 0;
}

