#define ABS(a) ((a)>(0)?(a):-(a))

int64 func(int64 n,int64 b){
  int64 res=0;
  while(n>0){
    res+=n/b;
    n/=b;
  }
  return res;
}

void run(void){
  int64 n=readInt();
  int64 b=readInt();
  int64 ans=n;
  for(int64 k=2;k*k<=b;k++){
    if(b%k!=0) continue;
    int cnt=0;
    do{
      b/=k;
      cnt++;
    } while(b%k==0);
    int64 f=func(n,k)/cnt;
    ans=MIN(ans,f);
  }
  if(b>1){
    ans=MIN(ans,func(n,b));
  }
  printInt(ans);
  putchar('\n');
}

