long long totient(long long n) {
	long long p, x;

	x = n;
	for (p = 2; p * p <= n; p++)
		if (n % p == 0) {
			x = x / p * (p - 1);
			while (n % p == 0)
				n /= p;
		}
	if (n > 1)
		x = x / n * (n - 1);
	return x;
}

