long long foo(const char* str, int base, int len, long long mul, long long bar){
	if(!*str) return bar;
	long long c = 0;
	long long p = 1;
	int i = 0;
	do{
		c += p * (str[i++] - '0');
		p *= 10;
	}while(str[i] && c + p * (str[i] - '0') < base && i < len);
	if(!str[i]) return bar + c * mul;
	if(c != 0){
		str += i - 1;
		while(*str == '0') --str;
	}
	return foo(++str, base, len, mul * base, bar + c * mul);
}

