	scanf("%d%d%d%d", &a, &b, &l, &r);
	l--, r--;
	ab = a + b;
	m = 4;
	h = l / ab;
	r -= h * ab;
	l -= h * ab;
	h = (r - l + 1) / ab;
	if (h > 2)
		r -= (h - 2) * ab;
	d = a > b ? a - b : 1;
	for (h = 0; h < m; h++) {
		for (k = 0; k < a - d; k++)
			cc[h * ab + k] = k;
		for (k = 0; k < d; k++)
			cc[h * ab + a - d + k] = h % 2 == 0 ? a - d + k : a + k;
	}
	min = a + a;
	for (k0 = 1; k0 <= d; k0++) {
