#define N	15
#define K	200000
#define L	19	/* L = ceil(log2(K * 2 + 1)) */
#define N_	(1 << L)
#define MD	998244353

long long power(long long a, int k) {
	long long p = 1;

	while (k) {
		if (k & 1)
			p = p * a % MD;
		a = a * a % MD;
		k >>= 1;
	}
	return p;
}

int vv_[L + 1], *wwu[L + 1], *wwv[L + 1];

void init() {
	int i, l, u, v;

	u = power(3, MD - 1 >> L), v = power(u, MD - 2);
	for (l = L; l > 0; l--) {
		int n = 1 << l, m = n >> 1;

		vv_[l] = power(1 << l, MD - 2);
		wwu[l] = (int *) malloc(m * sizeof *wwu[l]);
		wwv[l] = (int *) malloc(m * sizeof *wwv[l]);
		wwu[l][0] = wwv[l][0] = 1;
		for (i = 1; i < m; i++) {
			wwu[l][i] = (long long) wwu[l][i - 1] * u % MD;
			wwv[l][i] = (long long) wwv[l][i - 1] * v % MD;
		}
		u = (long long) u * u % MD;
		v = (long long) v * v % MD;
	}
	vv_[0] = 1;
}

void ntt_(int *aa, int l, int inverse) {
	if (l) {
		int n = 1 << l, m = n >> 1, *ww = inverse ? wwv[l] : wwu[l], i, j;

		ntt_(aa, l - 1, inverse), ntt_(aa + m, l - 1, inverse);
		for (i = 0; (j = i + m) < n; i++) {
			int a = aa[i], b = (long long) aa[j] * ww[i] % MD;

			if ((aa[i] = a + b) >= MD)
				aa[i] -= MD;
			if ((aa[j] = a - b) < 0)
				aa[j] += MD;
		}
	}
}

void ntt(int *aa, int l, int inverse) {
	int n = 1 << l, i, j;

	for (i = 0, j = 1; j < n; j++) {
		int b = n >> 1, tmp;

		while ((i ^= b) < b)
			b >>= 1;
		if (i < j)
			tmp = aa[i], aa[i] = aa[j], aa[j] = tmp;
	}
	ntt_(aa, l, inverse);
}

void multiply(int *aa, int *bb, int *cc, int n, int m) {
	static int aa_[N_], bb_[N_];
	int n_, l, i;

	l = 0;
	while (1 << l < n + m - 1)
		l++;
	n_ = 1 << l;
	for (i = 0; i < n_; i++) {
		aa_[i] = i < n ? aa[i] : 0;
		bb_[i] = i < m ? bb[i] : 0;
	}
	ntt(aa_, l, 0);
	ntt(bb_, l, 0);
	for (i = 0; i < n_; i++)
		aa_[i] = (long long) aa_[i] * bb_[i] % MD;
	ntt(aa_, l, 1);
	for (i = 0; i < n + m - 1; i++)
		cc[i] = (long long) aa_[i] * vv_[l] % MD;
}

int main() {
	static int dp[N][K + 1], dq[K * 2 + 1];
	int n, c_, k, i, c, x;

	init();
	scanf("%d%d%d", &n, &k, &c_);
	for (c = 0; c <= k; c++)
		dp[0][c] = 1;
	for (i = 0; i < n; i++) {
		multiply(dp[i], dp[i], dq, k + 1, k + 1);
		if (i + 1 == n)
			printf("%d\n", dq[c_]);
		else {
			x = 0;
			for (c = k + 1; c <= k * 2; c++)
				x = (x + dq[c]) % MD;
			for (c = k; c >= 0; c--) {
				x = (x + dq[c]) % MD;
				dp[i + 1][c] = (x + (long long) dq[c] * (k - c)) % MD;
			}
		}
	}
	return 0;
}

