int fact[1000006], wpar[1000006<<1], n, level;

int mul(int a, int b){
  return (a*1ll*b)%MOD;
}

int powmod(int b, int p){
  int t = 1;
  while(p){
    if(p&1)t = mul(t, b);
    b = mul(b, b);
    p>>=1;
  }
  return t;
}

int ncr(int _n, int r){
  return mul(mul(fact[_n], powmod(fact[r], MOD - 2)), powmod(fact[_n - r], MOD - 2));
}

void dfs(int x, int bits){
  if(bits > level) return;
  int l, r;
  l = x<<1;
  r = l|1;
  if(x&1){
    // x is a right child
    wpar[l] = 1;
    wpar[r] = 1^wpar[x]^wpar[l];
  } else {
    // x is a left child
    wpar[r] = 0;
    wpar[l] = 1^wpar[x]^wpar[r];
  }
  dfs(l, bits + 1);
  dfs(r, bits + 1);
}

int getpossib(int lparity){
  int i, rem;
  wpar[2] = lparity;
  wpar[3] = 1^wpar[1]^wpar[2];
  dfs(2, 2);dfs(3, 2);

  rem = n - (1<<level) + 1;

  for(i = (1<<(level - 1));i < (1<<level);i++){
    //    printf("wpar[%d]: %d\n", i, wpar[i]);
    if(i&1){
      if(wpar[i]) return 0;
      rem--;
    } else {
      if(1^wpar[i]) rem--;
    }
  }
  return rem == 0;
}

