long long Veci(long long a,long long b)
{
    if (a>b)
        return a;
    else return b;
}
void swap(long long* a,long long* b)
{
    long long c;
    c=*a;
    *a=*b;
    *b=c;
}
long long Partition(long long *A, long long left, long long right)
{
    long long pivot = A[right], i = left, x;

    for (x = left; x < right; x++){
        if (A[x] <= pivot){
            swap(&A[i], &A[x]);
            i++;
        }
    }

    swap(&A[i], &A[right]);
    return i;
}
void QuickSort(long long Niz[],long long Levo,long long Desno)
{
    if(Levo<Desno)
    {
        long long pos;
        pos=Partition(Niz,Levo,Desno);
        QuickSort(Niz,Levo,pos-1);
        QuickSort(Niz,pos+1,Desno);
    }
}
