#include <stdio.h>
#include <stdlib.h>

#define N	200000
#define L_	19	/* L_ = ceil(log2(N * 2 + 1)) */
#define N_	(1 << L_)
#define MD	998244353

int min(int a, int b) { return a < b ? a : b; }

long long power(long long a, int k) {
	long long p = 1;

	while (k) {
		if (k & 1)
			p = p * a % MD;
		a = a * a % MD;
		k >>= 1;
	}
	return p;
}

int vv[N + 1], ff[N + 1], gg[N + 1], mobius[N + 1];
int *wwu[L_ + 1], *wwv[L_ + 1], vv_[L_ + 1];

void init() {
	int i, j, l, u, v;

	ff[0] = gg[0] = 1;
	for (i = 1; i <= N; i++) {
		vv[i] = i == 1 ? 1 : (long long) vv[i - MD % i] * (MD / i + 1) % MD;
		ff[i] = (long long) ff[i - 1] * i % MD;
		gg[i] = (long long) gg[i - 1] * vv[i] % MD;
	}
	for (i = 2; i <= N; i++) {
		if (mobius[i])
			continue;
		for (j = i; j <= N; j += i)
			mobius[j]++;
	}
	for (i = 2; i <= N / i; i++)
		for (j = i * i; j <= N; j += i * i)
			mobius[j] = -1;
	for (i = 1; i <= N; i++)
		mobius[i] = mobius[i] == -1 ? 0 : (mobius[i] % 2 == 0 ? 1 : -1);
	u = power(3, MD - 1 >> L_), v = power(u, MD - 2);
	for (l = L_; l > 0; l--) {
		int n = 1 << l, m = n >> 1;

		wwu[l] = (int *) malloc(m * sizeof *wwu[l]);
		wwv[l] = (int *) malloc(m * sizeof *wwv[l]);
		wwu[l][0] = wwv[l][0] = 1;
		for (i = 1; i < m; i++) {
			wwu[l][i] = (long long) wwu[l][i - 1] * u % MD;
			wwv[l][i] = (long long) wwv[l][i - 1] * v % MD;
		}
		vv_[l] = power(1 << l, MD - 2);
		u = (long long) u * u % MD, v = (long long) v * v % MD;
	}
	vv_[0] = 1;
}

int choose(int n, int k) {
	return (long long) ff[n] * gg[k] % MD * gg[n - k] % MD;
}

void ntt_(int *aa, int l, int inverse) {
	if (l) {
		int n = 1 << l, m = n >> 1, *ww = inverse ? wwv[l] : wwu[l], i, j;

		ntt_(aa, l - 1, inverse), ntt_(aa + m, l - 1, inverse);
		for (i = 0; (j = i + m) < n; i++) {
			int a = aa[i], b = (long long) aa[j] * ww[i] % MD;

			if ((aa[i] = a + b) >= MD)
				aa[i] -= MD;
			if ((aa[j] = a - b) < 0)
				aa[j] += MD;
		}
	}
}

void ntt(int *aa, int l, int inverse) {
	int n = 1 << l, i, j;

	for (i = 1, j = 0; i < n; i++) {
		int b = n >> 1, tmp;

		while ((j ^= b) < b)
			b >>= 1;
		if (i < j)
			tmp = aa[i], aa[i] = aa[j], aa[j] = tmp;
	}
	ntt_(aa, l, inverse);
}

void multiply(int *aa, int *bb, int n) {
	static int aa_[N_], bb_[N_];
	int n_, l_, i;

	l_ = 0;
	while (1 << l_ < n + n - 1)
		l_++;
	n_ = 1 << l_;
	for (i = 0; i < n_; i++) {
		aa_[i] = i < n ? aa[i] : 0;
		bb_[i] = i < n ? bb[i] : 0;
	}
	ntt(aa_, l_, 0), ntt(bb_, l_, 0);
	for (i = 0; i < n_; i++)
		aa_[i] = (long long) aa_[i] * bb_[i] % MD;
	ntt(aa_, l_, 1);
	for (i = 0; i < n; i++)
		aa[i] = (long long) aa_[i] * vv_[l_] % MD;
}

void inv(int *aa, int *bb, int n) {
	static int aa_[N_], bb_[N_];
	int m, n_, l_, i;

	if (n == 1) {
		bb[0] = 1;
		return;
	}
	m = (n + 1) / 2;
	inv(aa, bb, m);
	l_ = 0;
	while (1 << l_ < n * 2)
		l_++;
	n_ = 1 << l_;
	for (i = 0; i < n_; i++) {
		aa_[i] = i < n ? aa[i] : 0;
		bb_[i] = i < m ? bb[i] : 0;
	}
	ntt(aa_, l_, 0), ntt(bb_, l_, 0);
	for (i = 0; i < n_; i++)
		aa_[i] = bb_[i] * (MD + 2 - (long long) aa_[i] * bb_[i] % MD) % MD;
	ntt(aa_, l_, 1);
	for (i = 0; i < n; i++)
		bb[i] = (long long) aa_[i] * vv_[l_] % MD;
}

void log_(int *aa, int *bb, int n) {
	static int pp[N + 1], qq[N + 1];
	int i;

	for (i = 0; i < n; i++)
		pp[i] = i + 1 == n ? 0 : (long long) aa[i + 1] * (i + 1) % MD;
	inv(aa, qq, n);
	multiply(pp, qq, n);
	for (i = 0; i < n; i++)
		bb[i] = i == 0 ? 0 : (long long) pp[i - 1] * vv[i] % MD;
}

void exp_(int *aa, int *bb, int n) {
	static int aa_[N + 1], bb_[N + 1], cc_[N + 1];
	int m, i;

	if (n == 1) {
		bb[0] = 1;
		return;
	}
	m = (n + 1) / 2;
	exp_(aa, bb, m);
	for (i = 0; i < n; i++)
		bb_[i] = i < m ? bb[i] : 0;
	log_(bb_, cc_, n);
	for (i = 0; i < n; i++)
		aa_[i] = (aa[i] - cc_[i] + MD) % MD;
	aa_[0] = (aa_[0] + 1) % MD;
	multiply(aa_, bb_, n);
	for (i = 0; i < n; i++)
		bb[i] = aa_[i];
}

int bell[N + 1];

void compute_bell() {
	static int aa[N + 1];
	int i;

	for (i = 1; i <= N; i++)
		aa[i] = gg[i];
	exp_(aa, bell, N + 1);
	for (i = 0; i <= N; i++)
		bell[i] = (long long) bell[i] * ff[i] % MD;
}

int sum(int n, int k) {
	static int aa[N + 1], bb[N + 1];
	int i, ans;

	if (k > n)
		return (bell[n] - 1 + MD) % MD;
	for (i = 0; i <= k; i++)
		aa[i] = power(i, n) * gg[i] % MD;
	for (i = 0; i <= k; i++)
		bb[i] = (long long) (i % 2 == 0 ? 1 : MD - 1) * gg[i] % MD;
	multiply(aa, bb, k + 1);
	ans = MD - 1;
	for (i = 0; i <= k; i++)
		ans = (ans + aa[i]) % MD;
	return ans;
}

int main() {
	int n, k, d, ans;

	init();
	scanf("%d%d", &n, &k);
	if (k == 1 || n == 1) {
		printf("1\n");
		return 0;
	}
	compute_bell();
	ans = 0;
	for (d = 1; d < n; d++)
		if (mobius[d])
			ans = (ans + sum((n + d - 1) / d, k) * mobius[d]) % MD;
	if (ans < 0)
		ans += MD;
	printf("%d\n", ans);
	return 0;
}

