		for(j=1;j*j<=x;++j)if(x%j==0)
		{
			if(!G[j])G[j]=i;
			else if(h<j)h=j;
			if(j!=(k=x/j))
			{
				if(!G[k])G[k]=i;
				else if(h<k)h=k;
			}
		}
		set(p,0,i-1,h);
		for(x=A[i],j=1;j*j<=x;++j)if(x%j==0)
		{
			if(F[j]&&F[j]<i)set(p,F[j],i-1,j);
			if(F[k=x/j]&&F[k]<i)set(p,F[k],i-1,k);
		}
		r+=que(p,i==n?1:0,i-2);
	}
	printf("%I64u\n",r);
	return 0;
}

