int n;

double p(double a, double e) {
    return a / e;
}
double q(double a, double b, double c, double d, double e, double f) {
    return (a / d) * (b / e) * (c / f);
}

double solve(int k) {
    const double q3 = q(k, k-1, k-2, n, n-1, n-2);
    const double q0 = q(n-k, n-k-1, n-k-2, n, n-1, n-2);
    const double q1 = 3 / 2. * q(k, n-k, n-k-1, n, n-1, n-2);
    const double q2 = 3 * q(k, k-1, n-k, n, n-1, n-2);
    const double res = q3 + q1 + q2;
    //printf("solve(%d) = %lf\n", k, res);
    //assert(q3 + q0 + 3 / 2. * q1 + 3 * q2 == 1.);
    assert(res >= 0.);
    assert(res <= 1.);
    return res;
}

