				if (d1[ijh_] > d1[ijh] + 1 || (d1[ijh_] == d1[ijh] + 1 && d2[ijh_] > d2[ijh])) {
					if (d1[ijh_] == INF)
						qq[head + cnt++] = ijh_;
					d1[ijh_] = d1[ijh] + 1;
					d2[ijh_] = d2[ijh];
				}
			}
		}
}

void bfs(int i, int j, int h) {
	int nn3, ijh;

	nn3 = n * n * 3;
	for (ijh = 0; ijh < nn3; ijh++)
		d1[ijh] = d2[ijh] = INF;
	head = cnt = 0;
	ijh = (i * n + j) * 3 + h;
	d1[ijh] = d2[ijh] = 0;
	qq[head + cnt++] = ijh;
	while (cnt) {
		int h_, ijh_;

		ijh = qq[cnt--, head++];
		i = ijh / 3 / n; j = ijh / 3 % n, h = ijh % 3;
		for (h_ = 0; h_ < 3; h_++) {
			ijh_ = ijh / 3 * 3 + h_;
			if (d1[ijh_] > d1[ijh] + 1 || (d1[ijh_] == d1[ijh] + 1 && d2[ijh_] > d2[ijh] + 1)) {
				if (d1[ijh_] == INF)
					qq[head + cnt++] = ijh_;
				d1[ijh_] = d1[ijh] + 1;
				d2[ijh_] = d2[ijh] + 1;
			}
		}
		if (h == 0)
			move(kx, ky, i, j, h, 8, 1);
		else if (h == 1)
			move(bx, by, i, j, h, 4, n);
		else
			move(rx, ry, i, j, h, 4, n);
	}
}

