typedef struct {
  int l, r;
} interval;

int max(int x, int y) {
  return x > y ? x : y;
}

int min(int x, int y) {
  return x < y ? x : y;
}

int interval_intersection_length(const interval *a, const interval *b) {
  return max(0, min(a->r, b->r) - max(a->l, b->l) + 1);
}

void extract(const interval *a, interval *a1, interval *a2, int i) {
  int s = 1 << i;
  int x = (a->l + s - 1) >> i << i;
  int y = a->r >> i << i;
  if (x < y) {
    a1->l = a2->l = 1;
    a1->r = a2->r = s - 1;
  } else if (x == y) {
    a1->l = a->l % s;
    if (a1->l == 0) a1->l = s;
    a1->r = s - 1;
    a2->l = 1;
    a2->r = a->r % s;
  } else {
    a1->l = a2->l = a->l % s;
    a1->r = a2->r = a->r % s;
  }
}

int main() {
  int i, ans;
  interval a, b, a1, a2, b1, b2;
  scanf("%d %d %d %d", &a.l, &a.r, &b.l, &b.r);
  ans = 0;
  for (i = 1; i <= 30; i++) {
    extract(&a, &a1, &a2, i);
    extract(&b, &b1, &b2, i);
    ans = max(ans, interval_intersection_length(&a1, &b1));
    ans = max(ans, interval_intersection_length(&a1, &b2));
    ans = max(ans, interval_intersection_length(&a2, &b1));
    ans = max(ans, interval_intersection_length(&a2, &b2));
  }
  printf("%d\n", ans);
  return 0;
}

