long long cprodukt(int x1, int y1, int x2, int y2, int x3, int y3){
	return (x3-x1)*(y2-y1)-(x2-x1)*(y3-y1);
}

bool cross(int g1, int s1, int g2, int s2){
	return (
		cprodukt(x[0][g1], y[0][g1], x[1][s1], y[1][s1], x[0][g2], y[0][g2])
		*
		cprodukt(x[0][g1], y[0][g1], x[1][s1], y[1][s1], x[1][s2], y[1][s2])
		<0)
		&&
		(
		cprodukt(x[0][g2], y[0][g2], x[1][s2], y[1][s2], x[0][g1], y[0][g1])
		*
		cprodukt(x[0][g2], y[0][g2], x[1][s2], y[1][s2], x[1][s1], y[1][s1])
		<0);
}

bool pos(int d){
	if(d==R) return true;
	for(int i=0;i<R;++i){
		if(inuse[i]) continue;
		inuse[i]=true;
		guarding[d]=i;
		for(int j=0;j<d;++j) if(cross(j, guarding[j], d, i)) continue;
		if(pos(d+1)) return true;
		inuse[i]=false;
		guarding[d]=-1;
	}
	return false;
}

