			if ((ans += (long long) dp[i] * dq[i + 1] % MD) >= MD)
				ans -= MD;
	}
	for (j = 0; j < m; j++)
		for (i = 0; i < n; i++)
			xx[j][i] = choose(j + i, i);
	for (i = 1; i < n; i++) {
		x = 0;
		for (j = 0; j < m; j++) {
			if ((x += xx[j][i - 1]) >= MD)
				x -= MD;
			dp[j] = (long long) x * xx[m - 1 - j][i - 1] % MD;
		}
		x = 0;
		for (j = m - 1; j >= 0; j--) {
			if ((x += xx[m - 1 - j][n - i - 1]) >= MD)
				x -= MD;
			dq[j] = (long long) x * xx[j][n - i - 1] % MD;
		}
		for (j = 1; j < m; j++)
			if ((dp[j] += dp[j - 1]) >= MD)
				dp[j] -= MD;
		for (j = 0; j + 2 < m; j++)
			if ((ans += (long long) dp[j] * dq[j + 2] % MD) >= MD)
				ans -= MD;
		x = 0;
		for (j = 0; j < m; j++) {
			if ((x += xx[j][n - i - 1]) >= MD)
				x -= MD;
			dp[j] = (long long) x * xx[m - 1 - j][n - i - 1] % MD;
		}
		x = 0;
		for (j = m - 1; j >= 0; j--) {
			if ((x += xx[m - 1 - j][i - 1]) >= MD)
				x -= MD;
			dq[j] = (long long) x * xx[j][i - 1] % MD;
		}
		for (j = 1; j < m; j++)
			if ((dp[j] += dp[j - 1]) >= MD)
				dp[j] -= MD;
		for (j = 0; j + 2 < m; j++)
			if ((ans += (long long) dp[j] * dq[j + 2] % MD) >= MD)
				ans -= MD;
	}
	printf("%d\n", ans);
	return 0;
