#include <stdio.h>
#include <stdlib.h>

#define N	8

int compare(const void *a, const void *b) {
	long long la = *(long long *) a;
	long long lb = *(long long *) b;

	return la == lb ? 0 : la < lb ? -1 : 1;
}

long long aa[N], aa_[N];
int bb[N], dp[N][1 << (N - 1)];
char pp[N];
int n, ans = 0x3f3f3f3f;

void solve(int i) {
	int j;

	if (i == n) {
		int cnt, sum;

		cnt = 0, sum = 0;
		for (i = 0; i < n; i++) {
			int k;

			if (!pp[i])
				cnt++;
			k = dp[i][bb[i]];
			sum += k == 1 && bb[i] == 0 ? 1 : k + 1;
		}
		if (cnt >= 2)
			sum++;
		if (ans > sum)
			ans = sum;
		return;
	}
	solve(i + 1);
	pp[i] = 1;
	for (j = i + 1; j < n; j++)
		if (aa_[j] % aa[i] == 0) {
			aa_[j] /= aa[i], bb[j] ^= 1 << i;
			solve(i + 1);
			aa_[j] *= aa[i], bb[j] ^= 1 << i;
		}
	pp[i] = 0;
}

int main() {
	int i, j;

	scanf("%d", &n);
	for (i = 0; i < n; i++)
		scanf("%lld", &aa[i]);
	qsort(aa, n, sizeof *aa, compare);
	for (i = 0; i < n; i++) {
		long long a;
		int k, p, b;

		a = aa[i];
		k = 0;
		for (p = 2; p <= a / p; p++)
			while (a % p == 0) {
				k++;
				a /= p;
			}
		if (a > 1)
			k++;
		dp[i][0] = k;
		for (b = 1; b < 1 << i; b++) {
			a = aa[i];
			k = dp[i][0];
			for (j = 0; j < i; j++)
				if ((b & 1 << j)) {
					if (a % aa[j] != 0) {
						k = -1;
						break;
					}
					a /= aa[j];
					k -= dp[j][0];
				}
			dp[i][b] = k;
		}
	}
	for (i = 0; i < n; i++)
		aa_[i] = aa[i];
	solve(0);
	printf("%d\n", ans);
	return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define A	5000
#define N_	(A * 3)
#define INF	0x3f3f3f3f3f3f3f3fLL

long long min(long long a, long long b) { return a < b ? a : b; }

int oo[1 + (N_ - 1) * 2], oj[1 + (N_ - 1) * 2];

int link(int o, int j) {
	static int _ = 1;

	oo[_] = o, oj[_] = j;
	return _++;
}

int count(int n, int p) {
	return n < p ? 0 : n / p + count(n / p, p);
}

int ae[N_], pp[N_], dd[N_], sz[N_], ii[A + 1], n;

void init() {
	static char composite[A + 1];
	static int primes[A + 1];
	int n_, a, b, cnt, i, j;

	for (a = 2; a <= A / a; a++) {
		if (composite[a])
			continue;
		for (b = a * a; b <= A; b += a)
			composite[b] = 1;
	}
	cnt = 0;
	for (a = 2; a <= A; a++)
		if (!composite[a])
			primes[cnt++] = a;
	n_ = 0;
	pp[n_] = -1, dd[n_] = 0;
	ii[1] = n_++;
	for (a = 2; a <= A; a++) {
		int h, d, d_;

		d = 0;
		for (h = 0; h < cnt; h++)
			d += count(a, primes[h]);
		d_ = 0;
		for (h = cnt - 1; h >= 0; h--) {
			d_ += count(a - 1, primes[h]);
			if (a % primes[h] == 0)
				break;
		}
		i = ii[a - 1], j = -1;
		while (1)
			if (dd[i] > d_)
				j = i, i = pp[i];
			else if (dd[i] == d_) {
				pp[n_] = i, dd[n_] = d, n_++;
				ii[a] = n_ - 1;
				break;
			} else {
				int k = n_++;

				pp[k] = i, dd[k] = d_;
				if (j != -1)
					pp[j] = k;
				pp[n_] = k, dd[n_] = d, n_++;
				ii[a] = n_ - 1;
				break;
			}
	}
	for (j = 1; j < n_; j++) {
		i = pp[j];
		ae[i] = link(ae[i], j), ae[j] = link(ae[j], i);
	}
}

long long dfs1(int p, int i) {
	int o;
	long long x;

	x = (long long) sz[i] * dd[i];
	for (o = ae[i]; o; o = oo[o]) {
		int j = oj[o];

		if (j != p) {
			x += dfs1(i, j);
			sz[i] += sz[j];
		}
	}
	return x;
}

long long ans;

void dfs2(int p, int i, long long x) {
	int o;

	ans = min(ans, x);
	for (o = ae[i]; o; o = oo[o]) {
		int j = oj[o];

		if (j != p) {
			int w = abs(dd[i] - dd[j]);

			dfs2(i, j, x - (long long) sz[j] * w + (long long) (n - sz[j]) * w);
		}
	}
}

