#define N	100000
 
int md;
 
long long power(long long a, int k) {
	long long p = 1;
 
	while (k) {
		if (k & 1)
			p = p * a % md;
		a = a * a % md;
		k >>= 1;
	}
	return p;
}
 
int vv[N + 1], ff[N + 1], gg[N + 1];
 
void init() {
	int i;
 
	ff[0] = gg[0] = 1;
	for (i = 1; i <= N; i++) {
		vv[i] = i == 1 ? 1 : (long long) vv[i - md % i] * (md / i + 1) % md;
		ff[i] = (long long) ff[i - 1] * i % md;
		gg[i] = (long long) gg[i - 1] * vv[i] % md;
	}
}
 
int choose(int n, int k) {
	return k < 0 || k > n ? 0 : (long long) ff[n] * gg[k] % md * gg[n - k] % md;
}
 
int aa[N], cnt;
 
void brute(int i, int n) {
	if (i == n) {
		int b, c, d, i, j;
 
		for (b = 0; b < 1 << n; b++) {
			c = (1 << n) - 1;
			for (i = 0; i < n; i++)
				if ((b & 1 << i) != 0) {
					if ((c & 1 << aa[i]) == 0)
						goto out;
					c &= ~(1 << aa[i]);
				}
			for (i = 0; i < n; i++)
				if ((c & 1 << i) != 0 && (c & 1 << aa[i]) != 0)
					goto out;
			c = 0;
			for (i = 0; i < n; i++) {
				if ((c & 1 << i) != 0)
					continue;
				j = i, d = 0;
				while (((c | d) & 1 << j) == 0)
					d |= 1 << j, j = aa[j];
				if ((c & 1 << j) != 0) {
					c |= d;
					continue;
				}
				c |= d, d = 0;
				while ((d & 1 << j) == 0)
					d |= 1 << j, j = aa[j];
				if ((b & d) == d)
					goto out;
			}
			cnt++;
out:;
		}
		return;
	}
	for (aa[i] = 0; aa[i] < n; aa[i]++)
		if (aa[i] != i)
			brute(i + 1, n);
}
 
int slow(int n) {
	int k, l, ans;
 
	ans = 0;
	for (k = 1; k <= n; k++)
		for (l = k; l + k <= n; l++)
			ans = (ans + (long long) choose(n, l + k)
					* ff[l + k] % md
					* gg[k] % md
					* choose(l - 1, k - 1) % md
					* power(n - 1, k) % md
					* power(l, n - l - k)) % md;
	return ans;
}
 
