		for (h = 2; h <= m; h++)
			x = (x + ((long long) sum(h - k, h - 2) * k - sum_(h - k, h - 2)) % md * dp[h]) % md;
		for (i = 0; i < n - k; i++)
			x = (long long) x * (n - i) % md;
		ans = (ans + x) % md;
		for (h = 1; h <= m + k - 1; h++)
			dp[h] = (dp[h] + dp[h - 1]) % md;
		for (h = m + k - 1; h >= k; h--)
			dp[h] = (dp[h] - dp[h - k]) % md;
	}
	if (ans < 0)
		ans += md;
	printf("%d\n", ans);
	return 0;
}

