#include <stdio.h>

long long count2(int h) {
	return h % 2 == 1 ? (long long) (h + 1) / 2 * ((h + 1) / 2 + 1)
		: (long long) (h / 2 + 1) * (h / 2 + 1);
}

long long count1(int h, int r) {
	return count2(h) - (r >= h ? 0 : count2(h - 1 - r));
}

long long count(int h, int k, int r) {
	return count1(h, r) - (k == 0 ? 0 : count1(k - 1, r));
}

long long solve(int a, int b, int c, int h) {
	int k, l, r;

	if (a + 1 > b + c + h)
		return 0;
	k = a + 1 <= b + c ? 0 : a + 1 - (b + c);
	l = 1 - a - (c - b);
	r = a - 1 - (c - b);
	if (l >= 0)
		return count(h, k, r) - (l == 0 ? 0 : count(h, k, l - 1));
	if (r <= 0) {
		r = -r, l = -l;
		return count(h, k, l) - (r == 0 ? 0 : count(h, k, r - 1));
	}
	return count(h, k, -l) + count(h, k, r) - count(h, k, 0);
}

