double noHigherThan(int b) {
    int i, j, f;
    double p = 0.0, p1;
    for(i = 3; i < (1 << n); i++) {
        p1 = 1.0;
        f = 0;
        for(j = 0; j < n; j++) {
            if((i & (1 << j)) > 0) {
                if(!(L[j] <= b && b <= R[j])) {
                    p1 = 0;
                    break;
                }
                p1 *= (1.0 / (R[j] - L[j] + 1));
                f++;
            }
            else {
                if(L[j] >= b) {
                    p1 = 0;
                    break;
                }
                p1 *= ((min(b - 1, R[j]) - L[j] + 1) / (R[j] - L[j] + 1));
            }
        }
        if(f >= 2)
            p = p + p1;
    }
    return p;
}

double oneHigherThan(int b, int x) {
    if(b >= R[x]) return 0.0;
    double p = 0.0, p1;
    int i, j, f;
    for(i = 1; i < (1 << n); i++) {
        p1 = 1.0;
        f = 0;
        for(j = 0; j < n; j++) {
            if(j == x) continue;
            if((i & (1 << j)) > 0) {
                if(!(L[j] <= b && b <= R[j])) {
                    p1 = 0;
                    break;
                }
                p1 *= (1.0 / (R[j] - L[j] + 1));
                f++;
            }
            else {
                if(L[j] >= b) {
                    p1 = 0;
                    break;
                }
                p1 *= ((min(b - 1, R[j]) - L[j] + 1.0) / (R[j] - L[j] + 1.0));
            }
        }
        if(f == 0) p1 = 0;
        p = p + p1;
    }
    p /= 2.0;
    return p * ((R[x] - max(b + 1, L[x]) + 1.0) / (R[x] - L[x] + 1));
}

double P(int b) {
    double p = 0.0;
    p = noHigherThan(b);
    int i;
    for(i = 0; i < n; i++)
        p = p + oneHigherThan(b, i);
    return p;
}

