#include <sys/time.h>

#define N	35
#define N_	((N + 1) / 2)

unsigned int X;

void srand_() {
	struct timeval tv;

	gettimeofday(&tv, NULL);
	X = tv.tv_sec ^ tv.tv_usec | 1;
}

int rand_() {
	return (X *= 3) >> 1;
}

void multiply(char *aa, char *bb, char *md, int n) {
	static char cc[N * 2];
	int i, j;

	memset(cc, 0, n * 2 * sizeof *cc);
	for (i = 0; i < n; i++)
		for (j = 0; j < n; j++)
			if (aa[i] && bb[j])
				cc[i + j] ^= 1;
	for (i = n * 2 - 1; i >= n - 1; i--)
		if (cc[i])
			for (j = 0; j < n; j++)
				if (md[j])
					cc[i - (n - 1 - j)] ^= 1;
	memcpy(aa, cc, n * sizeof *cc);
}

char ppp[1 << N_][N]; int n;

int compare(int i, int j) {
	int c = memcmp(ppp[i], ppp[j], n * sizeof *ppp[j]);

	return c ? c : i - j;
}

void sort(int *ii, int l, int r) {
	while (l < r) {
		int i = l, j = l, k = r, i_ = ii[l + rand_() % (r - l)], tmp;

		while (j < k) {
			int c = compare(ii[j], i_);

			if (c == 0)
				j++;
			else if (c < 0) {
				tmp = ii[i], ii[i] = ii[j], ii[j] = tmp;
				i++, j++;
			} else {
				k--;
				tmp = ii[j], ii[j] = ii[k], ii[k] = tmp;
			}
		}
		sort(ii, l, i);
		l = k;
	}
}

int search(int *ii, int m, char *pp) {
	int lower = -1, upper = m;

	while (upper - lower > 1) {
		int i = (lower + upper) / 2;

		if (memcmp(ppp[ii[i]], pp, n * sizeof *ppp[ii[i]]) >= 0)
			upper = i;
		else
			lower = i;
	}
	return upper < m && memcmp(pp, ppp[ii[upper]], n * sizeof *ppp[ii[upper]]) == 0 ? ii[upper] : -1;
}

int main() {
	static char cc_[N + 1], *cc, md[N], xx[N], vv[N], pp[N], pp_[N];
	static int rr[1 << N_];
	int n_, p, q, r, i, j, one;
	char tmp;

	srand_();
	scanf("%s", cc_), n = strlen(cc_);
	p = 0;
	while (p < n && cc_[p] == '0')
		p++;
	if (p == n) {
		printf("-1\n");
		return 0;
	}
	cc = cc_ + p, n -= p;
	while (cc[n - 1] == '0')
		n--;
	if (n == 1) {
		printf("%d %d\n", p + 1, p + 2);
		return 0;
	}
	n_ = (n + 1) / 2;
	cc[n] = 0;
	for (i = 0, j = n - 1; i < j; i++, j--)
		tmp = cc[i], cc[i] = cc[j], cc[j] = tmp;
	for (i = 0; i < n; i++)
		md[i] = cc[i] - '0';
	for (j = 0; j < n - 1; j++)
		vv[j] = md[j + 1];
	memset(pp, 0, n * sizeof *pp), pp[0] = 1;
	for (r = 0; r < 1 << n_; r++) {
		memcpy(ppp[r], pp, n * sizeof *pp);
		one = 1;
		for (i = 0; i < n; i++)
			if ((pp[i] == 1) != (i == 0)) {
				one = 0;
				break;
			}
		if (one && r != 0) {
			printf("%d %d\n", p + 1, p + 1 + r);
			return 0;
		}
		multiply(pp, vv, md, n);
	}
	for (r = 0; r < 1 << n_; r++)
		rr[r] = r;
	sort(rr, 0, 1 << n_);
	memset(pp_, 0, n * sizeof *pp_), pp_[0] = 1;
	xx[1] = 1, multiply(xx, pp_, md, n);
	for (r = 0; r < 1 << n_; r++)
		multiply(pp_, xx, md, n);
	memset(pp, 0, n * sizeof *pp), pp[0] = 1;
	for (q = 1; q <= 1 << n_; q++) {
		multiply(pp, pp_, md, n);
		if ((r = search(rr, 1 << n_, pp)) != -1) {
			printf("%d %lld\n", p + 1, p + 1 + ((long long) q << n_) + r);
			return 0;
		}
	}
	printf("-1\n");
	return 0;
}

#include<stdio.h>
long long  a[5],ans=1000000000000;
char p[4];
void dfs(int l)
{
    if(l==1)
    {
      long long  s;
        for( int i=1; i<=4; i++)
            if(a[i]!=-1)
            {
                s=a[i];
                break;
            }
        if(s<ans)
            ans=s;
        return;
    }
    for(int i=1; i<=4; i++)
        for( int j=i+1; j<=4; j++)
        {
            int k=4-l+1;
            if(a[i]==-1||a[j]==-1||p[k]=='-')
                continue;
            long long   x=a[i],y=a[j];
            char t=p[k];
            p[k]='-';
            a[j]=-1;
            if(t=='+')
                a[i]=x+y;
            else
                a[i]=x*y;
            dfs(l-1);
            a[i]=x;
            a[j]=y;
            p[k]=t;
        }
}
int main()
{
    for( int i=1; i<=4; i++)
       scanf("%lld",&a[i]);
    for(int i=1; i<=3; i++)
    {
        char c;
        c=getchar();
        if(c=='*'||c=='+')
            p[i]=c;
        else
            i--;
    }
    dfs(4);
    printf("%lld",ans);
    return 0;
}
